{
  "name": "metered-web-broker",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "A neutral one-contract Metered Web Broker: one endpoint returns content + license + settlement receipt. The broker handles the 402s, licenses, identity, budget, and audit.",
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "typecheck": "npm run typecheck --workspaces",
    "test": "vitest run",
    "test:watch": "vitest",
    "demo": "tsx scripts/demo.ts",
    "conformance": "tsx packages/conformance/src/cli.ts"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  }
}

/**
 * A runnable end-to-end demo of the Metered Web Broker.
 *
 * It exercises all four terminal outcomes against the in-memory rail, with
 * a frozen clock and an injected origin client, so it is fully deterministic
 * and needs no network:
 *
 *   1. fulfilled   — a paid fetch, receipt + obligations from a Link header
 *   2. blocked     — budget ceiling exceeded (the first deny-gate)
 *   3. payment-required — origin still demands payment after settlement (402)
 *   4. token-rejected — origin rejects the presented identity (403 + ring)
 *
 * After each, the single audit ledger is rendered so the terminal decision is
 * visible on the audit surface.
 *
 *   npm run demo   (== tsx scripts/demo.ts)
 */

import { frozenClock, formatMicros } from '@mwb/core';
import { Broker } from '@mwb/gateway';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { AuditLedger, renderDashboard } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import { InMemoryRail } from '@mwb/rails';

const clock = frozenClock();

const URL = 'https://api.example.com/wire/42';

/** A configurable-injection OriginClient: returns whatever response we build. */
function originClient(response: {
  httpStatus: number;
  headers?: Record<string, string>;
  body?: string;
}) {
  return {
    fetch: async () => ({
      httpStatus: response.httpStatus,
      headers: response.headers ?? {},
      body: response.body ?? '<html>ok</html>',
    }),
  };
}

/** The L1000/2GB RSL Link header an origin publishes on a fulfilled fetch. */
const LICENSE_LINK =
  '<https://licenses.example/r/73>; rel="type:license-terms"; type="application/vnd.example.l1000+json"';

/** Build a broker wired with a frozen clock and an injected origin. */
function makeBroker(args: {
  rail: ReturnType<typeof inMemory>;
  budget: BudgetEngine;
  ledger: AuditLedger;
  ring?: KeyRing;
  subject?: string;
  resp: { httpStatus: number; headers?: Record<string, string>; body?: string };
}) {
  const { rail, budget, ledger, resp, subject } = args;
  const options: ConstructorParameters<typeof Broker>[0] = {
    rail,
    budget,
    ledger,
    origin: originClient(resp),
    clock,
  };
  if (args.ring) options.ring = args.ring;
  if (subject) options.identity = { subject };
  return new Broker(options);
}

/** A rail that "succeeds" (quote/authorize/settle all pass). */
function inMemory(priceMicros: number) {
  return new InMemoryRail({
    id: 'x402',
    priceMicros,
    currency: defaultPolicy.currency,
    clock,
    settlementSeed: 'demo-seed',
  });
}

/** A rail that fails settlement. */
function failingRail() {
  return new InMemoryRail({
    id: 'x402',
    priceMicros: 5000,
    currency: defaultPolicy.currency,
    clock,
    settlementSeed: 'demo-seed',
    failureMode: 'settle',
  });
}

let seq = 0;
function nextFetchId(): string {
  seq += 1;
  return `demo-fetch-${seq}`;
}

/** Print a terminal outcome's key fields as a short receipt. */
function printOutcome(outcome: Awaited<ReturnType<Broker['fetch']>>, label: string): void {
  console.log(`\n── ${label} ─────────────────────────────────`);
  console.log(`  status    : ${outcome.status}`);
  if (outcome.failureClass) console.log(`  failure   : ${outcome.failureClass}`);
  if (outcome.error) console.log(`  reason    : ${outcome.error.message}`);
  if (outcome.status === 'fulfilled') {
    console.log(`  content   : ${outcome.content?.body}`);
    console.log(`  price     : ${formatMicros(outcome.price?.unitsMicros ?? 0, outcome.price?.currency)}`);
    console.log(`  settlement: ${outcome.settlementRef}`);
    if (outcome.identity) {
      console.log(`  identity  : keyId=${outcome.identity.keyId}`);
      if (outcome.identity.pactToken) console.log(`  pactToken : [${outcome.identity.pactToken.length} chars, PACT-issued]`);
    }
    if (outcome.license) console.log(`  license   : id=${outcome.license.id} (rawSource=${outcome.license.rawSource})`);
    if (outcome.obligations) {
      console.log(`  obligations:`);
      for (const o of outcome.obligations) console.log(`    - ${o.clause} → ${o.kind}: ${o.instruction}`);
    }
  }
}

async function main(): Promise<void> {
  const ledger = new AuditLedger({ clock });

  // 1. Fulfilled — a paid fetch that returns content + an RSL Link header.
  {
    const rail = inMemory(5000);
    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
    const ring = new KeyRing(clock);
    ring.issue({ keyId: 'demo-key' });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      ring,
      subject: 'tenant:demo',
      resp: {
        httpStatus: 200,
        headers: { link: LICENSE_LINK, 'content-type': 'text/markdown' },
        body: '# Headline\nThe wire, paid for.',
      },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '1. FULFILLED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 1: fulfilled'));
  }

  // 2. Blocked — the quote (5000 micros) blows the per-call ceiling (100).
  {
    const rail = inMemory(5000);
    const budget = new BudgetEngine({
      policy: { ...defaultPolicy, perCallCeilingMicros: 100 },
      clock,
    });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      resp: { httpStatus: 200, body: 'never fetched' },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '2. BLOCKED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 2: blocked'));
  }

  // 3. Payment-required — settlement fails on the rail.
  {
    const rail = failingRail();
    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      resp: { httpStatus: 200, body: 'never fetched' },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '3. PAYMENT-REQUIRED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 3: payment-required'));
  }

  // 4. Token-rejected — a 403 from the origin while presenting identity.
  {
    const rail = inMemory(5000);
    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
    const ring = new KeyRing(clock);
    ring.issue({ keyId: 'demo-key' });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      ring,
      subject: 'tenant:demo',
      resp: { httpStatus: 403, body: 'identity rejected' },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '4. TOKEN-REJECTED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 4: token-rejected'));
  }

  // --- summary -----------------------------------------------------------
  console.log('\n' + '═'.repeat(60));
  console.log('SUMMARY');
  console.log(`  total requests : ${ledger.entries.length}`);
  console.log(
    `  fulfilled      : ${
      ledger.entries.filter((e) => e.status === 'fulfilled').length
    }`
  );
  console.log(
    `  denied         : ${ledger.entries.filter((e) => e.status === 'denied').length}`
  );
  const spend = ledger.entries.reduce(
    (sum, e) => sum + (e.priceMicros ?? 0),
    0
  );
  console.log(`  total spend    : ${formatMicros(spend, 'USD')}`);
  console.log('  terminal classes on the audit surface: ' +
    ['fulfilled', 'blocked', 'payment-required', 'token-rejected']
      .map((c) => `${c}=1`)
      .join('  '));
  console.log('═'.repeat(60));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

