import type { Price, Quote } from './amounts.js';

/** A string constrained to a valid absolute URL at construction. */
export type UrlString = string & { readonly __brand: 'UrlString' };

export function url(value: string): UrlString {
  try {
    return new URL(value) as unknown as UrlString;
  } catch (cause) {
    throw new TypeError(`url(): invalid absolute URL: ${value}`, { cause });
  }
}

export type HeaderRecord = Record<string, string>;

/**
 * The three distinct failure classes. Today's agents collapse all of these
 * into a generic fetch failure; the broker reports each separately so the
 * cost decision is visible.
 */
export type FailureClass = 'blocked' | 'payment-required' | 'token-rejected';

export type FetchStatus = 'fulfilled' | 'denied' | 'error';

export interface FetchParams {
  url: UrlString;
  headers?: HeaderRecord;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /** Extra budget context from the caller, merged under broker policy. */
  budgetOverride?: { perCallCeilingMicros?: number; lineItemCeilingMicros?: number };
}

export type RslClauseType =
  | 'attribution'
  | 'no-store'
  | 'no-derivative-works'
  | 'no-commercial-use'
  | 'pay-per-inference'
  | 'redistribution'
  | (string & {});

export type RslClauseValue = 'required' | 'permitted' | 'forbidden' | number;

export interface RslClause {
  type: string;
  value: RslClauseValue;
  params: Record<string, string | number>;
}

/** A parsed Rights Statement Language (RSL) document. */
export interface License {
  draft: string;
  id: string;
  title?: string;
  publishedAt?: string;
  clauses: RslClause[];
  rawSource: string;
}

/**
 * Obligations the broker derives from a license and enforces/surfaces for
 * this particular fetch. Surfaced in the outcome so the caller can comply.
 */
export interface LicenseObligation {
  clause: string;
  kind: 'notice' | 'store-prohibited' | 'inference-budget' | 'forbidden' | 'permitted';
  instruction: string;
  applied?: string;
}

export interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  /** Opaque PACT-style attestation token where the origin accepts one. */
  pactToken?: string;
}

export interface FetchOutcome {
  fetchId: string;
  status: FetchStatus;
  /** Present iff status !== 'fulfilled'. The three distinct failure classes. */
  failureClass?: FailureClass;
  reason: string;
  origin?: { url: string; httpStatus?: number };
  content?: { body: string; contentType: string; storeable: boolean; attributionNotice?: string };
  license?: License;
  obligations?: LicenseObligation[];
  price?: Price;
  quote?: Quote;
  rail?: string;
  settlementRef?: string;
  identity?: IdentityPresentation;
  tenantId?: string;
  timestamps: { startedAt: string; completedAt: string };
  error?: { code: string; message: string };
}

/** A raw ledger row — the audit surface. */
export interface LedgerEntry {
  seq: number;
  fetchId: string;
  tenantId: string;
  url: string;
  status: FetchStatus;
  failureClass?: FailureClass;
  httpStatus?: number;
  priceMicros?: number;
  currency?: string;
  rail?: string;
  licenseId?: string;
  keyId?: string;
  settlementRef?: string;
  startedAt: string;
  completedAt: string;
  recordedAt: string;
}

/**
 * A payment rail: one interface, pluggable backends.
 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
 * The interface is stable; backend field names are not (draft-caveat discipline).
 */
export interface PaymentRequest {
  url: UrlString;
  method: string;
  headers: HeaderRecord;
  contentType?: string;
}

export interface RailAuthorization {
  /** Headers the origin expects on the settled request (e.g. X-PAYMENT). */
  settlementHeaders: HeaderRecord;
  scheme: string;
  payload: string;
}

export interface RailSettlement {
  rail: string;
  settlementRef: string;
  amountMicros: number;
  currency: string;
  settledAt: string;
}

export interface PaymentRail {
  readonly id: string;
  quote(req: PaymentRequest): Promise<Quote>;
  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
}

import { formatMicros } from '@mwb/core';
import type { LedgerEntry } from '@mwb/core';
import { summarize } from './ledger.js';

/**
 * A minimal, dependency-free text dashboard. Deliberately dumb: pipe its
 * output anywhere — CI logs, a status page, an ops channel — and the three
 * failure classes stay visible. The moat is *seeing* these rows, which is
 * what collapses into a generic failure today.
 */
export function renderDashboard(rows: LedgerEntry[], title = 'Metered Web Broker'): string {
  const s = summarize(rows);
  const bar = '─'.repeat(70);
  const lines: string[] = [];
  lines.push(`┌${bar}┐`);
  lines.push(`│ ${title.padEnd(70)} │`);
  lines.push(`└${bar}┘`);
  lines.push(`  total ${s.total}   fulfilled ${s.fulfilled}   denied ${s.denied}`);
  const classes = Object.entries(s.byFailureClass)
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([k, v]) => `${k}=${v}`)
    .join('  ');
  if (classes) lines.push(`  classes  ${classes}`);
  if (s.spendMicros > 0) lines.push(`  spend    ${formatMicros(s.spendMicros)}`);
  lines.push('');

  const cols: Array<[string, (r: LedgerEntry) => string]> = [
    ['seq', (r) => String(r.seq)],
    ['fetch_id', (r) => r.fetchId],
    ['status', (r) => r.status],
    ['class', (r) => r.failureClass ?? '-'],
    ['http', (r) => (r.httpStatus != null ? String(r.httpStatus) : '-')],
    ['price', (r) => (r.priceMicros != null ? formatMicros(r.priceMicros) : '-')],
    ['rail', (r) => r.rail ?? '-'],
  ];
  const widths = cols.map(([label, get]) =>
    Math.max(label.length, ...rows.map((r) => get(r).length))
  );
  const pad = (i: number, t: string) => t.padEnd(widths[i] ?? 0);
  lines.push(cols.map(([label], i) => pad(i, label.toUpperCase())).join('   '));
  lines.push(widths.map((w) => '-'.repeat(w)).join('   '));
  for (const r of rows) lines.push(cols.map(([_l, get], i) => pad(i, get(r))).join('   '));

  return lines.join('\n');
}

import { readFileSync } from 'node:fs';
import { report, run } from './run.js';
import type { ContractCard, ConformanceResult } from './types.js';

/**
 * The entry point CI invokes:
 *
 *   tsx packages/conformance/src/cli.ts <fixturePath> <contractName>
 *
 * Reads + JSON-parses the fixture, resolves the validators by contractName,
 * runs them, reports, and exits 0 on full pass / 1 on any failure.
 */
function main(argv: string[]): number {
  const [fixturePath, contractName] = argv;

  if (!fixturePath || !contractName) {
    console.error('usage: conformance <fixturePath> <contractName>');
    return 1;
  }

  let card: ContractCard;
  try {
    card = JSON.parse(readFileSync(fixturePath, 'utf8')) as ContractCard;
  } catch (cause) {
    console.error(`failed to read fixture "${fixturePath}": ${(cause as Error).message}`);
    return 1;
  }

  const result: ConformanceResult = run(card, contractName);
  report(result);
  return result.pass ? 0 : 1;
}

process.exit(main(process.argv.slice(2)));

import {
  type ContractCard,
  type TerminalKind,
  type ValidationResult,
} from './types.js';

/**
 * The four terminal classes the broker reports. Derived in one place so the
 * identity + audit + contract-shape validators agree on the vocabulary.
 */
const TERMINAL_CLASSES: ReadonlySet<string> = new Set<TerminalKind>([
  'fulfilled',
  'blocked',
  'payment-required',
  'token-rejected',
]);

/** The RSL `rel` the broker reads as the published license-terms link. */
const LICENSE_REL = 'type:license-terms';

/**
 * A single contract-shape helper, factored out so each message is built once.
 */
function result(name: string, ok: boolean, message: string): ValidationResult {
  return { name, ok, message };
}

/**
 * Derive a license id from a Link href the same way the broker's RSL engine
 * does: extract the URL, then take its pathname — not the full href. A bare
 * `/r/73` stays `/r/73`; an absolute `https://licenses.example/r/73` collapses
 * to `/r/73`. Query and hash fragments are dropped, matching the engine's
 * `extractLink`/`slugFromUrl`.
 */
function deriveId(href: string): string {
  const brace = href.match(/<([^>]*)>/);
  const url = brace ? brace[1] : href.split(/\s|;/)[0];
  if (!url) return '';
  try {
    return new URL(url).pathname;
  } catch {
    return url;
  }
}

/** identity — PACT key/pactToken present and structurally consistent. */
function validateIdentity(card: ContractCard): ValidationResult {
  const id = card.identity;

  // Identity is best-effort, never a gate: an absent PACT is valid.
  if (!id || typeof id.keyId !== 'string' || id.keyId.length === 0) {
    return result('identity', true, 'PACT not presented (identity is best-effort, not a gate)');
  }

  // When a PACT is present it must be structured consistently. The broker
  // issues a PACT only when a KeyRing AND an identity.subject are both
  // present — so a subject implies a token, and a token implies a subject.
  const hasSubject = typeof id.subject === 'string' && id.subject.length > 0;
  const hasToken = typeof id.pactToken === 'string' && id.pactToken.length > 0;
  if (hasSubject !== hasToken) {
    return result(
      'identity',
      false,
      'a PACT requires both identity.subject and pactToken ' +
        '(subject present=' + hasSubject + ', token present=' + hasToken + ')',
    );
  }

  return result(
    'identity',
    true,
    'identity PACT consistent (keyId=' +
      id.keyId +
      (id.subject ? ', subject=' + id.subject : '') +
      ')',
  );
}

/** license — RSL Link resolves, obligations derive, id is the pathname. */
function validateLicense(card: ContractCard): ValidationResult {
  // A license surfaces only on a fulfilled outcome; a denied outcome carries
  // none and is not an error.
  if (card.status !== 'fulfilled') {
    return result('license', true, 'denied — no license to validate');
  }

  const license = card.license;
  if (!license) {
    return result('license', false, 'a fulfilled outcome must reference its license terms');
  }
  if (typeof license.id !== 'string' || license.id.length === 0) {
    return result('license', false, 'license id is missing');
  }

  // An RSL `Link` header with rel="type:license-terms" must identify the doc,
  // and the license id must equal the href's pathname, not the full href.
  if (card.linkHref != null && card.linkHref !== '') {
    if (card.linkHref.indexOf(LICENSE_REL) === -1) {
      return result(
        'license',
        false,
        'the RSL Link must carry rel="' +
          LICENSE_REL +
          '" (found: ' +
          card.linkHref +
          ')',
      );
    }
    const derived = deriveId(card.linkHref);
    if (derived !== license.id) {
      return result(
        'license',
        false,
        'license id must equal the Link href pathname (' +
          derived +
          '), not the full href',
      );
    }
  }

  // Obligations derive from the license: clauses present ⇒ obligations present,
  // one per clause; absent ⇒ no obligations.
  const clauseCount = (license.clauses ?? []).length;
  const obligationCount = (card.obligations ?? []).length;
  if (clauseCount > 0 && obligationCount === 0) {
    return result('license', false, 'license clauses present but no obligations were derived');
  }
  if (clauseCount > 0 && obligationCount !== clauseCount) {
    return result(
      'license',
      false,
      'expected one obligation per clause (' +
        clauseCount +
        '), derived ' +
        obligationCount,
    );
  }

  return result(
    'license',
    true,
    'license ' +
      license.id +
      ' (' +
      clauseCount +
      (clauseCount === 1 ? ' clause' : ' clauses') +
      ' → ' +
      obligationCount +
      ' obligation' +
      (obligationCount === 1 ? '' : 's') +
      ')',
  );
}

/** audit/settlement — rows well-formed, the spend sums, valid terminal class. */
function validateSettlement(card: ContractCard): ValidationResult {
  // A denied outcome records no spend: that is correct and passes.
  if (card.status === 'denied') {
    return result('settlement', true, 'denied — no spend recorded');
  }

  // A fulfilled outcome paid: every spend line needs a price + settlement ref,
  // and the sum must reconcile with the recorded price.
  const rows = card.spendLines ?? [];
  if (rows.length === 0) {
    return result('settlement', false, 'a fulfilled outcome has no spend lines');
  }
  if (card.price == null) {
    return result('settlement', false, 'a fulfilled outcome must carry a price');
  }

  const spend: number[] = [];
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    if (row == null || typeof row.priceMicros !== 'number' || Number.isNaN(row.priceMicros)) {
      return result('settlement', false, 'spend line ' + i + ' has a non-numeric priceMicros');
    }
    if (typeof row.settlementRef !== 'string' || row.settlementRef.length === 0) {
      return result(
        'settlement',
        false,
        'spend line ' + i + ' (' + (row.fetchId ?? '#' + i) + ') has no settlementRef',
      );
    }
    spend.push(row.priceMicros);
  }

  const summed = spend.reduce((acc, n) => acc + n, 0);
  if (card.price.unitsMicros !== summed) {
    return result(
      'settlement',
      false,
      'spend line sum ' +
        summed +
        ' != recorded price ' +
        card.price.unitsMicros,
    );
  }

  return result(
    'settlement',
    true,
    'settlement consistent across ' + rows.length + ' line(s), sum ' + summed,
  );
}

/** contract-shape (gateway) — outcome shape, terminal class, denied class. */
function validateContractShape(card: ContractCard): ValidationResult {
  if (card.status === 'fulfilled') {
    // Fulfilled releases content + license + a settlement proof.
    if (!card.content || typeof card.content.body !== 'string') {
      return result('contract-shape', false, 'content block is missing/invalid');
    }
    if (!card.license) {
      return result('contract-shape', false, 'license block is missing');
    }
    if (card.settlementRef == null || card.settlementRef.length === 0) {
      return result('contract-shape', false, 'a fulfilled outcome must carry a settlementRef');
    }
  } else {
    // Denied has no content/license/settlement — it must carry a failureClass.
    if (card.failureClass == null || card.failureClass.length === 0) {
      return result('contract-shape', false, 'a denied outcome must carry a failureClass');
    }
  }

  // The terminal decision must be one of the four classes.
  const terminal = card.status === 'fulfilled' ? 'fulfilled' : card.failureClass;
  if (terminal == null || !TERMINAL_CLASSES.has(terminal)) {
    return result(
      'contract-shape',
      false,
      'decision is not one of the 4 terminal classes: ' + JSON.stringify(terminal),
    );
  }

  return result(
    'contract-shape',
    true,
    'contract shape OK (' +
      (card.status === 'fulfilled' ? 'fulfilled' : card.failureClass) +
      ')',
  );
}

/** A conformance validator: one named predicate over the contract card. */
export type ValidatorFn = (card: ContractCard) => ValidationResult;

/**
 * The four validators, keyed to the public one-contract surface. Each reads
 * the card as plain data — no broker internals are imported.
 */
export const VALIDATORS: ReadonlyArray<[string, ValidatorFn]> = [
  ['identity', validateIdentity],
  ['license', validateLicense],
  ['settlement', validateSettlement],
  ['contract-shape', validateContractShape],
];

import { registry } from './registry.js';
import {
  type ContractCard,
  type ConformanceResult,
  type ValidationResult,
} from './types.js';

/** ANSI helpers for the terminal PASS/FAIL summary. */
const CONFORMANCE_OK = '\x1B[32m'; // green
const CONFORMANCE_WARN = '\x1B[31m'; // red
const RESET = '\x1B[0m';

/**
 * Run every registered validator over a card.
 *
 * Each validator's result is collected; `pass` is true only when every
 * validator returned ok.
 */
export function run(card: ContractCard, contractName: string): ConformanceResult {
  const results: ValidationResult[] = [];
  for (const name of registry.names()) {
    results.push(registry.get(name)(card));
  }
  return {
    contract: card,
    contractName,
    results,
    pass: results.every((r) => r.ok),
  };
}

/**
 * Render a green/red PASS/FAIL summary to stdout. Each of the four validators
 * gets a line; a single failure is enough to flip the whole gate to red.
 */
export function report(result: ConformanceResult): void {
  const bar = '\u2500'.repeat(64);
  const line = (text: string) => console.log(text);

  line('');
  line(bar);
  line(`  conformance · ${result.contractName}`);
  line(bar);

  for (const r of result.results) {
    const tick = r.ok ? '✓' : '✗';
    const colour = r.ok ? CONFORMANCE_OK : CONFORMANCE_WARN;
    line(`  ${colour}${tick}${RESET}  ${r.name.padEnd(14)} ${r.message}`);
  }

  line(bar);
  const verdict = result.pass ? 'PASS' : 'FAIL';
  const verdictColour = result.pass ? CONFORMANCE_OK : CONFORMANCE_WARN;
  const failed = result.results.filter((r) => !r.ok).length;
  line(`  ${verdictColour}${verdict}${RESET}  — ${result.results.length} validators, ${failed} failed`);
  line('');
}

export { VALIDATORS, registry } from './registry.js';
export { Registry } from './registry.js';
export { run, report } from './run.js';
export type {
  ContractCard,
  SpendLineCard,
  IdentityCard,
  LicenseCard,
  LicenseClauseCard,
  TerminalKind,
  ValidationResult,
  ConformanceResult,
  ValidatorFn,
} from './types.js';

import {
  type ValidatorFn,
  VALIDATORS,
} from './validators.js';

export { type ValidatorFn, VALIDATORS };

/**
 * The registry of named conformance validators. Each validator is keyed by the
 * name the CLI and fixtures refer to; a lookup by name lets an unknown contract
 * name fail fast instead of silently validating against the wrong ruleset.
 */
export class Registry {
  private readonly map = new Map<string, ValidatorFn>();

  constructor(validators: readonly [string, ValidatorFn][] = VALIDATORS) {
    for (const [name, fn] of validators) {
      if (this.map.has(name)) {
        throw new Error(`duplicate validator registered: ${name}`);
      }
      this.map.set(name, fn);
    }
  }

  /** Whether a validator with this name exists. */
  has(name: string): boolean {
    return this.map.has(name);
  }

  /** Look up a validator by name, or throw a typed error if it is unknown. */
  get(name: string): ValidatorFn {
    const fn = this.map.get(name);
    if (!fn) {
      throw new Error(`unknown contract name: ${name}`);
    }
    return fn;
  }

  /** All registered validator names, in registration order. */
  names(): string[] {
    return [...this.map.keys()];
  }
}

/** The default registry built from the four contract validators. */
export const registry = new Registry();

/**
 * The public "one contract" surface, as a standalone card.
 *
 * The broker's single endpoint returns exactly { content, license, settlement
 * receipt } and every terminal decision decodes to one of four classes. This
 * module names that shape so the four validators below can validate a card
 * against it without importing any broker internals.
 *
 * The card is intentionally a superset of FetchOutcome: the audit row records
 * the subset of the outcome the ledger cares about (price + settlementRef), so
 * the card carries those too. The identity claim mirrors
 * IdentityPresentation — the shape the broker surfaces when a KeyRing AND an
 * identity.subject are both present.
 */

/** The four terminal classes the broker reports on the audit surface. */
export type TerminalKind =
  | 'fulfilled'
  | 'blocked'
  | 'payment-required'
  | 'token-rejected';

/** An RSL clause as the broker's license engine normalises it (draft field names). */
export interface LicenseClauseCard {
  type: string;
  value?: string | number | boolean;
  params?: Record<string, string | number>;
}

/** A license terms document, as surfaced on a fulfilled outcome. */
export interface LicenseCard {
  id: string;
  draft?: string;
  title?: string;
  clauses?: LicenseClauseCard[];
}

/**
 * An identity claim: what the broker records when a KeyRing is present and a
 * subject is known. `keyId` identifies the active key; `pactToken` is the
 * optional PACT attestation the origin may verify (present iff a subject was
 * issued).
 */
export interface IdentityCard {
  keyId: string;
  subject?: string;
  pactToken?: string;
}

/** One spend line in the settlement receipt. */
export interface SpendLineCard {
  fetchId: string;
  priceMicros: number;
  settlementRef: string;
}

/** A broker audit card — the public one-contract shape, in record form. */
export interface ContractCard {
  fetchId: string;
  status: 'fulfilled' | 'denied';
  failureClass?: TerminalKind;
  reason: string;
  content?: {
    body: string;
    contentType: string;
    storeable: boolean;
  };
  license?: LicenseCard;
  obligations?: Array<{ clause: string; kind: string; instruction: string }>;
  price?: { unitsMicros: number; currency: string };
  identity?: IdentityCard;
  /** The RSL `Link` header (or bare href) identifying the license, if any. */
  linkHref?: string | null;
  /** The top-level settlement ref, present iff the outcome is fulfilled. */
  settlementRef?: string | null;
  spendLines: SpendLineCard[];
  timestamps: { startedAt: string; completedAt: string };
}

/** The result of a single validator over the card. */
export interface ValidationResult {
  name: string;
  ok: boolean;
  message: string;
}

/** The full conformance outcome for one card. */
export interface ConformanceResult {
  contract: ContractCard;
  contractName: string;
  results: ValidationResult[];
  pass: boolean;
}

/** A named validator. */
export type ValidatorFn = (card: ContractCard) => ValidationResult;

/**
 * A typed error carrying the failing validator name, so the CLI can print a
 * clean "validator X failed: message" line instead of an uncaught throw.
 */
export class ConformanceError extends Error {
  readonly name: string;
  constructor(name: string, message: string) {
    super(message);
    this.name = name;
  }
}

