/**
 * A thin HTTP entrypoint for the Metered Web Broker — one endpoint, one contract.
 *
 * The `Broker` is a library (see `packages/gateway/src/broker.ts`); nothing in
 * the repo previously bound a socket. This file is the only "web" layer: it
 * wires a `Broker` from environment config, serves `GET /health` and `GET /`,
 * mounts the metered `POST /fetch`, and exposes the audit ledger at `GET /audit`.
 *
 * It uses Node's built-in `http` module (no Express) so the production image is
 * small and cold-start cheap — one Node process, no PaaS, exactly what the VPS
 * deploy targets. The broker's orchestration is reused untouched.
 *
 *   # run it (TS directly)
 *   npx tsx packages/gateway/src/server.ts
 *   # or, in the image
 *   npm start
 *
 *   curl -s localhost:8787/health
 *   curl -s localhost:8787/fetch -XPOST -H'content-type: application/json' \
 *       -d '{"url":"https://api.example.com/wire/42"}'
 *   curl -s localhost:8787/audit
 */

import {
  createServer,
  type IncomingMessage,
  type Server,
  type ServerResponse,
} from 'node:http';
import { Broker } from './broker.js';
import { BudgetEngine, defaultPolicy, type BudgetPolicy } from '@mwb/budget';
import { AuditLedger, reconcile, renderDashboard, summarize } from '@mwb/audit';
import { KeyRing } from '@mwb/identity';
import { InMemoryRail } from '@mwb/rails';
import {
  systemClock,
  url as brandUrl,
  type Clock,
  type HeaderRecord,
  type PaymentRail,
  type PaymentRequest,
  type UrlString,
} from '@mwb/core';
import type { OriginClient, OriginResponse } from './broker.js';

/** The port the HTTP server binds. Defaults to 8787 for a small VPS. */
export const PORT = Number(process.env.PORT ?? 8787);

/** Host/interface to bind. Default: all interfaces (Caddy fronts it in prod). */
export const HOST = process.env.HOST ?? '0.0.0.0';

/**
 * A metered origin client. Two modes:
 *
 *  - `ORIGIN_URL` unset (default): a self-fulfilling origin. Every settled
 *    request returns HTTP 200 with synthetic body + no license. This lets the
 *    broker run `fulfilled` end-to-end with no real origin behind it — the
 *    whole metered path (quote → authorize → settle → record) executes.
 *  - `ORIGIN_URL` set: the settled request is proxied to that URL over HTTP.
 *    This is the path to a real metered origin (self 402, x402, Cloudflare PPC).
 */
export class MeteredOrigin implements OriginClient {
  private readonly target?: UrlString;

  constructor(target?: UrlString) {
    this.target = target;
  }

  async fetch(req: PaymentRequest): Promise<OriginResponse> {
    if (this.target) {
      const res = await fetch(this.target, {
        method: req.method,
        headers: req.headers,
      });
      return {
        httpStatus: res.status,
        headers: headerRecord(res),
        body: await res.text(),
      };
    }
    // Self origin: nothing behind the broker, so report satisfied.
    return {
      httpStatus: 200,
      headers: { 'content-type': 'text/plain; charset=utf-8' },
      body: 'metered content from a self-hosted origin (ORIGIN_URL unset)',
    };
  }
}

/** Build the Rail from env. Today: InMemoryRail (the self 402-style backend). */
export function buildRail(clock: Clock): PaymentRail {
  const id = process.env.RAIL_ID ?? 'self402';
  // A price of 5000 micros (0.005) is comfortably under the per-call ceiling
  // (10_000) so the default self-origin fetch reaches the fulfilled terminal.
  const priceMicros = Number(
    process.env.RAIL_PRICE_MICROS ?? 5000,
  );
  return new InMemoryRail({
    id,
    priceMicros,
    currency: defaultPolicy.currency,
    clock,
    settlementSeed: process.env.RAIL_SETTLEMENT_SEED ?? 'self',
  });
}

/** Parse budget policy from env, overriding just the per-call ceiling. */
function buildPolicy(): BudgetPolicy {
  const policy: BudgetPolicy = { ...defaultPolicy };
  const ceiling = process.env.PER_CALL_CEILING_MICROS;
  if (ceiling && Number.isFinite(Number(ceiling))) {
    policy.perCallCeilingMicros = Number(ceiling);
  }
  return policy;
}

/**
 * Build the full broker from env. Every collaborator is injected exactly as the
 * broker unit tests do, so the wiring here is the same one the test proves.
 *
 * Returns the broker alongside the small bits of state the HTTP layer needs to
 * shape responses (the audit ledger, the origin mode, whether identity is on)
 * so `createApp` never reaches into broker internals.
 */
export function buildBroker(): {
  broker: Broker;
  ledger: AuditLedger;
  origin: MeteredOrigin;
  originTarget?: UrlString;
  identityOn: boolean;
} {
  const clock: Clock = systemClock;
  const ledger = new AuditLedger({ clock });
  const origin = new MeteredOrigin(process.env.ORIGIN_URL ? brandUrl(process.env.ORIGIN_URL) : undefined);
  const ring = process.env.IDENTITY_KEY_ID ? new KeyRing(clock) : undefined;
  const identityOn = ring !== undefined;
  const broker = new Broker({
    rail: buildRail(clock),
    budget: new BudgetEngine({ clock, policy: buildPolicy() }),
    ledger,
    ring,
    origin,
    clock,
    identity: identityOn
      ? { subject: process.env.IDENTITY_SUBJECT }
      : undefined,
  });
  return {
    broker,
    ledger,
    origin,
    originTarget: process.env.ORIGIN_URL ? brandUrl(process.env.ORIGIN_URL) : undefined,
    identityOn,
  };
}

/** Read the whole request body as text. */
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString('utf-8');
}

/** A plain object from an HTTP response's headers (Node Headers → record). */
function headerRecord(res: Response): HeaderRecord {
  const out: HeaderRecord = {};
  res.headers.forEach((v, k) => {
    out[k] = v;
  });
  return out;
}

/** Send a JSON response with status and Content-Type. */
function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const raw = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(raw);
}

/** One metered request, decoded from the request body. */
export interface FetchRequest {
  /** The absolute URL of the metered content to fetch. */
  url: UrlString;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /**
   * Optional `fetchId`. Absent ⇒ the broker derives one. Present ⇒ idempotent
   * (a repeat id returns the cached outcome without re-charging the meter).
   */
  fetchId?: string;
  /** Optional headers to present to the origin on the settled request. */
  headers?: HeaderRecord;
}

/**
 * Handle `POST /fetch`. Decodes the request, runs `Broker.fetch`, and maps the
 * broker's terminal outcome to a JSON response. Every broker terminal class is
 * one of {fulfilled, blocked, payment-required, token-rejected}; there is no
 * generic `error` status.
 */
export async function handleFetch(
  broker: Broker,
  raw: string,
): Promise<{ status: number; body: unknown }> {
  let req: FetchRequest;
  try {
    req = JSON.parse(raw) as FetchRequest;
  } catch {
    return { status: 400, body: { error: 'invalid JSON body' } };
  }
  if (!req || typeof req.url !== 'string') {
    return { status: 400, body: { error: "missing required string field 'url'" } };
  }

  const outcome = await broker.fetch({
    url: req.url,
    fetchId: req.fetchId,
    tenantId: req.tenantId,
    headers: req.headers as HeaderRecord | undefined,
  });

  // A fulfilled metered fetch succeeds (200). Otherwise map the terminal class
  // to an HTTP status agents can branch on: payment-required (402) for any
  // metered-charge gate, and 403 for the rest (blocked, token-rejected, error).
  const status =
    outcome.status === 'fulfilled'
      ? 200
      : outcome.failureClass === 'payment-required'
        ? 402
        : 403;
  return { status, body: outcome };
}

/** Handle `GET /health` — liveness, no dependencies. */
export function handleHealth(): { status: number; body: unknown } {
  return { status: 200, body: { status: 'ok', clock: systemClock.now() } };
}

/** Handle `GET /audit` — JSON: the latest ledger rows. */
export function handleAudit(ledger: AuditLedger): { status: number; body: unknown } {
  const rows = ledger.toRows();
  return { status: 200, body: { rows, summary: summarize(rows) } };
}

/** Handle `GET /audit/dashboard` — the reconciliation dashboard as text. */
export function handleAuditDashboard(ledger: AuditLedger): {
  status: number;
  body: unknown;
} {
  const rows = ledger.toRows();
  const dashboard = renderDashboard(rows, 'Metered Web Broker');
  const recon = reconcile(rows);
  return {
    status: 200,
    body: { dashboard, reconciliation: recon, count: rows.length },
  };
}

/** Handle `GET /` — a small JSON index of the endpoints. */
export function handleIndex(): { status: number; body: unknown } {
  return {
    status: 200,
    body: {
      service: 'metered-web-broker',
      endpoints: {
        'GET /': 'this index',
        'GET /health': 'liveness',
        'POST /fetch': '{"url", fetchId?, tenantId?}',
        'GET /audit': 'latest ledger rows + summary',
        'GET /audit/dashboard': 'reconciliation dashboard',
      },
    },
  };
}

/**
 * Create (but do not start) the HTTP server. Exposed so the test can bind an
 * ephemeral port without opening a real socket in the module.
 */
export interface ServerConfig {
  broker: Broker;
  ledger: AuditLedger;
  origin: MeteredOrigin;
  /** The proxied-origin URL, if ORIGIN_URL was set; else undefined (self origin). */
  originTarget?: UrlString;
}

/**
 * Create (but do not start) the HTTP server. Exposed so the test can bind an
 * ephemeral port without opening a real socket in the module.
 */
export function createApp(cfg: ServerConfig): Server {
  const { ledger, origin, originTarget, broker } = cfg;

  const server = createServer((req, res) => {
    const url = req.url ?? '/';
    const method = req.method ?? 'GET';

    if (method === 'GET' && url === '/health') {
      const { status, body } = handleHealth();
      return void sendJson(res, status, body);
    }
    if (method === 'GET' && url === '/') {
      const { status, body } = handleIndex();
      return void sendJson(res, status, body);
    }
    if (method === 'GET' && url === '/audit/dashboard') {
      const { status, body } = handleAuditDashboard(ledger);
      return void sendJson(res, status, body);
    }
    if (method === 'GET' && url === '/audit') {
      const { status, body } = handleAudit(ledger);
      return void sendJson(res, status, body);
    }
    if (method === 'POST' && url === '/fetch') {
      void (async () => {
        try {
          const raw = await readBody(req);
          const { status, body } = await handleFetch(broker, raw);
          return void sendJson(res, status, body);
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          // A failure *inside* the server (not the metered path) is a 500; the
          // metered path never produces a generic error status.
          return void sendJson(res, 500, { error: 'server error', message });
        }
      })();
      return;
    }

    // Unknown route.
    const { status, body } = {
      status: 404,
      body: {
        error: 'not found',
        path: url,
        endpoints: ['/', '/health', '/fetch', '/audit', '/audit/dashboard'],
      },
    };
    return void sendJson(res, status, body);
  });

  // Log the effective origin mode (self-origin or proxied) at boot.
  server.on('listening', () => {
    // eslint-disable-next-line no-console
    console.log(
      `metered-web-broker listening on http://${HOST}:${PORT}` +
        (originTarget ? `  (origin → ${originTarget})` : '  (self origin)'),
    );
  });

  return server;
}

/** Start the HTTP server from env and listen. */
export function start(): Server {
  const cfg = buildBroker();
  const server = createApp(cfg);
  server.listen(PORT, HOST);
  return server;
}

// Only start when run directly (not when imported by the test).
const isMain =
  process.argv[1] &&
  process.argv[1].endsWith('server.ts') &&
  (process.argv[1].endsWith('src/server.ts') || process.argv[1].endsWith('server.js'));

if (isMain) {
  start();
}

import {
  RailError,
  makeSettlementRef,
  type Clock,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type Micros,
} from '@mwb/core';

/**
 * A rail is a backend: quote → authorize → settle, all behind one
 * interface. Field names inside `payload` are intentionally opaque — the
 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
 * finalized), so the broker never parses them. Draft-caveat discipline:
 * build against the interface, not a draft's field names.
 */
export interface RailBackend extends PaymentRail {}

/**
 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
 * (micro-unit price, `X-PAYMENT` header) without an external service.
 * Deterministic: with a `frozenClock` and fixed input, the settlement
 * reference is stable so reconciliation can be asserted.
 */
export class InMemoryRail implements PaymentRail {
  readonly id: string;
  readonly priceMicros: Micros;
  readonly currency: string;
  readonly clock: Clock;
  private readonly settlementSeed: string = '';
  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';

  constructor(options: {
    id: string;
    priceMicros: Micros;
    currency?: string;
    clock?: Clock;
    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    /** Stable suffix seed so settlement refs are deterministic in tests. */
    settlementSeed?: string;
  }) {
    this.id = options.id;
    this.priceMicros = options.priceMicros;
    this.currency = options.currency ?? 'USD';
    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    this.failureMode = options.failureMode ?? 'none';
    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
  }

  quote(_req: PaymentRequest): Promise<Quote> {
    if (this.failureMode === 'quote') {
      return Promise.reject(
        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
      );
    }
    const nowMs = Date.parse(this.clock.now());
    return Promise.resolve({
      unitsMicros: this.priceMicros,
      currency: this.currency,
      rail: this.id,
      settlement: 'immediate',
      expiresAt: new Date(nowMs + 60_000).toISOString(),
    });
  }

  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    if (this.failureMode === 'authorize') {
      return Promise.reject(
        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
      );
    }
    const payload = JSON.stringify({
      schema: 'urn:rail:' + this.id,
      amountMicros: quote.unitsMicros,
      currency: quote.currency,
      url: String(req.url),
      method: req.method,
    });
    return Promise.resolve({
      scheme: this.id,
      payload,
      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    });
  }

  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    if (this.failureMode === 'settle') {
      return Promise.reject(
        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
      );
    }
    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    return Promise.resolve({
      rail: this.id,
      // Deterministic from (seed, url) so tests can assert reconciliation.
      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
      amountMicros: parsed.amountMicros,
      currency: parsed.currency,
      settledAt: this.clock.now(),
    });
  }
}

/** Self-hosted 402 rail: same interface, different origin. */
export class SelfHosted402Rail extends InMemoryRail {
  constructor(options: { priceMicros: Micros; clock?: Clock; tenantId?: string }) {
    super({
      id: 'self402',
      priceMicros: options.priceMicros,
      clock: options.clock,
      settlementSeed: `self402-${options.tenantId ?? 'tenant'}`,
    });
    this._tenantId = options.tenantId;
  }
  private _tenantId?: string;
  tenantId(): string | undefined {
    return this._tenantId;
  }
}

/**
 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
 * only this minimal shape — it does not depend on the bridge's own types.
 * That is the "one contract" boundary in practice.
 */
export interface BridgeClientShape {
  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
  authorize(input: {
    url: string;
    method: string;
    headers: Record<string, string>;
    quote: { unitsMicros: number; currency: string };
  }): Promise<RailAuthorization>;
  settle(input: {
    url: string;
    method: string;
    headers: Record<string, string>;
    authorization: RailAuthorization;
  }): Promise<RailSettlement>;
}

export class BridgeRail implements PaymentRail {
  constructor(
    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
  ) {}

  get id(): string {
    return this.idAndBridge.id;
  }

  quote(req: PaymentRequest): Promise<Quote> {
    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
  }

  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    return this.idAndBridge.bridge.authorize({
      url: String(req.url),
      method: req.method,
      headers: req.headers,
      quote: { unitsMicros: quote.unitsMicros, currency: quote.currency },
    });
  }

  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    return this.idAndBridge.bridge.settle({
      url: String(req.url),
      method: req.method,
      headers: req.headers,
      authorization,
    });
  }
}

/** Registry lets the broker pick a rail per URL/tenant without touching the agent. */
export class RailRegistry {
  private readonly rails = new Map<string, PaymentRail>();

  register(rail: PaymentRail): this {
    if (this.rails.has(rail.id)) {
      throw new RailError(`Rail already registered: ${rail.id} (deregister first)`, 'RAIL_REGISTER');
    }
    this.rails.set(rail.id, rail);
    return this;
  }

  deregister(id: string): boolean {
    return this.rails.delete(id);
  }

  get(id: string): PaymentRail {
    const r = this.rails.get(id);
    if (!r) throw new RailError(`No rail registered: ${id}`, 'RAIL_MISSING');
    return r;
  }

  /** Look up a rail by id without throwing when it is absent. */
  optional(id: string): PaymentRail | undefined {
    return this.rails.get(id);
  }

  ids(): string[] {
    return [...this.rails.keys()].sort();
  }
}

/** Deterministic PRNG from a seed (FNV-1a based) so settlement refs are stable in tests. */
function deterministicRand(seed: string): () => number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return () => {
    h += 0x6d2b79f5;
    let t = h;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

{
  "name": "@mwb/gateway",
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "start": "tsx src/server.ts"
  },
  "description": "The Broker.fetch orchestrator: composes budget, rail, identity, license, and audit into one contract.",
  "main": "src/index.ts",
  "types": "src/index.ts",
  "dependencies": {
    "@mwb/core": "0.1.0",
    "@mwb/budget": "0.1.0",
    "@mwb/rails": "0.1.0",
    "@mwb/identity": "0.1.0",
    "@mwb/audit": "0.1.0",
    "@mwb/license": "0.1.0"
  },
  "peerDependencies": {
    "typescript": ">=5"
  }
}

import {
  BudgetError,
  IdentityError,
  PaymentRequiredError,
  RailError,
  isBrokerError,
  makeFetchId,
  systemClock,
  type Clock,
  type FetchOutcome,
  type FailureClass,
  type HeaderRecord,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type UrlString,
} from '@mwb/core';
import { BudgetEngine } from '@mwb/budget';
import { AuditLedger } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import {
  deriveObligations,
  parseLicense,
  resolveStoreability,
} from '@mwb/license';

/**
 * The Metered Web Broker orchestrator — the "one contract" call.
 *
 * `Broker.fetch` composes the budget gate, the payment rail, best-effort
 * identity, the license engine, and the audit ledger into a single terminal
 * outcome. The whole thing is designed around one invariant:
 *
 *   every terminal path is one of {fulfilled, blocked, payment-required,
 *   token-rejected} — `error` status is deliberately NOT produced, because a
 *   generic failure hides the cost decision.
 *
 * Pipeline:
 *
 *   1. rail.quote(request)        → quote (the origin's price)
 *   2. budget.preflight(quote)    → `blocked`        if policy denies it
 *   3. rail.authorize(quote)      → `payment-required` if the rail can't pay
 *   4. rail.settle(auth)          → `payment-required` if settlement fails
 *   5. identity.bestEffortSign    → recorded, never a gate
 *   6. origin.fetch(…, settlement) → fulfilled / 402 → payment-required /
 *                                  403 + identity → token-rejected /
 *                                  403 no identity → blocked / else → blocked
 *   7. license.parse + derive from the origin's RSL `Link` header
 *
 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
 * exactly one `AuditLedger` row is recorded for the `fetchId`.
 */

/** The content/SLA source the rail's settled request is sent to. */
export interface OriginResponse {
  httpStatus: number;
  headers: HeaderRecord;
  body: string;
}

export interface OriginClient {
  fetch(req: PaymentRequest): Promise<OriginResponse>;
}

export interface BrokerIdentityOptions {
  /** Subject/tenant to embed in the PACT, if a ring is present and a subject is known. */
  subject?: string;
}

export interface BrokerOptions {
  rail: PaymentRail;
  budget: BudgetEngine;
  ledger: AuditLedger;
  /** Identity vault. Absent ⇒ no identity presented (a 403 then reads as `blocked`). */
  ring?: KeyRing;
  /** Content/SLA source. Required — this is what the broker is metered to fetch. */
  origin: OriginClient;
  clock?: Clock;
  identity?: BrokerIdentityOptions;
  /** Extra headers presented on every origin fetch. Never secrets. */
  headers?: HeaderRecord;
}

/** The broker's terminal decision, decoded by the audit layer and agents. */
export type TerminalKind = 'fulfilled' | 'blocked' | 'payment-required' | 'token-rejected';

/**
 * The Broker. One call composes the whole metered-web decision stack.
 *
 * Injecting every collaborator (rail, budget, ledger, ring, origin, clock)
 * is what makes the terminal-path mapping and the "one row + recordPaid once"
 * guarantee fully testable.
 */
export class Broker {
  private readonly rail: PaymentRail;
  private readonly budget: BudgetEngine;
  private readonly ledger: AuditLedger;
  private readonly ring?: KeyRing;
  private readonly origin: OriginClient;
  private readonly clock: Clock;
  private readonly identityOpts: BrokerIdentityOptions;
  private readonly headers: HeaderRecord;

  /** Cached terminal outcomes keyed by fetchId ⇒ one row + one charge per id. */
  private readonly outcomes = new Map<string, FetchOutcome>();

  constructor(options: BrokerOptions) {
    this.rail = options.rail;
    this.budget = options.budget;
    this.ledger = options.ledger;
    this.ring = options.ring;
    this.origin = options.origin;
    this.clock = options.clock ?? systemClock;
    this.identityOpts = options.identity ?? {};
    this.headers = options.headers ?? {};
  }

  /**
   * Perform one metered fetch and return its terminal outcome.
   *
   * Idempotent by `fetchId`: a second call with the same id returns the
   * cached outcome without re-quoting, re-settling, or charging the meter.
   */
  async fetch(params: {
    url: UrlString;
    fetchId?: string;
    headers?: HeaderRecord;
    tenantId?: string;
    rand?: () => number;
  }): Promise<FetchOutcome> {
    const fetchId = params.fetchId ?? makeFetchId(params.rand);
    const existing = this.outcomes.get(fetchId);
    if (existing) return this.cloneOutcome(existing);

    const startedAt = this.clock.now();
    const tenantId = params.tenantId ?? 'default';

    try {
      const outcome = await this.run(fetchId, startedAt, params.url, tenantId, params.headers);
      // Cache the terminal outcome so a repeat fetchId returns the SAME
      // object without re-quoting, re-settling, or charging the meter.
      this.outcomes.set(fetchId, outcome);
      return outcome;
    } finally {
      // startedAt is carried forward on the outcome's timestamps.
      void startedAt;
    }
  }

  /** The single terminal outcome for a fetchId, or undefined. */
  outcomeFor(fetchId: string): FetchOutcome | undefined {
    const o = this.outcomes.get(fetchId);
    return o ? this.cloneOutcome(o) : undefined;
  }

  /** The one ledger row recorded for a fetchId, or undefined. */
  rowFor(fetchId: string) {
    return this.ledger.entries.find((e) => e.fetchId === fetchId);
  }

  // --- the compose pipeline ---------------------------------------------

  private async run(
    fetchId: string,
    startedAt: string,
    url: UrlString,
    tenantId: string,
    extraHeaders?: HeaderRecord
  ): Promise<FetchOutcome> {
    const req = this.paymentRequest(url, extraHeaders);
    const identity = this.signIdentity(req);

    // 1. Quote the rail — the origin's price, needed to gate on budget.
    const quote = await this.rail.quote(req);

    // 2. Budget gate (the first deny-gate). BudgetError is policy denial.
    try {
      this.budget.preflight(tenantId, quote, url);
    } catch (err) {
      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
        return this.denied(fetchId, tenantId, 'blocked',
          err instanceof Error ? err.message : String(err), { url, httpStatus: undefined });
      }
      throw err;
    }

    // 3. Authorize. A rail error here means payment could not be arranged
    //    — a terminal `payment-required` decision, not a thrown fault.
    let authorization: RailAuthorization;
    try {
      authorization = await this.rail.authorize(req, quote);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'authorize', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
    let settlement: RailSettlement;
    try {
      settlement = await this.rail.settle(req, authorization);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'settle', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 5. Content from the origin, settlement headers applied.
    const originResp = await this.origin.fetch({
      ...req,
      headers: { ...req.headers, ...authorization.settlementHeaders },
    });

    // 6. Map the origin's HTTP answer to a terminal class.
    if (!isOk(originResp.httpStatus)) {
      return this.originDenied(fetchId, tenantId, originUrl(originResp, url), originResp.httpStatus, identity != null);
    }

    // fulfilled — charge the meter once and record one row.
    return this.fulfilled({
      url,
      fetchId,
      tenantId,
      quote,
      settlement,
      identity,
      origin: originResp,
      startedAt,
    });
  }

  // --- outcome builders --------------------------------------------------

  private fulfilled(args: {
    url: UrlString;
    fetchId: string;
    tenantId: string;
    quote: Quote;
    settlement: RailSettlement;
    identity?: IdentityPresentation;
    origin: OriginResponse;
    startedAt: string;
  }): FetchOutcome {
    // 7. License — if the origin publishes RSL terms, derive obligations.
    const license = parseOriginLicense(args.origin.headers);
    const obligations = license ? deriveObligations(license) : [];
    const storeable = license ? resolveStoreability(license) : true;

    // Charge the tenant meter exactly once, on fulfillment.
    this.budget.recordPaid(
      args.tenantId,
      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      args.url
    );

    const outcome: FetchOutcome = {
      fetchId: args.fetchId,
      status: 'fulfilled',
      reason: 'content released after settlement',
      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
      content: {
        body: args.origin.body,
        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
        storeable,
        attributionNotice: attributionNotice(license),
      },
      license,
      obligations,
      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      quote: args.quote,
      rail: args.settlement.rail,
      settlementRef: args.settlement.settlementRef,
      identity: args.identity?.keyId ? identityToPresentation(args.identity) : undefined,
      tenantId: args.tenantId,
      timestamps: { startedAt: args.startedAt, completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId: args.tenantId });
    return outcome;
  }

  private denied(
    fetchId: string,
    tenantId: string,
    failureClass: FailureClass,
    message: string,
    info: { url: UrlString; httpStatus?: number }
  ): FetchOutcome {
    const outcome: FetchOutcome = {
      fetchId,
      status: 'denied',
      failureClass,
      reason: message,
      error: { code: failureClass, message },
      origin: info.httpStatus != null
        ? { url: String(info.url), httpStatus: info.httpStatus }
        : { url: String(info.url) },
      tenantId,
      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId });
    return outcome;
  }

  private originDenied(
    fetchId: string,
    tenantId: string,
    url: string,
    httpStatus: number,
    identityPresent: boolean
  ): FetchOutcome {
    let failureClass: FailureClass;
    let message: string;
    let code: string;

    if (httpStatus === 402) {
      failureClass = 'payment-required';
      message = 'origin still demanded payment after settlement (not obtainable)';
      code = 'PAYMENT_REQUIRED';
    } else if (httpStatus === 403 && identityPresent) {
      failureClass = 'token-rejected';
      message = 'origin rejected the presented attestation/identity (HTTP 403)';
      code = 'TOKEN_REJECTED';
    } else if (httpStatus === 403) {
      failureClass = 'blocked';
      message = 'origin blocked the request without a presented identity (HTTP 403)';
      code = 'ORIGIN_BLOCKED';
    } else {
      failureClass = 'blocked';
      message = `origin rejected the request with HTTP ${httpStatus}`;
      code = 'ORIGIN_REJECTED';
    }

    return this.denied(fetchId, tenantId, failureClass, message, { url: url as UrlString, httpStatus });
  }

  // --- identity + request helpers ----------------------------------------

  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
    return {
      url,
      method: 'GET',
      headers: {
        host: new URL(String(url)).host,
        'user-agent': 'metered-web-broker/0.1',
        ...this.headers,
        ...(extraHeaders ?? {}),
      },
    };
  }

  /**
   * Best-effort identity: sign the presented headers and, when a known
   * subject exists, issue a PACT. Returns undefined when no ring is present,
   * no active key exists, or signing throws. Never a gate.
   */
  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
    if (!this.ring) return undefined;

    const keyId = this.ring.active()[0]?.keyId;
    if (!keyId) return undefined;

    // Canonical block the origin can verify: host + date.
    const signingHeaders: HeaderRecord = {
      host: new URL(String(req.url)).host,
      date: this.clock.now(),
      ...req.headers,
    };

    let signedFields: string[];
    try {
      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
    } catch (cause) {
      if (cause instanceof IdentityError) return undefined;
      throw cause;
    }

    let pactToken: string | undefined;
    const subject = this.identityOpts.subject;
    if (subject) {
      try {
        const body = {
          subject,
          grants: [],
          iat: this.clock.now(),
          iss: 'metered-web-broker',
        };
        pactToken = PACT.issue(this.ring, keyId, body).token;
      } catch {
        // Best-effort: a failed PACT issuance is ignored, not a gate.
      }
    }

    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
  }

  private cloneOutcome(o: FetchOutcome): FetchOutcome {
    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
  }
}

/** Identity presentation surfaced on a fulfilled outcome. */
interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  pactToken?: string;
}

function identityToPresentation(x: IdentityPresentation): FetchOutcome['identity'] {
  return {
    keyId: x.keyId,
    algorithm: x.algorithm,
    signedHeaders: x.signedHeaders,
    timestamp: x.timestamp,
    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
  };
}

function isOk(httpStatus: number): boolean {
  return httpStatus >= 200 && httpStatus < 300;
}

/** A best-effort origin URL for denied rows when the fetch request was dropped. */
function originUrl(resp: OriginResponse, url: UrlString): string {
  return headersUrl(resp) ?? String(url);
}

function headersUrl(resp: OriginResponse): string | undefined {
  const u = resp.headers['location'] ?? resp.headers['Location'];
  if (u) try { return new URL(u).toString(); } catch { return undefined; }
  return undefined;
}

/** Wrap a rail failure as a `payment-required` fault. */
function railFault(err: unknown, step: 'authorize' | 'settle', railId: string): Error {
  if (isBrokerError(err)) return err;
  const cause = err instanceof Error ? err : new Error(String(err));
  return new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', cause, true);
}

/** Parse the RSL `Link` header from origin response headers, if present. */
function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
  const link = headers['link'] ?? headers['Link'];
  if (!link) return undefined;
  try {
    return parseLicense(link, { link });
  } catch {
    return undefined; // best-effort: a bad Link is not a terminal failure
  }
}

/** Attribution notice surfaced on fulfilled content, if the license requires it. */
function attributionNotice(
  license: FetchOutcome['license']
): string | undefined {
  if (!license) return undefined;
  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
  if (!clause) return undefined;
  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
  return `Attribution required: ${by}`;
}

export {
  Broker,
  type OriginClient,
  type OriginResponse,
  type BrokerOptions,
  type BrokerIdentityOptions,
  type TerminalKind,
} from './broker.js';

{
  "name": "metered-web-broker",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "A neutral one-contract Metered Web Broker: one endpoint returns content + license + settlement receipt. The broker handles the 402s, licenses, identity, budget, and audit.",
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "typecheck": "npm run typecheck --workspaces",
    "test": "vitest run",
    "test:watch": "vitest",
    "demo": "tsx scripts/demo.ts",
    "conformance": "tsx packages/conformance/src/cli.ts"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  }
}

/**
 * A runnable end-to-end demo of the Metered Web Broker.
 *
 * It exercises all four terminal outcomes against the in-memory rail, with
 * a frozen clock and an injected origin client, so it is fully deterministic
 * and needs no network:
 *
 *   1. fulfilled   — a paid fetch, receipt + obligations from a Link header
 *   2. blocked     — budget ceiling exceeded (the first deny-gate)
 *   3. payment-required — origin still demands payment after settlement (402)
 *   4. token-rejected — origin rejects the presented identity (403 + ring)
 *
 * After each, the single audit ledger is rendered so the terminal decision is
 * visible on the audit surface.
 *
 *   npm run demo   (== tsx scripts/demo.ts)
 */

import { frozenClock, formatMicros } from '@mwb/core';
import { Broker } from '@mwb/gateway';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { AuditLedger, renderDashboard } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import { InMemoryRail } from '@mwb/rails';

const clock = frozenClock();

const URL = 'https://api.example.com/wire/42';

/** A configurable-injection OriginClient: returns whatever response we build. */
function originClient(response: {
  httpStatus: number;
  headers?: Record<string, string>;
  body?: string;
}) {
  return {
    fetch: async () => ({
      httpStatus: response.httpStatus,
      headers: response.headers ?? {},
      body: response.body ?? '<html>ok</html>',
    }),
  };
}

/** The L1000/2GB RSL Link header an origin publishes on a fulfilled fetch. */
const LICENSE_LINK =
  '<https://licenses.example/r/73>; rel="type:license-terms"; type="application/vnd.example.l1000+json"';

/** Build a broker wired with a frozen clock and an injected origin. */
function makeBroker(args: {
  rail: ReturnType<typeof inMemory>;
  budget: BudgetEngine;
  ledger: AuditLedger;
  ring?: KeyRing;
  subject?: string;
  resp: { httpStatus: number; headers?: Record<string, string>; body?: string };
}) {
  const { rail, budget, ledger, resp, subject } = args;
  const options: ConstructorParameters<typeof Broker>[0] = {
    rail,
    budget,
    ledger,
    origin: originClient(resp),
    clock,
  };
  if (args.ring) options.ring = args.ring;
  if (subject) options.identity = { subject };
  return new Broker(options);
}

/** A rail that "succeeds" (quote/authorize/settle all pass). */
function inMemory(priceMicros: number) {
  return new InMemoryRail({
    id: 'x402',
    priceMicros,
    currency: defaultPolicy.currency,
    clock,
    settlementSeed: 'demo-seed',
  });
}

/** A rail that fails settlement. */
function failingRail() {
  return new InMemoryRail({
    id: 'x402',
    priceMicros: 5000,
    currency: defaultPolicy.currency,
    clock,
    settlementSeed: 'demo-seed',
    failureMode: 'settle',
  });
}

let seq = 0;
function nextFetchId(): string {
  seq += 1;
  return `demo-fetch-${seq}`;
}

/** Print a terminal outcome's key fields as a short receipt. */
function printOutcome(outcome: Awaited<ReturnType<Broker['fetch']>>, label: string): void {
  console.log(`\n── ${label} ─────────────────────────────────`);
  console.log(`  status    : ${outcome.status}`);
  if (outcome.failureClass) console.log(`  failure   : ${outcome.failureClass}`);
  if (outcome.error) console.log(`  reason    : ${outcome.error.message}`);
  if (outcome.status === 'fulfilled') {
    console.log(`  content   : ${outcome.content?.body}`);
    console.log(`  price     : ${formatMicros(outcome.price?.unitsMicros ?? 0, outcome.price?.currency)}`);
    console.log(`  settlement: ${outcome.settlementRef}`);
    if (outcome.identity) {
      console.log(`  identity  : keyId=${outcome.identity.keyId}`);
      if (outcome.identity.pactToken) console.log(`  pactToken : [${outcome.identity.pactToken.length} chars, PACT-issued]`);
    }
    if (outcome.license) console.log(`  license   : id=${outcome.license.id} (rawSource=${outcome.license.rawSource})`);
    if (outcome.obligations) {
      console.log(`  obligations:`);
      for (const o of outcome.obligations) console.log(`    - ${o.clause} → ${o.kind}: ${o.instruction}`);
    }
  }
}

async function main(): Promise<void> {
  const ledger = new AuditLedger({ clock });

  // 1. Fulfilled — a paid fetch that returns content + an RSL Link header.
  {
    const rail = inMemory(5000);
    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
    const ring = new KeyRing(clock);
    ring.issue({ keyId: 'demo-key' });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      ring,
      subject: 'tenant:demo',
      resp: {
        httpStatus: 200,
        headers: { link: LICENSE_LINK, 'content-type': 'text/markdown' },
        body: '# Headline\nThe wire, paid for.',
      },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '1. FULFILLED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 1: fulfilled'));
  }

  // 2. Blocked — the quote (5000 micros) blows the per-call ceiling (100).
  {
    const rail = inMemory(5000);
    const budget = new BudgetEngine({
      policy: { ...defaultPolicy, perCallCeilingMicros: 100 },
      clock,
    });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      resp: { httpStatus: 200, body: 'never fetched' },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '2. BLOCKED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 2: blocked'));
  }

  // 3. Payment-required — settlement fails on the rail.
  {
    const rail = failingRail();
    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      resp: { httpStatus: 200, body: 'never fetched' },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '3. PAYMENT-REQUIRED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 3: payment-required'));
  }

  // 4. Token-rejected — a 403 from the origin while presenting identity.
  {
    const rail = inMemory(5000);
    const budget = new BudgetEngine({ policy: defaultPolicy, clock });
    const ring = new KeyRing(clock);
    ring.issue({ keyId: 'demo-key' });
    const broker = makeBroker({
      rail,
      budget,
      ledger,
      ring,
      subject: 'tenant:demo',
      resp: { httpStatus: 403, body: 'identity rejected' },
    });
    const outcome = await broker.fetch({ url: URL, fetchId: nextFetchId() });
    printOutcome(outcome, '4. TOKEN-REJECTED');
    console.log(renderDashboard(ledger.entries, 'Metered Web Broker — after 4: token-rejected'));
  }

  // --- summary -----------------------------------------------------------
  console.log('\n' + '═'.repeat(60));
  console.log('SUMMARY');
  console.log(`  total requests : ${ledger.entries.length}`);
  console.log(
    `  fulfilled      : ${
      ledger.entries.filter((e) => e.status === 'fulfilled').length
    }`
  );
  console.log(
    `  denied         : ${ledger.entries.filter((e) => e.status === 'denied').length}`
  );
  const spend = ledger.entries.reduce(
    (sum, e) => sum + (e.priceMicros ?? 0),
    0
  );
  console.log(`  total spend    : ${formatMicros(spend, 'USD')}`);
  console.log('  terminal classes on the audit surface: ' +
    ['fulfilled', 'blocked', 'payment-required', 'token-rejected']
      .map((c) => `${c}=1`)
      .join('  '));
  console.log('═'.repeat(60));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { describe, expect, it } from 'vitest';
import { AuditLedger, reconcile, summarize } from '@mwb/audit';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { InMemoryRail } from '@mwb/rails';
import { KeyRing } from '@mwb/identity';
import { frozenClock, makeFetchId, url, type Clock, type UrlString } from '@mwb/core';
import type { OriginClient, OriginResponse, TerminalKind } from '@mwb/gateway';
import { Broker } from '@mwb/gateway';

const clock = frozenClock();

const PRICE = 5000; // 5000 micros
const URL: UrlString = url('https://api.example.com/data');

/** A minimal origin that returns whatever status we configure. */
function origin(response: Partial<OriginResponse> = {}): OriginResponse {
  return {
    httpStatus: 200,
    headers: {},
    body: '<html>ok</html>',
    ...response,
  };
}

/** Wrap an OriginResponse in the minimal OriginClient the broker calls. */
function client(resp: OriginResponse = origin()): OriginClient {
  return { fetch: () => Promise.resolve(resp) };
}

function make({
  price = PRICE,
  failureMode = 'none',
  currency,
  ring = false,
  origin: resp = origin(),
}: {
  price?: number;
  failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
  currency?: string;
  ring?: boolean;
  origin?: OriginResponse;
} = {}) {
  const budget = new BudgetEngine({ policy: defaultPolicy, clock });
  const ledger = new AuditLedger({ clock });
  const rail = new InMemoryRail({
    id: 'x402',
    priceMicros: price,
    currency: currency ?? defaultPolicy.currency,
    clock,
    settlementSeed: 'seed',
    failureMode,
  });
  const opts: ConstructorParameters<typeof Broker>[0] = {
    rail,
    budget,
    ledger,
    origin: { fetch: () => Promise.resolve(resp) },
    clock,
  };
  if (ring) {
    const r = new KeyRing(clock);
    r.issue({ keyId: 'test-key' });
    opts.ring = r;
    // A known subject is what makes the broker issue a PACT, so the
    // fulfilled outcome carries a pactToken (not just a keyId).
    opts.identity = { subject: 'tenant:test-key' };
  }
  return { budget, ledger, rail, opts };
}

function run(opts: ConstructorParameters<typeof Broker>[0], params?: { fetchId?: string; tenantId?: string }) {
  const b = new Broker(opts);
  const f = params?.fetchId ?? makeFetchId();
  return {
    broker: b,
    outcome: b.fetch({ url: URL, fetchId: f, tenantId: params?.tenantId }),
  };
}

describe('Broker.fetch — fulfilled', () => {
  it('charges the meter once, records exactly one row, and reconciles', async () => {
    const { ledger, budget, rail } = make();
    const { broker, outcome } = await run({ rail, budget, ledger, origin: client() });

    const o = await outcome;
    expect(o.status).toBe('fulfilled');
    expect(o.failureClass).toBeUndefined();
    expect(o.tenantId).toBe('default');
    expect(o.license).toBeUndefined();

    // exactly one row, and the idempotent fetch returns the same one
    expect(ledger.entries.length).toBe(1);
    expect(broker.rowFor(o.fetchId)).toBe(ledger.entries[0]);
    expect(await broker.outcomeFor(o.fetchId)).toEqual(o);

    // charge recorded once: exactly one fulfilled row on the ledger
    expect(ledger.entries.length).toBe(1);
    expect(summarize(ledger.entries).fulfilled).toBe(1);
    const settled = ledger.entries[0]!;
    expect(settled.priceMicros).toBe(PRICE);
    expect(settled.currency).toBe(defaultPolicy.currency);
    expect(settled.rail).toBe('x402');
    expect(settled.settlementRef).toBeTruthy();

    const rep = reconcile(ledger.entries);
    expect(rep.ok).toBe(true);
    expect(rep.problems).toEqual([]);
  });

  it('records identity on a fulfilled outcome when a ring is present', async () => {
    const { ledger, budget, rail, opts } = make({ ring: true });
    const { outcome } = await run(opts);
    const o = await outcome;
    expect(o.identity?.keyId).toBeTruthy();
    expect(o.identity?.pactToken).toBeTruthy();
    expect(ledger.entries[0]!.keyId).toBe(o.identity!.keyId);
  });

  it('derives obligations from a published license', async () => {
    const link = '<https://licenses.example/r/73>; rel="type:license-terms"';
    const resp = origin({
      headers: { link, 'content-type': 'text/html' },
      body: '<html>with terms</html>',
    });
    const { ledger, rail, budget } = make({ origin: resp });
    const { outcome } = await run({ rail, budget, ledger, origin: client(resp) });
    const o = await outcome;

    expect(o.license).toBeDefined();
    expect(o.license?.id).toBe('/r/73');
    expect(Array.isArray(o.obligations)).toBe(true);
    expect(o.content?.contentType).toBe('text/html');
  });
});

describe('Broker.fetch — blocked (budget is the first gate)', () => {
  it('maps a BudgetError policy denial to blocked', async () => {
    const policy = { ...defaultPolicy, perCallCeilingMicros: 100 }; // quote is 5000 → over ceiling
    const budget = new BudgetEngine({ policy, clock });
    const ledger = new AuditLedger({ clock });
    const rail = new InMemoryRail({ id: 'x402', priceMicros: 5000, currency: policy.currency, clock });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });

    expect(o.status).toBe('denied');
    expect(o.failureClass).toBe('blocked');
    expect(o.error!.code).toBe('blocked');
    expect(o.origin?.httpStatus).toBeUndefined(); // never reached the origin
    expect(ledger.entries.length).toBe(1);
    expect(reconcile(ledger.entries).checks.deniedHasFailureClass).toBe(true);
  });

  it('maps a currency mismatch to blocked', async () => {
    const { rail, budget, ledger } = make({ currency: 'EUR' });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
    expect(ledger.entries[0]!.status).toBe('denied');
  });

  it('maps a 5xx origin (no identity) to blocked', async () => {
    const { rail, budget, ledger } = make({ origin: origin({ httpStatus: 500 }) });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin({ httpStatus: 500 })) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
    expect(o.origin?.httpStatus).toBe(500);
  });

  it('maps a 403-without-identity origin to blocked', async () => {
    const resp = origin({ httpStatus: 403 });
    const broker = new Broker({
      rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }),
      budget: new BudgetEngine({ policy: defaultPolicy, clock }),
      ledger: new AuditLedger({ clock }),
      origin: { fetch: () => Promise.resolve(resp) },
    });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
  });
});

describe('Broker.fetch — payment-required', () => {
  it('maps authorize failure to payment-required', async () => {
    const { rail, budget, ledger } = make({ failureMode: 'authorize' });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('payment-required');
  });

  it('maps settle failure to payment-required', async () => {
    const { rail, budget, ledger } = make({ failureMode: 'settle' });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('payment-required');
  });

  it('maps a 402 origin to payment-required', async () => {
    const resp = origin({ httpStatus: 402 });
    const broker = new Broker({
      rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }),
      budget: new BudgetEngine({ policy: defaultPolicy, clock }),
      ledger: new AuditLedger({ clock }),
      origin: { fetch: () => Promise.resolve(resp) },
    });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('payment-required');
    expect(o.origin?.httpStatus).toBe(402);
  });
});

describe('Broker.fetch — token-rejected', () => {
  it('maps a 403 origin that rejected presented identity to token-rejected', async () => {
    const resp = origin({ httpStatus: 403 });
    const r = new KeyRing(clock);
    r.issue({ keyId: 'test-key' });
    const broker = new Broker({
      rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }),
      budget: new BudgetEngine({ policy: defaultPolicy, clock }),
      ledger: new AuditLedger({ clock }),
      ring: r,
      identity: { subject: 'tenant-a' },
      origin: { fetch: () => Promise.resolve(resp) },
    });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('token-rejected');
    expect(o.origin?.httpStatus).toBe(403);
  });
});

describe('Broker.fetch — idempotency', () => {
  it('returns the cached outcome and only charges/re-rows once', async () => {
    const { ledger, budget, rail } = make();
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const f = makeFetchId();

    const a = await broker.fetch({ url: URL, fetchId: f });
    const b = await broker.fetch({ url: URL, fetchId: f });

    expect(broker.rowFor(f)).toBe(ledger.entries[0]);
    expect(ledger.entries.length).toBe(1);
    expect(a.fetchId).toBe(b.fetchId);
    expect(a.status).toBe(b.status);
  });
});

describe('Broker.fetch — terminal-class invariant', () => {
  it('every denied path is one of the three failure classes and reconciles', async () => {
    const valid: TerminalKind[] = ['fulfilled', 'blocked', 'payment-required', 'token-rejected'];

    const makeBroker = (cfg: {
      origin?: OriginResponse;
      failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
      currency?: string;
      ceiling?: number;
      ring?: boolean;
    } = {}) => {
      const budget = new BudgetEngine({
        policy: { ...defaultPolicy, ...(cfg.ceiling != null ? { perCallCeilingMicros: cfg.ceiling } : {}) },
        clock,
      });
      const ledger = new AuditLedger({ clock });
      const rail = new InMemoryRail({
        id: 'x402',
        priceMicros: cfg.ceiling != null ? cfg.ceiling + 5000 : PRICE,
        currency: cfg.currency,
        clock,
        failureMode: cfg.failureMode,
      });
      const broker = new Broker({
        rail, budget, ledger,
        ...(cfg.ring ? { ring: new KeyRing(clock) } : {}),
        origin: { fetch: () => Promise.resolve(cfg.origin ?? origin()) },
      });
      return { broker, ledger };
    };

    const configs = [
      makeBroker({ ceiling: 100 }),
      makeBroker({ currency: 'EUR' }),
      makeBroker({ failureMode: 'authorize' }),
      makeBroker({ failureMode: 'settle' }),
      makeBroker({ origin: origin({ httpStatus: 402 }) }),
      makeBroker({ origin: origin({ httpStatus: 403 }), ring: true }),
      makeBroker({ origin: origin({ httpStatus: 403 }) }),
      makeBroker(),
    ];

    for (const { broker, ledger } of configs) {
      const o = await broker.fetch({ url: URL });
      expect(valid).toContain(o.failureClass ?? 'fulfilled');
      if (o.status === 'denied') expect(o.failureClass).toBeDefined();
      const rep = reconcile(ledger.entries);
      expect(rep.ok).toBe(true);
      expect(rep.problems).toEqual([]);
    }
  });
});

import type { Price, Quote } from './amounts.js';

/** A string constrained to a valid absolute URL at construction. */
export type UrlString = string & { readonly __brand: 'UrlString' };

export function url(value: string): UrlString {
  try {
    return new URL(value) as unknown as UrlString;
  } catch (cause) {
    throw new TypeError(`url(): invalid absolute URL: ${value}`, { cause });
  }
}

export type HeaderRecord = Record<string, string>;

/**
 * The three distinct failure classes. Today's agents collapse all of these
 * into a generic fetch failure; the broker reports each separately so the
 * cost decision is visible.
 */
export type FailureClass = 'blocked' | 'payment-required' | 'token-rejected';

export type FetchStatus = 'fulfilled' | 'denied' | 'error';

export interface FetchParams {
  url: UrlString;
  headers?: HeaderRecord;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /** Extra budget context from the caller, merged under broker policy. */
  budgetOverride?: { perCallCeilingMicros?: number; lineItemCeilingMicros?: number };
}

export type RslClauseType =
  | 'attribution'
  | 'no-store'
  | 'no-derivative-works'
  | 'no-commercial-use'
  | 'pay-per-inference'
  | 'redistribution'
  | (string & {});

export type RslClauseValue = 'required' | 'permitted' | 'forbidden' | number;

export interface RslClause {
  type: string;
  value: RslClauseValue;
  params: Record<string, string | number>;
}

/** A parsed Rights Statement Language (RSL) document. */
export interface License {
  draft: string;
  id: string;
  title?: string;
  publishedAt?: string;
  clauses: RslClause[];
  rawSource: string;
}

/**
 * Obligations the broker derives from a license and enforces/surfaces for
 * this particular fetch. Surfaced in the outcome so the caller can comply.
 */
export interface LicenseObligation {
  clause: string;
  kind: 'notice' | 'store-prohibited' | 'inference-budget' | 'forbidden' | 'permitted';
  instruction: string;
  applied?: string;
}

export interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  /** Opaque PACT-style attestation token where the origin accepts one. */
  pactToken?: string;
}

export interface FetchOutcome {
  fetchId: string;
  status: FetchStatus;
  /** Present iff status !== 'fulfilled'. The three distinct failure classes. */
  failureClass?: FailureClass;
  reason: string;
  origin?: { url: string; httpStatus?: number };
  content?: { body: string; contentType: string; storeable: boolean; attributionNotice?: string };
  license?: License;
  obligations?: LicenseObligation[];
  price?: Price;
  quote?: Quote;
  rail?: string;
  settlementRef?: string;
  identity?: IdentityPresentation;
  tenantId?: string;
  timestamps: { startedAt: string; completedAt: string };
  error?: { code: string; message: string };
}

/** A raw ledger row — the audit surface. */
export interface LedgerEntry {
  seq: number;
  fetchId: string;
  tenantId: string;
  url: string;
  status: FetchStatus;
  failureClass?: FailureClass;
  httpStatus?: number;
  priceMicros?: number;
  currency?: string;
  rail?: string;
  licenseId?: string;
  keyId?: string;
  settlementRef?: string;
  startedAt: string;
  completedAt: string;
  recordedAt: string;
}

/**
 * A payment rail: one interface, pluggable backends.
 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
 * The interface is stable; backend field names are not (draft-caveat discipline).
 */
export interface PaymentRequest {
  url: UrlString;
  method: string;
  headers: HeaderRecord;
  contentType?: string;
}

export interface RailAuthorization {
  /** Headers the origin expects on the settled request (e.g. X-PAYMENT). */
  settlementHeaders: HeaderRecord;
  scheme: string;
  payload: string;
}

export interface RailSettlement {
  rail: string;
  settlementRef: string;
  amountMicros: number;
  currency: string;
  settledAt: string;
}

export interface PaymentRail {
  readonly id: string;
  quote(req: PaymentRequest): Promise<Quote>;
  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    include: ['packages/*/src/**/*.test.ts'],
  },
});

import { LicenseError } from '@mwb/core';
import type { License, LicenseObligation, RslClause, RslClauseValue } from '@mwb/core';

/**
 * License Engine — the broker's compliance layer.
 *
 * Three jobs, all read-only with respect to the network:
 *   1. `parseLicense`     — turn a raw RSL source (a parsed body or a
 *      `Link` header) into a typed `License`.
 *   2. `deriveObligations` — read those terms and produce the concrete,
 *      fetch-scoped obligations the caller must satisfy (attribution,
 *      no-store, pay-per-inference budget, …).
 *   3. `enforce` / `resolveStoreability` — post-fetch checks: did the
 *      caller's actions violate a term?
 *
 * RSL (Really Simple Licensing) terms ride in an HTTP `Link` header, e.g.
 *
 *     Link: <https://licenses.example/r/73>; rel="type:license-terms"
 *
 * with a JSON body that carries the `terms` array. This module builds
 * against that *pattern*; draft field names may drift, so parsing is
 * defensive. Draft-caveat discipline: parse against the shape above, never
 * a draft's exact wire grammar.
 */

/** A clause, as it appears in an RSL `terms` array. */
export interface RslTermInput {
  type: string;
  value?: boolean | number | string;
  params?: Record<string, string | number>;
}

/** A parsed RSL body, matching the accepted JSON shape. */
export interface RslBodyLike {
  draft?: string;
  id?: string;
  title?: string;
  publishedAt?: string;
  terms?: RslTermInput[];
  link?: string;
  rawSource?: string;
}

export interface LicenseParseOptions {
  /** A `Link` header (or just its URL) identifying the terms document. */
  link?: string;
  /**
   * The raw source string, preserved verbatim on the parsed License for the
   * audit trail. Defaults to whatever was parsed if it was a string.
   */
  rawSource?: string;
}

/**
 * Parse an RSL source into a License.
 *
 * Accepts:
 *  - a JSON string with a `terms` array (or an `RslBodyLike` object)
 *  - a `Link` header string such as
 *    `<https://licenses.example/r/73>; rel="type:license-terms"`
 *  - `options.link` to attach a terms id when the body carries no `id`.
 */
export function parseLicense(
  source: string | RslBodyLike,
  options: LicenseParseOptions = {}
): License {
  let body: RslBodyLike = { ...(source && typeof source === 'object' ? source : {}) };
  let rawSource: string | undefined = options.rawSource;

  if (typeof source === 'string') {
    const s = source.trim();
    if (s.startsWith('{')) {
      try {
        body = { ...(JSON.parse(s) as RslBodyLike) };
      } catch (cause) {
        throw new LicenseError(`RSL body is not valid JSON: ${s}`, 'RSL_PARSE', cause);
      }
      rawSource ??= source;
    } else {
      // It is a Link header (or bare URL) identifying the terms doc.
      const link = extractLink(s);
      body.id = body.id ?? link.id;
      body.draft = body.draft ?? link.draft;
      rawSource ??= source;
    }
  }

  const id = body.id?.trim() || linkId(body.link as string | undefined);
  if (!id) {
    throw new LicenseError('RSL source carried no license identifier', 'RSL_NO_ID');
  }

  return {
    draft: body.draft?.trim() || 'urn:rsl:draft:unregistered',
    id,
    title: body.title,
    publishedAt: body.publishedAt,
    clauses: normalizeClauses(body.terms),
    rawSource: rawSource ?? body.rawSource ?? `<${id}>`,
  };
}

/**
 * Derive the fetch-scoped obligations from a license. An empty terms array
 * yields no obligations; the broker still surfaces the `License` so the
 * caller can see what it is (not) bound to.
 */
export function deriveObligations(license: License): LicenseObligation[] {
  const out: LicenseObligation[] = [];
  for (const clause of license.clauses) {
    const { instruction, kind } = clauseToObligation(clause.type, clause.params);
    if (instruction) out.push({ clause: clause.type, kind, instruction });
  }
  return out;
}

/**
 * Whether the broker may mark the fetched content storeable given the
 * license. A `no-store` marked `forbidden` makes it non-storeable; anything
 * else leaves storeability to the caller.
 */
export function resolveStoreability(license: License): boolean {
  return !license.clauses.some((c) => c.type === 'no-store' && c.value === 'forbidden');
}

/** Post-fetch actions the caller may have taken. */
export interface EnforcementActions {
  /** Did the caller store/cache the content? */
  store?: boolean;
  /** Attribution notice included when storing, if any (non-empty ⇒ provided). */
  attribution?: string;
  /** Is the usage commercial? */
  commercialUse?: boolean;
  /** Did the caller produce a derivative work from stored content? */
  derived?: boolean;
  /** Number of model inferences run, if any. */
  inferenceCount?: number;
}

export interface EnforcementResult {
  pass: boolean;
  violations: string[];
  obligations: LicenseObligation[];
}

/**
 * Check the caller's post-fetch actions against the license. Returns the
 * derived obligations plus any violations — the broker surfaces this so a
 * call that "worked" can still report a compliance problem.
 *
 * Pay-per-inference is advisory (a budget, not a hard gate): the settlement
 * row is the proof of payment, so the engine never blocks on it.
 */
export function enforce(
  license: License,
  actions: EnforcementActions = {}
): EnforcementResult {
  const violations: string[] = [];

  for (const clause of license.clauses) {
    if (clause.type === 'no-store' && clause.value === 'forbidden' && actions.store) {
      violations.push('no-store: content must not be stored, but store was requested');
    }
    if (clause.type === 'no-commercial-use' && clause.value === 'forbidden' && actions.commercialUse) {
      violations.push('no-commercial-use: usage is commercial, which the license forbids');
    }
    if (
      clause.type === 'no-derivative-works' &&
      clause.value === 'forbidden' &&
      actions.store &&
      actions.derived
    ) {
      violations.push('no-derivative-works: content was stored and transformed');
    }
  }

  const wantsAttribution = license.clauses.some((c) => c.type === 'attribution' && c.value === 'required');
  if (wantsAttribution && actions.store && !attributionProvided(actions)) {
    violations.push('attribution: content was stored without the required attribution notice');
  }

  return { pass: violations.length === 0, violations, obligations: deriveObligations(license) };
}

function attributionProvided(actions: EnforcementActions): boolean {
  return typeof actions.attribution === 'string' && actions.attribution.length > 0;
}

// --- clause mapping -------------------------------------------------------

/** Translate a single clause to the obligation it imposes, if any. */
function clauseToObligation(
  type: string,
  params?: Record<string, string | number>
): { instruction?: string; kind: LicenseObligation['kind'] } {
  switch (type) {
    case 'attribution':
      if (params?.by) return { kind: 'notice', instruction: `Include attribution to ${params.by} when using this content.` };
      return { kind: 'notice', instruction: 'Include attribution when using this content.' };
    case 'no-store':
      return { kind: 'store-prohibited', instruction: 'Do not store or cache this content.' };
    case 'no-derivative-works':
      return { kind: 'forbidden', instruction: 'Do not create derivative works from this content.' };
    case 'no-commercial-use':
      return { kind: 'forbidden', instruction: 'Commercial use of this content is forbidden.' };
    case 'redistribution':
      return { kind: 'forbidden', instruction: 'Redistribution of this content is forbidden.' };
    default:
      return { kind: 'notice', instruction: `License term ${type} applies; review its conditions.` };
  }
}

// --- helpers --------------------------------------------------------------

/** RSL treats a bare clause as required; the engine is predictable about it. */
function normalizeClauses(terms?: RslTermInput[]): RslClause[] {
  if (!terms) return [];
  const out: RslClause[] = [];
  for (const t of terms) {
    if (!t || typeof t.type !== 'string' || !t.type) {
      throw new LicenseError(`RSL clause is missing a type: ${JSON.stringify(t)}`, 'RSL_BAD_CLAUSE');
    }
    out.push({
      type: t.type,
      // RslTermInput is the loose draft input; the engine contract (RslClauseValue)
      // is the normalized shape. Preserve recognized values; treat an omitted
      // value as the default 'required'.
      value: t.value === undefined
        ? 'required'
        : (t.value as RslClauseValue),
      params: t.params ?? {},
    });
  }
  return out;
}

/** Parse a `Link` header (or bare URL) into { id, draft }. */
function extractLink(link: string): { id: string; draft?: string } {
  const url = linkUrl(link);
  if (!url) return { id: '' };
  return { id: slugFromUrl(url), draft: draftFromUrl(url) };
}

/** A `Link: <url>; rel="..."` or a bare `<url>` / url → the URL string. */
function linkUrl(link: string): string {
  const brace = link.match(/<([^>]*)>/);
  if (brace) return brace[1]!;
  const token = (link.trim().split(/\s|;/)[0] ?? '').trim();
  return token.startsWith('http') ? token : '';
}

/** https://h.example.com/r/73 → https://h.example.com/r/73. */
function slugFromUrl(url: string): string {
  try {
    return new URL(url).pathname;
  } catch {
    return url;
  }
}

/** A draft label is best-effort; used only if the body carried no draft. */
function draftFromUrl(url: string): string | undefined {
  try {
    return new URL(url).hostname || undefined;
  } catch {
    return undefined;
  }
}

/** Alias used by the top-level parse path for a link given via options. */
function linkId(link?: string): string {
  if (!link) return '';
  return extractLink(link.trim()).id;
}

