/**
 * The ledger is the broker's source of truth: every fetch the broker
 * attempted — fulfilled, denied, failed — appears exactly once.
 *
 * `seq` is monotonically increasing and gap-free; that invariant is what the
 * reconciliation step verifies. If the broker crashes or an origin
 * settlement is missing, reconciliation surfaces it instead of hiding it.
 */
export class AuditLedger {
  readonly entries: LedgerEntry[] = [];
  private seq = 0;
  private readonly clock: Clock;

  constructor(options?: { clock?: Clock }) {
    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
  }

  /** Append one row for one fetch attempt. Idempotent per fetchId. */
  record(outcome: FetchOutcome, options?: { tenantId?: string }): LedgerEntry {
    const existing = this.entries.find((e) => e.fetchId === outcome.fetchId);
    if (existing) return existing;

    this.seq += 1;
    const now = this.clock.now();
    const row: LedgerEntry = {
      seq: this.seq,
      fetchId: outcome.fetchId,
      tenantId: options?.tenantId ?? outcome.tenantId ?? 'default',
      url: outcome.origin?.url ?? 'unknown',
      status: outcome.status === 'fulfilled' ? 'fulfilled' : 'denied',
      failureClass: outcome.failureClass,
      httpStatus: outcome.origin?.httpStatus,
      priceMicros: outcome.price?.unitsMicros,
      currency: outcome.price?.currency,
      rail: outcome.rail,
      licenseId: outcome.license?.id,
      keyId: outcome.identity?.keyId,
      settlementRef: outcome.settlementRef,
      startedAt: outcome.timestamps.startedAt,
      completedAt: outcome.timestamps.completedAt,
      recordedAt: now,
    };
    this.entries.push(row);
    return row;
  }

  /** Gap-free, monotonically increasing seq. */
  lastSeq(): number {
    return this.seq;
  }

  byTenant(tenantId: string): LedgerEntry[] {
    return this.entries.filter((e) => e.tenantId === tenantId);
  }

  byUrl(url: string): LedgerEntry[] {
    return this.entries.filter((e) => e.url === url);
  }

  toRows(): LedgerEntry[] {
    return this.entries.map((e) => structuredClone(e));
  }
}

export interface LedgerSummary {
  total: number;
  fulfilled: number;
  denied: number;
  byFailureClass: Record<string, number>;
  spendMicros: number;
  byRail: Record<string, number>;
  byLicense: Record<string, number>;
}

export function summarize(rows: LedgerEntry[]): LedgerSummary {
  const s: LedgerSummary = {
    total: rows.length,
    fulfilled: 0,
    denied: 0,
    byFailureClass: {},
    spendMicros: 0,
    byRail: {},
    byLicense: {},
  };
  for (const r of rows) {
    if (r.status === 'fulfilled') s.fulfilled += 1;
    else s.denied += 1;
    if (r.failureClass) s.byFailureClass[r.failureClass] = (s.byFailureClass[r.failureClass] ?? 0) + 1;
    if (r.status === 'fulfilled' && r.priceMicros != null) s.spendMicros += r.priceMicros;
    if (r.rail) s.byRail[r.rail] = (s.byRail[r.rail] ?? 0) + 1;
    if (r.licenseId) s.byLicense[r.licenseId] = (s.byLicense[r.licenseId] ?? 0) + 1;
  }
  return s;
}

export interface ReconciliationReport {
  ok: boolean;
  problems: string[];
  checks: {
    seqGapFree: boolean;
    deniedHasFailureClass: boolean;
    fulfilledHasSettlement: boolean;
    fulfilledHasPrice: boolean;
  };
}

/**
 * Reconcile the ledger against invariants:
 *  - seq is gap-free starting at 1
 *  - every denied row has a failureClass (the three-classes invariant)
 *  - every fulfilled row has a settlementRef (we paid, we can prove it)
 *  - every fulfilled row has a price (we can bill what we paid)
 */
export function reconcile(rows: LedgerEntry[]): ReconciliationReport {
  const problems: string[] = [];

  const seqGapFree =
    rows.length === 0 ||
    rows.every((r, i) => r.seq === i + 1);

  const deniedHaveFC = rows
    .filter((r) => r.status !== 'fulfilled')
    .every((r) => r.failureClass !== undefined);

  const fulfilledHasSett = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => (r.settlementRef ?? '').length > 0);

  const fulfilledHasPrice = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => r.priceMicros != null && r.priceMicros > 0);

  if (!seqGapFree) problems.push('seq is not gap-free starting at 1');
  if (!deniedHaveFC) problems.push('a denied row lacks a failureClass');
  if (!fulfilledHasSett)
    problems.push('a fulfilled row lacks a settlementRef (settlement not proven)');
  if (!fulfilledHasPrice) problems.push('a fulfilled row lacks a positive price');

  return {
    ok:
      seqGapFree && deniedHaveFC && fulfilledHasSett && fulfilledHasPrice,
    problems,
    checks: { seqGapFree, deniedHasFailureClass: deniedHaveFC, fulfilledHasSettlement: fulfilledHasSett, fulfilledHasPrice },
  };
}

export type { FailureClass };

import {
  type ContractCard,
  type TerminalKind,
  type ValidationResult,
} from './types.js';

/**
 * The four terminal classes the broker reports. Derived in one place so the
 * identity + audit + contract-shape validators agree on the vocabulary.
 */
const TERMINAL_CLASSES: ReadonlySet<string> = new Set<TerminalKind>([
  'fulfilled',
  'blocked',
  'payment-required',
  'token-rejected',
]);

/** The RSL `rel` the broker reads as the published license-terms link. */
const LICENSE_REL = 'type:license-terms';

/**
 * A single contract-shape helper, factored out so each message is built once.
 */
function result(name: string, ok: boolean, message: string): ValidationResult {
  return { name, ok, message };
}

/**
 * Derive a license id from a Link href the same way the broker's RSL engine
 * does: extract the URL, then take its pathname — not the full href. A bare
 * `/r/73` stays `/r/73`; an absolute `https://licenses.example/r/73` collapses
 * to `/r/73`. Query and hash fragments are dropped, matching the engine's
 * `extractLink`/`slugFromUrl`.
 */
function deriveId(href: string): string {
  const brace = href.match(/<([^>]*)>/);
  const url = brace ? brace[1] : href.split(/\s|;/)[0];
  if (!url) return '';
  try {
    return new URL(url).pathname;
  } catch {
    return url;
  }
}

/** identity — PACT key/pactToken present and structurally consistent. */
function validateIdentity(card: ContractCard): ValidationResult {
  const id = card.identity;

  // Identity is best-effort, never a gate: an absent PACT is valid.
  if (!id || typeof id.keyId !== 'string' || id.keyId.length === 0) {
    return result('identity', true, 'PACT not presented (identity is best-effort, not a gate)');
  }

  // When a PACT is present it must be structured consistently. The broker
  // issues a PACT only when a KeyRing AND an identity.subject are both
  // present — so a subject implies a token, and a token implies a subject.
  const hasSubject = typeof id.subject === 'string' && id.subject.length > 0;
  const hasToken = typeof id.pactToken === 'string' && id.pactToken.length > 0;
  if (hasSubject !== hasToken) {
    return result(
      'identity',
      false,
      'a PACT requires both identity.subject and pactToken ' +
        '(subject present=' + hasSubject + ', token present=' + hasToken + ')',
    );
  }

  return result(
    'identity',
    true,
    'identity PACT consistent (keyId=' +
      id.keyId +
      (id.subject ? ', subject=' + id.subject : '') +
      ')',
  );
}

/** license — RSL Link resolves, obligations derive, id is the pathname. */
function validateLicense(card: ContractCard): ValidationResult {
  // A license surfaces only on a fulfilled outcome; a denied outcome carries
  // none and is not an error.
  if (card.status !== 'fulfilled') {
    return result('license', true, 'denied — no license to validate');
  }

  const license = card.license;
  if (!license) {
    return result('license', false, 'a fulfilled outcome must reference its license terms');
  }
  if (typeof license.id !== 'string' || license.id.length === 0) {
    return result('license', false, 'license id is missing');
  }

  // An RSL `Link` header with rel="type:license-terms" must identify the doc,
  // and the license id must equal the href's pathname, not the full href.
  if (card.linkHref != null && card.linkHref !== '') {
    if (card.linkHref.indexOf(LICENSE_REL) === -1) {
      return result(
        'license',
        false,
        'the RSL Link must carry rel="' +
          LICENSE_REL +
          '" (found: ' +
          card.linkHref +
          ')',
      );
    }
    const derived = deriveId(card.linkHref);
    if (derived !== license.id) {
      return result(
        'license',
        false,
        'license id must equal the Link href pathname (' +
          derived +
          '), not the full href',
      );
    }
  }

  // Obligations derive from the license: clauses present ⇒ obligations present,
  // one per clause; absent ⇒ no obligations.
  const clauseCount = (license.clauses ?? []).length;
  const obligationCount = (card.obligations ?? []).length;
  if (clauseCount > 0 && obligationCount === 0) {
    return result('license', false, 'license clauses present but no obligations were derived');
  }
  if (clauseCount > 0 && obligationCount !== clauseCount) {
    return result(
      'license',
      false,
      'expected one obligation per clause (' +
        clauseCount +
        '), derived ' +
        obligationCount,
    );
  }

  return result(
    'license',
    true,
    'license ' +
      license.id +
      ' (' +
      clauseCount +
      (clauseCount === 1 ? ' clause' : ' clauses') +
      ' → ' +
      obligationCount +
      ' obligation' +
      (obligationCount === 1 ? '' : 's') +
      ')',
  );
}

/** audit/settlement — rows well-formed, the spend sums, valid terminal class. */
function validateSettlement(card: ContractCard): ValidationResult {
  // A denied outcome records no spend: that is correct and passes.
  if (card.status === 'denied') {
    return result('settlement', true, 'denied — no spend recorded');
  }

  // A fulfilled outcome paid: every spend line needs a price + settlement ref,
  // and the sum must reconcile with the recorded price.
  const rows = card.spendLines ?? [];
  if (rows.length === 0) {
    return result('settlement', false, 'a fulfilled outcome has no spend lines');
  }
  if (card.price == null) {
    return result('settlement', false, 'a fulfilled outcome must carry a price');
  }

  const spend: number[] = [];
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    if (row == null || typeof row.priceMicros !== 'number' || Number.isNaN(row.priceMicros)) {
      return result('settlement', false, 'spend line ' + i + ' has a non-numeric priceMicros');
    }
    if (typeof row.settlementRef !== 'string' || row.settlementRef.length === 0) {
      return result(
        'settlement',
        false,
        'spend line ' + i + ' (' + (row.fetchId ?? '#' + i) + ') has no settlementRef',
      );
    }
    spend.push(row.priceMicros);
  }

  const summed = spend.reduce((acc, n) => acc + n, 0);
  if (card.price.unitsMicros !== summed) {
    return result(
      'settlement',
      false,
      'spend line sum ' +
        summed +
        ' != recorded price ' +
        card.price.unitsMicros,
    );
  }

  return result(
    'settlement',
    true,
    'settlement consistent across ' + rows.length + ' line(s), sum ' + summed,
  );
}

/** contract-shape (gateway) — outcome shape, terminal class, denied class. */
function validateContractShape(card: ContractCard): ValidationResult {
  if (card.status === 'fulfilled') {
    // Fulfilled releases content + license + a settlement proof.
    if (!card.content || typeof card.content.body !== 'string') {
      return result('contract-shape', false, 'content block is missing/invalid');
    }
    if (!card.license) {
      return result('contract-shape', false, 'license block is missing');
    }
    if (card.settlementRef == null || card.settlementRef.length === 0) {
      return result('contract-shape', false, 'a fulfilled outcome must carry a settlementRef');
    }
  } else {
    // Denied has no content/license/settlement — it must carry a failureClass.
    if (card.failureClass == null || card.failureClass.length === 0) {
      return result('contract-shape', false, 'a denied outcome must carry a failureClass');
    }
  }

  // The terminal decision must be one of the four classes.
  const terminal = card.status === 'fulfilled' ? 'fulfilled' : card.failureClass;
  if (terminal == null || !TERMINAL_CLASSES.has(terminal)) {
    return result(
      'contract-shape',
      false,
      'decision is not one of the 4 terminal classes: ' + JSON.stringify(terminal),
    );
  }

  return result(
    'contract-shape',
    true,
    'contract shape OK (' +
      (card.status === 'fulfilled' ? 'fulfilled' : card.failureClass) +
      ')',
  );
}

/** A conformance validator: one named predicate over the contract card. */
export type ValidatorFn = (card: ContractCard) => ValidationResult;

/**
 * The four validators, keyed to the public one-contract surface. Each reads
 * the card as plain data — no broker internals are imported.
 */
export const VALIDATORS: ReadonlyArray<[string, ValidatorFn]> = [
  ['identity', validateIdentity],
  ['license', validateLicense],
  ['settlement', validateSettlement],
  ['contract-shape', validateContractShape],
];

import { registry } from './registry.js';
import {
  type ContractCard,
  type ConformanceResult,
  type ValidationResult,
} from './types.js';

/** ANSI helpers for the terminal PASS/FAIL summary. */
const CONFORMANCE_OK = '\x1B[32m'; // green
const CONFORMANCE_WARN = '\x1B[31m'; // red
const RESET = '\x1B[0m';

/**
 * Run every registered validator over a card.
 *
 * Each validator's result is collected; `pass` is true only when every
 * validator returned ok.
 */
export function run(card: ContractCard, contractName: string): ConformanceResult {
  const results: ValidationResult[] = [];
  for (const name of registry.names()) {
    results.push(registry.get(name)(card));
  }
  return {
    contract: card,
    contractName,
    results,
    pass: results.every((r) => r.ok),
  };
}

/**
 * Render a green/red PASS/FAIL summary to stdout. Each of the four validators
 * gets a line; a single failure is enough to flip the whole gate to red.
 */
export function report(result: ConformanceResult): void {
  const bar = '\u2500'.repeat(64);
  const line = (text: string) => console.log(text);

  line('');
  line(bar);
  line(`  conformance · ${result.contractName}`);
  line(bar);

  for (const r of result.results) {
    const tick = r.ok ? '✓' : '✗';
    const colour = r.ok ? CONFORMANCE_OK : CONFORMANCE_WARN;
    line(`  ${colour}${tick}${RESET}  ${r.name.padEnd(14)} ${r.message}`);
  }

  line(bar);
  const verdict = result.pass ? 'PASS' : 'FAIL';
  const verdictColour = result.pass ? CONFORMANCE_OK : CONFORMANCE_WARN;
  const failed = result.results.filter((r) => !r.ok).length;
  line(`  ${verdictColour}${verdict}${RESET}  — ${result.results.length} validators, ${failed} failed`);
  line('');
}

