import { readFileSync } from 'node:fs';
import { report, run } from './run.js';
import type { ContractCard, ConformanceResult } from './types.js';

/**
 * The entry point CI invokes:
 *
 *   tsx packages/conformance/src/cli.ts <fixturePath> <contractName>
 *
 * Reads + JSON-parses the fixture, resolves the validators by contractName,
 * runs them, reports, and exits 0 on full pass / 1 on any failure.
 */
function main(argv: string[]): number {
  const [fixturePath, contractName] = argv;

  if (!fixturePath || !contractName) {
    console.error('usage: conformance <fixturePath> <contractName>');
    return 1;
  }

  let card: ContractCard;
  try {
    card = JSON.parse(readFileSync(fixturePath, 'utf8')) as ContractCard;
  } catch (cause) {
    console.error(`failed to read fixture "${fixturePath}": ${(cause as Error).message}`);
    return 1;
  }

  const result: ConformanceResult = run(card, contractName);
  report(result);
  return result.pass ? 0 : 1;
}

process.exit(main(process.argv.slice(2)));

/**
 * The public "one contract" surface, as a standalone card.
 *
 * The broker's single endpoint returns exactly { content, license, settlement
 * receipt } and every terminal decision decodes to one of four classes. This
 * module names that shape so the four validators below can validate a card
 * against it without importing any broker internals.
 *
 * The card is intentionally a superset of FetchOutcome: the audit row records
 * the subset of the outcome the ledger cares about (price + settlementRef), so
 * the card carries those too. The identity claim mirrors
 * IdentityPresentation — the shape the broker surfaces when a KeyRing AND an
 * identity.subject are both present.
 */

/** The four terminal classes the broker reports on the audit surface. */
export type TerminalKind =
  | 'fulfilled'
  | 'blocked'
  | 'payment-required'
  | 'token-rejected';

/** An RSL clause as the broker's license engine normalises it (draft field names). */
export interface LicenseClauseCard {
  type: string;
  value?: string | number | boolean;
  params?: Record<string, string | number>;
}

/** A license terms document, as surfaced on a fulfilled outcome. */
export interface LicenseCard {
  id: string;
  draft?: string;
  title?: string;
  clauses?: LicenseClauseCard[];
}

/**
 * An identity claim: what the broker records when a KeyRing is present and a
 * subject is known. `keyId` identifies the active key; `pactToken` is the
 * optional PACT attestation the origin may verify (present iff a subject was
 * issued).
 */
export interface IdentityCard {
  keyId: string;
  subject?: string;
  pactToken?: string;
}

/** One spend line in the settlement receipt. */
export interface SpendLineCard {
  fetchId: string;
  priceMicros: number;
  settlementRef: string;
}

/** A broker audit card — the public one-contract shape, in record form. */
export interface ContractCard {
  fetchId: string;
  status: 'fulfilled' | 'denied';
  failureClass?: TerminalKind;
  reason: string;
  content?: {
    body: string;
    contentType: string;
    storeable: boolean;
  };
  license?: LicenseCard;
  obligations?: Array<{ clause: string; kind: string; instruction: string }>;
  price?: { unitsMicros: number; currency: string };
  identity?: IdentityCard;
  /** The RSL `Link` header (or bare href) identifying the license, if any. */
  linkHref?: string | null;
  /** The top-level settlement ref, present iff the outcome is fulfilled. */
  settlementRef?: string | null;
  spendLines: SpendLineCard[];
  timestamps: { startedAt: string; completedAt: string };
}

/** The result of a single validator over the card. */
export interface ValidationResult {
  name: string;
  ok: boolean;
  message: string;
}

/** The full conformance outcome for one card. */
export interface ConformanceResult {
  contract: ContractCard;
  contractName: string;
  results: ValidationResult[];
  pass: boolean;
}

/** A named validator. */
export type ValidatorFn = (card: ContractCard) => ValidationResult;

/**
 * A typed error carrying the failing validator name, so the CLI can print a
 * clean "validator X failed: message" line instead of an uncaught throw.
 */
export class ConformanceError extends Error {
  readonly name: string;
  constructor(name: string, message: string) {
    super(message);
    this.name = name;
  }
}

import {
  type ValidatorFn,
  VALIDATORS,
} from './validators.js';

export { type ValidatorFn, VALIDATORS };

/**
 * The registry of named conformance validators. Each validator is keyed by the
 * name the CLI and fixtures refer to; a lookup by name lets an unknown contract
 * name fail fast instead of silently validating against the wrong ruleset.
 */
export class Registry {
  private readonly map = new Map<string, ValidatorFn>();

  constructor(validators: readonly [string, ValidatorFn][] = VALIDATORS) {
    for (const [name, fn] of validators) {
      if (this.map.has(name)) {
        throw new Error(`duplicate validator registered: ${name}`);
      }
      this.map.set(name, fn);
    }
  }

  /** Whether a validator with this name exists. */
  has(name: string): boolean {
    return this.map.has(name);
  }

  /** Look up a validator by name, or throw a typed error if it is unknown. */
  get(name: string): ValidatorFn {
    const fn = this.map.get(name);
    if (!fn) {
      throw new Error(`unknown contract name: ${name}`);
    }
    return fn;
  }

  /** All registered validator names, in registration order. */
  names(): string[] {
    return [...this.map.keys()];
  }
}

/** The default registry built from the four contract validators. */
export const registry = new Registry();

