import {
  RailError,
  makeSettlementRef,
  type Clock,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type Micros,
} from '@mwb/core';

/**
 * A rail is a backend: quote → authorize → settle, all behind one
 * interface. Field names inside `payload` are intentionally opaque — the
 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
 * finalized), so the broker never parses them. Draft-caveat discipline:
 * build against the interface, not a draft's field names.
 */
export interface RailBackend extends PaymentRail {}

/**
 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
 * (micro-unit price, `X-PAYMENT` header) without an external service.
 * Deterministic: with a `frozenClock` and fixed input, the settlement
 * reference is stable so reconciliation can be asserted.
 */
export class InMemoryRail implements PaymentRail {
  readonly id: string;
  readonly priceMicros: Micros;
  readonly currency: string;
  readonly clock: Clock;
  private readonly settlementSeed: string = '';
  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';

  constructor(options: {
    id: string;
    priceMicros: Micros;
    currency?: string;
    clock?: Clock;
    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    /** Stable suffix seed so settlement refs are deterministic in tests. */
    settlementSeed?: string;
  }) {
    this.id = options.id;
    this.priceMicros = options.priceMicros;
    this.currency = options.currency ?? 'USD';
    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    this.failureMode = options.failureMode ?? 'none';
    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
  }

  quote(_req: PaymentRequest): Promise<Quote> {
    if (this.failureMode === 'quote') {
      return Promise.reject(
        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
      );
    }
    const nowMs = Date.parse(this.clock.now());
    return Promise.resolve({
      unitsMicros: this.priceMicros,
      currency: this.currency,
      rail: this.id,
      settlement: 'immediate',
      expiresAt: new Date(nowMs + 60_000).toISOString(),
    });
  }

  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    if (this.failureMode === 'authorize') {
      return Promise.reject(
        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
      );
    }
    const payload = JSON.stringify({
      schema: 'urn:rail:' + this.id,
      amountMicros: quote.unitsMicros,
      currency: quote.currency,
      url: String(req.url),
      method: req.method,
    });
    return Promise.resolve({
      scheme: this.id,
      payload,
      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    });
  }

  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    if (this.failureMode === 'settle') {
      return Promise.reject(
        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
      );
    }
    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    return Promise.resolve({
      rail: this.id,
      // Deterministic from (seed, url) so tests can assert reconciliation.
      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
      amountMicros: parsed.amountMicros,
      currency: parsed.currency,
      settledAt: this.clock.now(),
    });
  }
}

/**
 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
 * only this minimal shape — it does not depend on the bridge's own types.
 * That is the "one contract" boundary in practice.
 */
export interface BridgeClientShape {
  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
  authorize(input: {
    url: string;
    method: string;
    headers: Record<string, string>;
    quote: { unitsMicros: number; currency: string };
  }): Promise<RailAuthorization>;
  settle(input: {
    url: string;
    method: string;
    headers: Record<string, string>;
    authorization: RailAuthorization;
  }): Promise<RailSettlement>;
}

export class BridgeRail implements PaymentRail {
  constructor(
    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
  ) {}

  get id(): string {
    return this.idAndBridge.id;
  }

  quote(req: PaymentRequest): Promise<Quote> {
    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
  }

  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    return this.idAndBridge.bridge.authorize({
      url: String(req.url),
      method: req.method,
      headers: req.headers,
      quote: { unitsMicros: quote.unitsMicros, currency: quote.currency },
    });
  }

  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    return this.idAndBridge.bridge.settle({
      url: String(req.url),
      method: req.method,
      headers: req.headers,
      authorization,
    });
  }
}

/** Registry lets the broker pick a rail per URL/tenant without touching the agent. */
export class RailRegistry {
  private readonly rails = new Map<string, PaymentRail>();

  register(rail: PaymentRail): this {
    if (this.rails.has(rail.id)) {
      throw new RailError(`Rail already registered: ${rail.id} (deregister first)`, 'RAIL_REGISTER');
    }
    this.rails.set(rail.id, rail);
    return this;
  }

  deregister(id: string): boolean {
    return this.rails.delete(id);
  }

  get(id: string): PaymentRail {
    const r = this.rails.get(id);
    if (!r) throw new RailError(`No rail registered: ${id}`, 'RAIL_MISSING');
    return r;
  }

  /** Look up a rail by id without throwing when it is absent. */
  optional(id: string): PaymentRail | undefined {
    return this.rails.get(id);
  }

  ids(): string[] {
    return [...this.rails.keys()].sort();
  }
}

/** Deterministic PRNG from a seed (FNV-1a based) so settlement refs are stable in tests. */
function deterministicRand(seed: string): () => number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return () => {
    h += 0x6d2b79f5;
    let t = h;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

import {
  BudgetError,
  IdentityError,
  PaymentRequiredError,
  RailError,
  isBrokerError,
  makeFetchId,
  systemClock,
  type Clock,
  type FetchOutcome,
  type FailureClass,
  type HeaderRecord,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type UrlString,
} from '@mwb/core';
import { BudgetEngine } from '@mwb/budget';
import { AuditLedger } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import {
  deriveObligations,
  parseLicense,
  resolveStoreability,
} from '@mwb/license';

/**
 * The Metered Web Broker orchestrator — the "one contract" call.
 *
 * `Broker.fetch` composes the budget gate, the payment rail, best-effort
 * identity, the license engine, and the audit ledger into a single terminal
 * outcome. The whole thing is designed around one invariant:
 *
 *   every terminal path is one of {fulfilled, blocked, payment-required,
 *   token-rejected} — `error` status is deliberately NOT produced, because a
 *   generic failure hides the cost decision.
 *
 * Pipeline:
 *
 *   1. rail.quote(request)        → quote (the origin's price)
 *   2. budget.preflight(quote)    → `blocked`        if policy denies it
 *   3. rail.authorize(quote)      → `payment-required` if the rail can't pay
 *   4. rail.settle(auth)          → `payment-required` if settlement fails
 *   5. identity.bestEffortSign    → recorded, never a gate
 *   6. origin.fetch(…, settlement) → fulfilled / 402 → payment-required /
 *                                  403 + identity → token-rejected /
 *                                  403 no identity → blocked / else → blocked
 *   7. license.parse + derive from the origin's RSL `Link` header
 *
 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
 * exactly one `AuditLedger` row is recorded for the `fetchId`.
 */

/** The content/SLA source the rail's settled request is sent to. */
export interface OriginResponse {
  httpStatus: number;
  headers: HeaderRecord;
  body: string;
}

export interface OriginClient {
  fetch(req: PaymentRequest): Promise<OriginResponse>;
}

export interface BrokerIdentityOptions {
  /** Subject/tenant to embed in the PACT, if a ring is present and a subject is known. */
  subject?: string;
}

export interface BrokerOptions {
  rail: PaymentRail;
  budget: BudgetEngine;
  ledger: AuditLedger;
  /** Identity vault. Absent ⇒ no identity presented (a 403 then reads as `blocked`). */
  ring?: KeyRing;
  /** Content/SLA source. Required — this is what the broker is metered to fetch. */
  origin: OriginClient;
  clock?: Clock;
  identity?: BrokerIdentityOptions;
  /** Extra headers presented on every origin fetch. Never secrets. */
  headers?: HeaderRecord;
}

/** The broker's terminal decision, decoded by the audit layer and agents. */
export type TerminalKind = 'fulfilled' | 'blocked' | 'payment-required' | 'token-rejected';

/**
 * The Broker. One call composes the whole metered-web decision stack.
 *
 * Injecting every collaborator (rail, budget, ledger, ring, origin, clock)
 * is what makes the terminal-path mapping and the "one row + recordPaid once"
 * guarantee fully testable.
 */
export class Broker {
  private readonly rail: PaymentRail;
  private readonly budget: BudgetEngine;
  private readonly ledger: AuditLedger;
  private readonly ring?: KeyRing;
  private readonly origin: OriginClient;
  private readonly clock: Clock;
  private readonly identityOpts: BrokerIdentityOptions;
  private readonly headers: HeaderRecord;

  /** Cached terminal outcomes keyed by fetchId ⇒ one row + one charge per id. */
  private readonly outcomes = new Map<string, FetchOutcome>();

  constructor(options: BrokerOptions) {
    this.rail = options.rail;
    this.budget = options.budget;
    this.ledger = options.ledger;
    this.ring = options.ring;
    this.origin = options.origin;
    this.clock = options.clock ?? systemClock;
    this.identityOpts = options.identity ?? {};
    this.headers = options.headers ?? {};
  }

  /**
   * Perform one metered fetch and return its terminal outcome.
   *
   * Idempotent by `fetchId`: a second call with the same id returns the
   * cached outcome without re-quoting, re-settling, or charging the meter.
   */
  async fetch(params: {
    url: UrlString;
    fetchId?: string;
    headers?: HeaderRecord;
    tenantId?: string;
    rand?: () => number;
  }): Promise<FetchOutcome> {
    const fetchId = params.fetchId ?? makeFetchId(params.rand);
    const existing = this.outcomes.get(fetchId);
    if (existing) return this.cloneOutcome(existing);

    const startedAt = this.clock.now();
    const tenantId = params.tenantId ?? 'default';

    try {
      const outcome = await this.run(fetchId, startedAt, params.url, tenantId, params.headers);
      // Cache the terminal outcome so a repeat fetchId returns the SAME
      // object without re-quoting, re-settling, or charging the meter.
      this.outcomes.set(fetchId, outcome);
      return outcome;
    } finally {
      // startedAt is carried forward on the outcome's timestamps.
      void startedAt;
    }
  }

  /** The single terminal outcome for a fetchId, or undefined. */
  outcomeFor(fetchId: string): FetchOutcome | undefined {
    const o = this.outcomes.get(fetchId);
    return o ? this.cloneOutcome(o) : undefined;
  }

  /** The one ledger row recorded for a fetchId, or undefined. */
  rowFor(fetchId: string) {
    return this.ledger.entries.find((e) => e.fetchId === fetchId);
  }

  // --- the compose pipeline ---------------------------------------------

  private async run(
    fetchId: string,
    startedAt: string,
    url: UrlString,
    tenantId: string,
    extraHeaders?: HeaderRecord
  ): Promise<FetchOutcome> {
    const req = this.paymentRequest(url, extraHeaders);
    const identity = this.signIdentity(req);

    // 1. Quote the rail — the origin's price, needed to gate on budget.
    const quote = await this.rail.quote(req);

    // 2. Budget gate (the first deny-gate). BudgetError is policy denial.
    try {
      this.budget.preflight(tenantId, quote, url);
    } catch (err) {
      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
        return this.denied(fetchId, tenantId, 'blocked',
          err instanceof Error ? err.message : String(err), { url, httpStatus: undefined });
      }
      throw err;
    }

    // 3. Authorize. A rail error here means payment could not be arranged
    //    — a terminal `payment-required` decision, not a thrown fault.
    let authorization: RailAuthorization;
    try {
      authorization = await this.rail.authorize(req, quote);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'authorize', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
    let settlement: RailSettlement;
    try {
      settlement = await this.rail.settle(req, authorization);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'settle', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 5. Content from the origin, settlement headers applied.
    const originResp = await this.origin.fetch({
      ...req,
      headers: { ...req.headers, ...authorization.settlementHeaders },
    });

    // 6. Map the origin's HTTP answer to a terminal class.
    if (!isOk(originResp.httpStatus)) {
      return this.originDenied(fetchId, tenantId, originUrl(originResp, url), originResp.httpStatus, identity != null);
    }

    // fulfilled — charge the meter once and record one row.
    return this.fulfilled({
      url,
      fetchId,
      tenantId,
      quote,
      settlement,
      identity,
      origin: originResp,
      startedAt,
    });
  }

  // --- outcome builders --------------------------------------------------

  private fulfilled(args: {
    url: UrlString;
    fetchId: string;
    tenantId: string;
    quote: Quote;
    settlement: RailSettlement;
    identity?: IdentityPresentation;
    origin: OriginResponse;
    startedAt: string;
  }): FetchOutcome {
    // 7. License — if the origin publishes RSL terms, derive obligations.
    const license = parseOriginLicense(args.origin.headers);
    const obligations = license ? deriveObligations(license) : [];
    const storeable = license ? resolveStoreability(license) : true;

    // Charge the tenant meter exactly once, on fulfillment.
    this.budget.recordPaid(
      args.tenantId,
      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      args.url
    );

    const outcome: FetchOutcome = {
      fetchId: args.fetchId,
      status: 'fulfilled',
      reason: 'content released after settlement',
      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
      content: {
        body: args.origin.body,
        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
        storeable,
        attributionNotice: attributionNotice(license),
      },
      license,
      obligations,
      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      quote: args.quote,
      rail: args.settlement.rail,
      settlementRef: args.settlement.settlementRef,
      identity: args.identity?.keyId ? identityToPresentation(args.identity) : undefined,
      tenantId: args.tenantId,
      timestamps: { startedAt: args.startedAt, completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId: args.tenantId });
    return outcome;
  }

  private denied(
    fetchId: string,
    tenantId: string,
    failureClass: FailureClass,
    message: string,
    info: { url: UrlString; httpStatus?: number }
  ): FetchOutcome {
    const outcome: FetchOutcome = {
      fetchId,
      status: 'denied',
      failureClass,
      reason: message,
      error: { code: failureClass, message },
      origin: info.httpStatus != null
        ? { url: String(info.url), httpStatus: info.httpStatus }
        : { url: String(info.url) },
      tenantId,
      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId });
    return outcome;
  }

  private originDenied(
    fetchId: string,
    tenantId: string,
    url: string,
    httpStatus: number,
    identityPresent: boolean
  ): FetchOutcome {
    let failureClass: FailureClass;
    let message: string;
    let code: string;

    if (httpStatus === 402) {
      failureClass = 'payment-required';
      message = 'origin still demanded payment after settlement (not obtainable)';
      code = 'PAYMENT_REQUIRED';
    } else if (httpStatus === 403 && identityPresent) {
      failureClass = 'token-rejected';
      message = 'origin rejected the presented attestation/identity (HTTP 403)';
      code = 'TOKEN_REJECTED';
    } else if (httpStatus === 403) {
      failureClass = 'blocked';
      message = 'origin blocked the request without a presented identity (HTTP 403)';
      code = 'ORIGIN_BLOCKED';
    } else {
      failureClass = 'blocked';
      message = `origin rejected the request with HTTP ${httpStatus}`;
      code = 'ORIGIN_REJECTED';
    }

    return this.denied(fetchId, tenantId, failureClass, message, { url: url as UrlString, httpStatus });
  }

  // --- identity + request helpers ----------------------------------------

  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
    return {
      url,
      method: 'GET',
      headers: {
        host: new URL(String(url)).host,
        'user-agent': 'metered-web-broker/0.1',
        ...this.headers,
        ...(extraHeaders ?? {}),
      },
    };
  }

  /**
   * Best-effort identity: sign the presented headers and, when a known
   * subject exists, issue a PACT. Returns undefined when no ring is present,
   * no active key exists, or signing throws. Never a gate.
   */
  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
    if (!this.ring) return undefined;

    const keyId = this.ring.active()[0]?.keyId;
    if (!keyId) return undefined;

    // Canonical block the origin can verify: host + date.
    const signingHeaders: HeaderRecord = {
      host: new URL(String(req.url)).host,
      date: this.clock.now(),
      ...req.headers,
    };

    let signedFields: string[];
    try {
      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
    } catch (cause) {
      if (cause instanceof IdentityError) return undefined;
      throw cause;
    }

    let pactToken: string | undefined;
    const subject = this.identityOpts.subject;
    if (subject) {
      try {
        const body = {
          subject,
          grants: [],
          iat: this.clock.now(),
          iss: 'metered-web-broker',
        };
        pactToken = PACT.issue(this.ring, keyId, body).token;
      } catch {
        // Best-effort: a failed PACT issuance is ignored, not a gate.
      }
    }

    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
  }

  private cloneOutcome(o: FetchOutcome): FetchOutcome {
    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
  }
}

/** Identity presentation surfaced on a fulfilled outcome. */
interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  pactToken?: string;
}

function identityToPresentation(x: IdentityPresentation): FetchOutcome['identity'] {
  return {
    keyId: x.keyId,
    algorithm: x.algorithm,
    signedHeaders: x.signedHeaders,
    timestamp: x.timestamp,
    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
  };
}

function isOk(httpStatus: number): boolean {
  return httpStatus >= 200 && httpStatus < 300;
}

/** A best-effort origin URL for denied rows when the fetch request was dropped. */
function originUrl(resp: OriginResponse, url: UrlString): string {
  return headersUrl(resp) ?? String(url);
}

function headersUrl(resp: OriginResponse): string | undefined {
  const u = resp.headers['location'] ?? resp.headers['Location'];
  if (u) try { return new URL(u).toString(); } catch { return undefined; }
  return undefined;
}

/** Wrap a rail failure as a `payment-required` fault. */
function railFault(err: unknown, step: 'authorize' | 'settle', railId: string): Error {
  if (isBrokerError(err)) return err;
  const cause = err instanceof Error ? err : new Error(String(err));
  return new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', cause, true);
}

/** Parse the RSL `Link` header from origin response headers, if present. */
function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
  const link = headers['link'] ?? headers['Link'];
  if (!link) return undefined;
  try {
    return parseLicense(link, { link });
  } catch {
    return undefined; // best-effort: a bad Link is not a terminal failure
  }
}

/** Attribution notice surfaced on fulfilled content, if the license requires it. */
function attributionNotice(
  license: FetchOutcome['license']
): string | undefined {
  if (!license) return undefined;
  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
  if (!clause) return undefined;
  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
  return `Attribution required: ${by}`;
}

/**
 * Self-hosted 402 settlement backend.
 *
 * The metered path (see `packages/gateway/src/broker.ts`) is:
 *
 *   rail.quote -> rail.authorize -> rail.settle -> origin.fetch(...)
 *
 * The rail's `settle` step is the payment commit. Previously `SelfHosted402Rail`
 * only extended the in-memory stub, so a "self 402" never actually minted a
 * proof, rejected a reused proof, or recorded a final receipt. This module
 * makes it real:
 *
 *   1. The broker signs an Ed25519 **payment mandate** (a spend authorization)
 *      over an opaque manifest, carrying a per-request nonce.
 *   2. The rail POSTs that signed mandate to a settlement backend. The backend
 *      verifies the signature, rejects a **replayed** nonce, signs a chained
 *      settlement **receipt**, and returns it. A replayed proof throws
 *      `RAIL_REPLAY` (non-retryable) — the broker maps a settle fault to
 *      `payment-required`, exactly as an origin that still demanded payment.
 *   3. The receipt lands in a small, Ed25519-**chained, tamper-evident ledger**
 *      that the audit/`reconcile` surface can read.
 *
 * The wire form is intentionally minimal (draft-caveat: build against the
 * *pattern* of x402's `PAYMENT-SIGNATURE`/`X-PAYMENT`, not its field names).
 * The same backend runs in-process (tests, dev) or behind a thin HTTP service
 * (`SettlementHttpServer`) on a separate host (`HttpSettlementClient`), so the
 * rail needs no compile-time knowledge of where the backend lives.
 *
 * Crypto mirrors `packages/identity/src/ring.ts`: Ed25519 over a JWK, and the
 * broker's own `b64url`/`fromB64url` from `@mwb/core`. No new dependency.
 */

import {
  generateKeyPairSync,
  sign,
  verify,
  createPrivateKey,
  createPublicKey,
  randomBytes,
} from 'node:crypto';
import {
  RailError,
  systemClock,
  b64url,
  fromB64url,
  type Clock,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type Micros,
} from '@mwb/core';

/** The opaque mandate type the broker mints. Not a draft's field set. */
const PAYMENT_MANDATE_TYPE = 'urn:mwb:self402:payment-mandate:v1';

/** Fixed key order so the manifest bytes are byte-identical at sign and verify. */
const MANDATE_FIELDS = [
  'origin',
  'url',
  'amountMicros',
  'currency',
  'nonce',
  'issuedAt',
  'recipient',
] as const;

/** Accept a mandate whose `issuedAt` is within this window of the clock. */
const ACCEPTANCE_WINDOW_MS = 5 * 60 * 1000;

/** The header the rail injects on the settled origin request (holds the proof). */
export const PAYMENT_HEADER = 'x-payment';

/** An Ed25519 spend-authorizer. `privateKey` never leaves the signing side. */
export interface SettlementKey {
  keyId: string;
  algorithm: 'ed25519';
  /** 32-byte public key, JWK `x`, base64url. Shares the verifier. */
  publicKey: string;
  /** 32-byte seed, JWK `d`, base64url. Never leaves the broker. */
  privateKey: string;
  createdAt: string;
}

/** Mint a settlement key (broker's spend authorizer). */
export function makeSettlementKey(
  clock: Clock = systemClock,
  keyId = `settle_${clock.now().replace(/[^A-Za-z0-9]/g, '')}`,
): SettlementKey {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
  const pub = publicKey.export({ format: 'jwk' }) as { x?: string };
  const priv = privateKey.export({ format: 'jwk' }) as { d?: string };
  if (!pub.x || !priv.d) {
    throw new RailError('failed to export Ed25519 JWK', 'SETTLEMENT_KEY');
  }
  return {
    keyId,
    algorithm: 'ed25519',
    publicKey: b64url(fromB64url(pub.x)),
    privateKey: b64url(fromB64url(priv.d)),
    createdAt: clock.now(),
  };
}

function privateKeyObject(k: SettlementKey): ReturnType<typeof createPrivateKey> {
  return createPrivateKey({
    format: 'jwk',
    key: { kty: 'OKP', crv: 'Ed25519', d: k.privateKey, x: k.publicKey },
  });
}

function publicKeyObject(k: SettlementKey): ReturnType<typeof createPublicKey> {
  return createPublicKey({
    format: 'jwk',
    key: { kty: 'OKP', crv: 'Ed25519', x: k.publicKey },
  });
}

function signBytes(k: SettlementKey, buf: Buffer): string {
  return b64url(new Uint8Array(sign(null, buf, privateKeyObject(k))));
}

function verifyBytes(k: SettlementKey, buf: Buffer, sigB64: string): boolean {
  try {
    return verify(null, buf, publicKeyObject(k), Buffer.from(fromB64url(sigB64)));
  } catch {
    return false;
  }
}

/** The signed spend authorization the broker mints and the rail commits. */
export interface PaymentMandateManifest {
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  nonce: string;
  issuedAt: string;
  recipient: string;
}

export interface PaymentMandate extends PaymentMandateManifest {
  /**
   * 64-byte Ed25519 signature, base64url-encoded (86 chars, no padding). The
   * wire form always sets it, but a hand-edited/tampered mandate may omit it.
   */
  signature?: string;
}

function manifestBytes(m: PaymentMandateManifest): Buffer {
  const obj: Record<string, number | string> = {};
  for (const f of MANDATE_FIELDS) obj[f] = m[f];
  return Buffer.from(JSON.stringify(obj), 'utf8');
}

/** Build (sign) a payment mandate. */
export function buildMandate(o: {
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  recipient: string;
  clock: Clock;
  key: SettlementKey;
  nonce?: string;
  issuedAt?: string;
}): PaymentMandate {
  const nonce = o.nonce ?? randomBytes(32).toString('base64url');
  const issuedAt = o.issuedAt ?? o.clock.now();
  const manifest: PaymentMandateManifest = {
    origin: o.origin,
    url: o.url,
    amountMicros: o.amountMicros,
    currency: o.currency,
    nonce,
    issuedAt,
    recipient: o.recipient,
  };
  return { ...manifest, signature: signBytes(o.key, manifestBytes(manifest)) };
}

export interface VerifyResult {
  valid: boolean;
  reason?: string;
}

/**
 * Verify a mandate's signature, manifest, and acceptance window. Does not
 * consume the nonce — the origin can call this to gate content release.
 */
export function verifyMandate(
  m: PaymentMandate,
  key: SettlementKey,
  opts?: { nowMs?: number },
): VerifyResult {
  if (typeof m.signature !== 'string' || m.signature.length === 0) {
    return { valid: false, reason: 'missing-signature' };
  }
  if (!verifyBytes(key, manifestBytes(m), m.signature)) {
    return { valid: false, reason: 'signature-mismatch' };
  }
  const iat = Date.parse(m.issuedAt);
  if (Number.isNaN(iat)) return { valid: false, reason: 'bad-issuedAt' };
  const nowMs = opts?.nowMs ?? Date.now();
  if (Math.abs(nowMs - iat) > ACCEPTANCE_WINDOW_MS) {
    return { valid: false, reason: 'issued-out-of-window' };
  }
  if (!(m.amountMicros > 0)) return { valid: false, reason: 'non-positive-amount' };
  return { valid: true };
}

/** A receipt minted by the backend, signed by its key. */
export interface SettlementReceipt {
  settlementRef: string;
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  nonce: string;
  issuedAt: string;
  settledAt: string;
}

/** One entry in the chained, tamper-evident settlement ledger. */
export interface LedgerRecord {
  seq: number;
  receipt: SettlementReceipt;
  signedAt: string;
  /** Signature over `${seq}\0${ref}\0${previousSignature}`. */
  signature: string;
}

/**
 * The settlement backend: verifies signed mandates, enforces replay
 * protection (a nonce is consumed exactly once), and records a final,
 * cryptographically-chained receipt ledger. Runs in-process.
 */
export class SettlementServer {
  readonly key: SettlementKey;
  readonly clock: Clock;
  private readonly consumed = new Set<string>();
  private readonly ledgerRows: LedgerRecord[] = [];

  constructor(options: { key: SettlementKey; clock?: Clock }) {
    this.key = options.key;
    this.clock = options.clock ?? systemClock;
  }

  /** Pure: is this mandate's signature valid and in-window? (No state change.) */
  isValidMandate(m: PaymentMandate): boolean {
    return verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) }).valid;
  }

  /** Verify and, on first use, consume the nonce, then mint a receipt. */
  verify(m: PaymentMandate): VerifyResult {
    const v = verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) });
    if (!v.valid) return v;
    if (this.consumed.has(m.nonce)) {
      return { valid: false, reason: 'replayed-proof' };
    }
    return { valid: true };
  }

  /**
   * The payment commit. Verifies, rejects a replayed nonce (throwing
   * `RAIL_REPLAY`, non-retryable), records a chained receipt, and returns the
   * `RailSettlement` the broker surfaces on a fulfilled outcome.
   */
  settle(m: PaymentMandate): RailSettlement {
    const v = this.verify(m);
    if (!v.valid) {
      throw new RailError(
        `settlement rejected: ${v.reason ?? 'unknown'}`,
        'RAIL_SETTLE',
        undefined,
        false,
      );
    }
    const settledAt = this.clock.now();
    const settlementRef = `settle_self402_${randomBytes(9).toString('hex')}`;
    const receipt: SettlementReceipt = {
      settlementRef,
      origin: m.origin,
      url: m.url,
      amountMicros: m.amountMicros,
      currency: m.currency,
      nonce: m.nonce,
      issuedAt: m.issuedAt,
      settledAt,
    };
    const prevSig = this.ledgerRows.length > 0 ? this.ledgerRows[this.ledgerRows.length - 1]!.signature : 'genesis';
    const seq = this.ledgerRows.length + 1;
    const chain = Buffer.from(`${seq}\u0000${receipt.settlementRef}\u0000${prevSig}`, 'utf8');
    const signature = signBytes(this.key, chain);
    this.ledgerRows.push({ seq, receipt, signedAt: settledAt, signature });
    this.consumed.add(m.nonce);
    return {
      rail: 'self402',
      settlementRef,
      amountMicros: m.amountMicros,
      currency: m.currency,
      settledAt,
    };
  }

  /** The current settlement ledger (a copy) — surfaced on the audit view. */
  ledger(): LedgerRecord[] {
    return this.ledgerRows.map((r) => ({ ...r, receipt: { ...r.receipt } }));
  }

  /** How many distinct nonces have been settled (== ledger length). */
  settledCount(): number {
    return this.ledgerRows.length;
  }
}

/**
 * A `PaymentRail` backed by a settlement backend (in-process
 * `SettlementServer`, or a remote `HttpSettlementClient`). The rail signs the
 * mandate (with the broker's key) and commits it via the backend. Spec-agnostic
 * — the broker only sees `quote/authorize/settle`.
 */
export class SelfHosted402Rail implements PaymentRail {
  readonly id = 'self402';

  constructor(
    private readonly backend: SettlementBackend,
    private readonly key: SettlementKey,
    private readonly opts: {
      priceMicros: Micros;
      currency?: string;
      clock?: Clock;
      origin?: string;
    },
  ) {}

  async quote(_req: PaymentRequest): Promise<Quote> {
    const nowMs = Date.parse(this.opts.clock?.now() ?? systemClock.now());
    return {
      unitsMicros: this.opts.priceMicros,
      currency: this.opts.currency ?? 'USD',
      rail: this.id,
      settlement: 'immediate',
      expiresAt: new Date(nowMs + 60_000).toISOString(),
    };
  }

  async authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    const origin = this.opts.origin ?? new URL(String(req.url)).origin;
    const mandate = buildMandate({
      origin,
      url: String(req.url),
      amountMicros: quote.unitsMicros,
      currency: this.opts.currency ?? 'USD',
      recipient: this.key.keyId,
      clock: this.opts.clock ?? systemClock,
      key: this.key,
    });
    const xPayment = encodeXPayment(mandate);
    return {
      scheme: this.id,
      payload: JSON.stringify(mandate),
      settlementHeaders: { [PAYMENT_HEADER]: xPayment },
    };
  }

  async settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    const mandate = JSON.parse(authorization.payload) as PaymentMandate;
    if (mandate.url !== String(req.url)) {
      throw new RailError('settlement mandate does not match the request', 'RAIL_SETTLE');
    }
    return this.backend.settle(mandate);
  }
}

/**
 * The backend contract the rail commits through: the settle commit, a pure
 * `isValidMandate` cross-check (an origin can use it), and the key id the
 * receipt references.
 */
export interface SettlementBackend {
  settle(mandate: PaymentMandate): Promise<RailSettlement>;
  isValidMandate(mandate: PaymentMandate): boolean;
  readonly keyId: string;
}

// `SettlementServer` is synchronous at its crypto core, but the rail is async,
// so wrap the commit in a resolved promise to keep one uniform shape.
function ok(s: RailSettlement): Promise<RailSettlement> {
  return Promise.resolve(s);
}

export class InProcessSettlementBackend implements SettlementBackend {
  readonly keyId: string;

  constructor(private readonly server: SettlementServer) {
    // `keyId` reads the parameter property, so it must be initialized inside
    // the constructor body — a field initializer runs *before* parameter
    // properties are assigned (TS2729: used before initialization).
    this.keyId = this.server.key.keyId;
  }

  settle(mandate: PaymentMandate): Promise<RailSettlement> {
    return ok(this.server.settle(mandate));
  }
  isValidMandate(mandate: PaymentMandate): boolean {
    return this.server.isValidMandate(mandate);
  }
}

/**
 * Convenience: a `SelfHosted402Rail` over an in-process `SettlementServer`,
 * sharing its key. This is the default wiring in `packages/gateway/src/server.ts`.
 */
export function makeSelf402Rail(
  server: SettlementServer,
  options: { priceMicros: Micros; currency?: string; clock?: Clock; origin?: string } = {
    priceMicros: 5000,
  },
): SelfHosted402Rail {
  return new SelfHosted402Rail(
    new InProcessSettlementBackend(server),
    server.key,
    options,
  );
}

/** The decoded wire payload carried in the `x-payment` header. */
export interface XPayment {
  type: string;
  mandate: PaymentMandate;
}

/** Encode the proof header value (`x-payment`). */
export function encodeXPayment(mandate: PaymentMandate): string {
  return b64url(
    Buffer.from(
      JSON.stringify({ type: PAYMENT_MANDATE_TYPE, mandate } satisfies XPayment),
      'utf8',
    ),
  );
}

/** Decode the proof header value; throws on malformed input. */
export function decodeXPayment(value: string): PaymentMandate {
  let raw: string;
  try {
    // Base64url must round-trip exactly; if it does not, the header is
    // malformed (not merely un-JSON). Reject it as such.
    const bytes = fromB64url(value);
    if (b64url(bytes) !== value) {
      throw new Error('not valid base64url');
    }
    raw = Buffer.from(bytes).toString('utf8');
  } catch (cause) {
    throw new RailError('malformed x-payment header', 'SETTLEMENT_DECODE', cause);
  }
  let parsed: XPayment;
  try {
    parsed = JSON.parse(raw) as XPayment;
  } catch (cause) {
    throw new RailError('x-payment is not JSON', 'SETTLEMENT_DECODE', cause);
  }
  if (!parsed || parsed.type !== PAYMENT_MANDATE_TYPE || !parsed.mandate) {
    throw new RailError('unknown x-payment shape', 'SETTLEMENT_DECODE');
  }
  return parsed.mandate;
}

/**
 * A `SettlementBackend` that commits against a *remote* settlement service over
 * HTTP (standalone `SettlementHttpServer`). Lets the backend run on its own
 * host while the rail stays identical. `isValidMandate` is a local signature
 * check (the remote cannot see the broker's key) plus a freshness read.
 */
export class HttpSettlementClient implements SettlementBackend {
  constructor(
    private readonly url: string,
    private readonly key: SettlementKey,
  ) {}

  get keyId(): string {
    return this.key.keyId;
  }

  isValidMandate(m: PaymentMandate): boolean {
    return verifyMandate(m, this.key, { nowMs: Date.now() }).valid;
  }

  async settle(m: PaymentMandate): Promise<RailSettlement> {
    const res = await fetch(`${this.url.replace(/\/$/, '')}/settle`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(m),
    });
    if (!res.ok) {
      // A settlement rejection (e.g. replayed nonce) is the payment rail
      // "still demanding payment" — surface it as a non-retryable settle fault.
      let reason: string | undefined;
      try {
        const json = (await res.json()) as { reason?: string };
        reason = json.reason;
      } catch {
        /* ignore */
      }
      throw new RailError(
        `settlement service returned ${res.status}${reason ? `: ${reason}` : ''}`,
        'RAIL_SETTLE',
        undefined,
        reason === 'replayed-proof',
      );
    }
    const body = (await res.json()) as RailSettlement & { receipt: SettlementReceipt };
    if (!body.settlementRef) {
      throw new RailError('settlement service returned no ref', 'RAIL_SETTLE');
    }
    return body;
  }
}

// --- Standalone settlement HTTP service -----------------------------------

/**
 * A tiny, dependency-free HTTP surface over a `SettlementServer`. The
 * settlement service is its own process on the backend host; this exposes just
 * what a `HttpSettlementClient` (and any independent auditor) needs:
 *
 *   GET  /health        -> liveness, with backend keyId and ledger depth
 *   POST /accept         -> verify a mandate's signature (non-consuming)
 *   POST /settle         -> the payment commit (consumes the nonce)
 *   GET  /ledger         -> the chained, tamper-evident receipt ledger
 *
 * The router (a `RouteTable`) is pure so it can be unit-tested by dispatching
 * decoded requests; the server just funnels a raw request through it. Tests bind
 * this to a `listen(0)` socket (no fixed port), so the routing is covered
 * without opening any socket.
 */
interface Decoded {
  pathname: string;
  body?: unknown;
}

type Result = { status: number; body: unknown };

type Handle = (req: Decoded) => Promise<Result> | Result;

class RouteTable {
  private readonly routes: { method: 'GET' | 'POST'; pattern: RegExp; handle: Handle }[] = [];

  add(method: 'GET' | 'POST', pattern: RegExp, handle: Handle): void {
    this.routes.push({ method, pattern, handle });
  }

  async dispatch(
    method: 'GET' | 'POST',
    pathname: string,
    raw: string,
  ): Promise<Result> {
    const decoded: Decoded = {
      pathname,
      body: method === 'POST' ? decodeBody(raw) : undefined,
    };
    for (const r of this.routes) {
      if (r.method !== method || !r.pattern.test(pathname)) continue;
      return r.handle(decoded);
    }
    return {
      status: 404,
      body: { error: 'not-found', detail: `${method} ${pathname} matches no route` },
    };
  }
}

function decodeBody(raw: string): unknown {
  if (!raw || raw.trim().length === 0) return {};
  return JSON.parse(raw) as unknown;
}

export class SettlementHttpServer {
  readonly table = new RouteTable();

  constructor(private readonly server: SettlementServer) {
    // Liveness: is the backend up, and what is its depth of settlements?
    this.table.add('GET', /^\/health$/, () => ({
      status: 200,
      body: {
        status: 'ok',
        keyId: this.server.key.keyId,
        settled: this.server.settledCount(),
        ledgerDepth: this.server.ledger().length,
      },
    }));

    // Accept: verify a mandate's signature without consuming its nonce.
    // This is what an origin would call before releasing content.
    this.table.add('POST', /^\/accept$/, (req) => {
      let m: PaymentMandate;
      try {
        m = req.body as PaymentMandate;
      } catch {
        return { status: 400, body: { error: 'bad-request', detail: 'missing mandate' } };
      }
      const valid = this.server.isValidMandate(m);
      return {
        status: valid ? 200 : 402,
        body: {
          valid,
          keyId: this.server.key.keyId,
        },
      };
    });

    // Settle: the payment commit. Verifies, enforces replay protection,
    // records a chained receipt, and returns it.
    this.table.add('POST', /^\/settle$/, (req) => {
      let m: PaymentMandate;
      try {
        m = req.body as PaymentMandate;
      } catch {
        return { status: 400, body: { error: 'bad-request', detail: 'missing mandate' } };
      }
      try {
        const settlement = this.server.settle(m);
        return {
          status: 200,
          body: {
            rail: settlement.rail,
            settlementRef: settlement.settlementRef,
            amountMicros: settlement.amountMicros,
            currency: settlement.currency,
            settledAt: settlement.settledAt,
          },
        };
      } catch (cause) {
        // A non-retryable reject (e.g. replayed nonce) is the backend "still
        // demanding payment" — return 402 so the client maps it to a
        // payment-required outcome.
        if (isRailError(cause) && cause.retryable === false) {
          return {
            status: 402,
            body: { error: 'settlement-rejected', reason: reasonOf(cause) },
          };
        }
        return { status: 500, body: { error: 'internal', detail: 'settlement error' } };
      }
    });

    // Ledger: the full, chained, tamper-evident receipt ledger.
    this.table.add('GET', /^\/ledger$/, () => ({
      status: 200,
      body: {
        keyId: this.server.key.keyId,
        count: this.server.ledger().length,
        records: this.server.ledger(),
      },
    }));
  }

  /** The backend's key id (for the standalone health endpoint / wiring). */
  get keyId(): string {
    return this.server.key.keyId;
  }

  /**
   * Dispatch a raw request through the router. `pathname` should be path only
   * (no query string). This is the seam tested by the HTTP integration test.
   */
  async dispatch(
    method: 'GET' | 'POST',
    pathname: string,
    raw = '',
  ): Promise<Result> {
    return this.table.dispatch(method, pathname, raw);
  }
}

function isRailError(e: unknown): e is RailError {
  return e instanceof RailError;
}

function reasonOf(e: RailError): string {
  // The settle fault carries the backend's rejection reason in its message.
  const m = /\s*:\s*([a-z-]+)$/.exec(e.message);
  return m ? m[1] ?? 'settlement-rejected' : 'settlement-rejected';
}

import {
  BudgetError,
  IdentityError,
  PaymentRequiredError,
  RailError,
  isBrokerError,
  makeFetchId,
  systemClock,
  type Clock,
  type FetchOutcome,
  type FailureClass,
  type HeaderRecord,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type UrlString,
} from '@mwb/core';
import { BudgetEngine } from '@mwb/budget';
import { AuditLedger, reconcile } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import {
  deriveObligations,
  parseLicense,
  resolveStoreability,
} from '@mwb/license';

/**
 * The Metered Web Broker orchestrator — the "one contract" call.
 *
 * `Broker.fetch` composes the budget gate, the payment rail, best-effort
 * identity, the license engine, and the audit ledger into a single terminal
 * outcome. The whole thing is designed around one invariant:
 *
 *   every terminal path is one of {fulfilled, blocked, payment-required,
 *   token-rejected} — `error` status is deliberately NOT produced, because a
 *   generic failure hides the cost decision.
 *
 * Pipeline:
 *
 *   1. rail.quote(request)        → quote (the origin's price)
 *   2. budget.preflight(quote)    → `blocked`        if policy denies it
 *   3. rail.authorize(quote)      → `payment-required` if the rail can't pay
 *   4. rail.settle(auth)          → `payment-required` if settlement fails
 *   5. identity.bestEffortSign    → recorded, never a gate
 *   6. origin.fetch(…, settlement) → fulfilled / 402 → payment-required /
 *                                  403 + identity → token-rejected /
 *                                  403 no identity → blocked / else → blocked
 *   7. license.parse + derive from the origin's RSL `Link` header
 *
 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
 * exactly one `AuditLedger` row is recorded for the `fetchId`.
 */

/** The content/SLA source the rail's settled request is sent to. */
export interface OriginResponse {
  httpStatus: number;
  headers: HeaderRecord;
  body: string;
}

export interface OriginClient {
  fetch(req: PaymentRequest): Promise<OriginResponse>;
}

export interface BrokerIdentityOptions {
  /** Subject/tenant to embed in the PACT, if a ring is present and a subject is known. */
  subject?: string;
}

export interface BrokerOptions {
  rail: PaymentRail;
  budget: BudgetEngine;
  ledger: AuditLedger;
  /** Identity vault. Absent ⇒ no identity presented (a 403 then reads as `blocked`). */
  ring?: KeyRing;
  /** Content/SLA source. Required — this is what the broker is metered to fetch. */
  origin: OriginClient;
  clock?: Clock;
  identity?: BrokerIdentityOptions;
  /** Extra headers presented on every origin fetch. Never secrets. */
  headers?: HeaderRecord;
}

/** The broker's terminal decision, decoded by the audit layer and agents. */
export type TerminalKind = 'fulfilled' | 'blocked' | 'payment-required' | 'token-rejected';

/**
 * The Broker. One call composes the whole metered-web decision stack.
 *
 * Injecting every collaborator (rail, budget, ledger, ring, origin, clock)
 * is what makes the terminal-path mapping and the "one row + recordPaid once"
 * guarantee fully testable.
 */
export class Broker {
  private readonly rail: PaymentRail;
  private readonly budget: BudgetEngine;
  private readonly ledger: AuditLedger;
  private readonly ring?: KeyRing;
  private readonly origin: OriginClient;
  private readonly clock: Clock;
  private readonly identityOpts: BrokerIdentityOptions;
  private readonly headers: HeaderRecord;

  /** Cached terminal outcomes keyed by fetchId ⇒ one row + one charge per id. */
  private readonly outcomes = new Map<string, FetchOutcome>();

  constructor(options: BrokerOptions) {
    this.rail = options.rail;
    this.budget = options.budget;
    this.ledger = options.ledger;
    this.ring = options.ring;
    this.origin = options.origin;
    this.clock = options.clock ?? systemClock;
    this.identityOpts = options.identity ?? {};
    this.headers = options.headers ?? {};
  }

  /**
   * Perform one metered fetch and return its terminal outcome.
   *
   * Idempotent by `fetchId`: a second call with the same id returns the
   * cached outcome without re-quoting, re-settling, or charging the meter.
   */
  async fetch(params: {
    url: UrlString;
    fetchId?: string;
    headers?: HeaderRecord;
    tenantId?: string;
    rand?: () => number;
  }): Promise<FetchOutcome> {
    const fetchId = params.fetchId ?? makeFetchId(params.rand);
    const existing = this.outcomes.get(fetchId);
    if (existing) return this.cloneOutcome(existing);

    const startedAt = this.clock.now();
    const tenantId = params.tenantId ?? 'default';

    try {
      const outcome = await this.run(fetchId, startedAt, params.url, tenantId, params.headers);
      // Cache the terminal outcome so a repeat fetchId returns the SAME
      // object without re-quoting, re-settling, or charging the meter.
      this.outcomes.set(fetchId, outcome);
      return outcome;
    } finally {
      // startedAt is carried forward on the outcome's timestamps.
      void startedAt;
    }
  }

  /** The single terminal outcome for a fetchId, or undefined. */
  outcomeFor(fetchId: string): FetchOutcome | undefined {
    const o = this.outcomes.get(fetchId);
    return o ? this.cloneOutcome(o) : undefined;
  }

  /** The one ledger row recorded for a fetchId, or undefined. */
  rowFor(fetchId: string) {
    return this.ledger.entries.find((e) => e.fetchId === fetchId);
  }

  // --- the compose pipeline ---------------------------------------------

  private async run(
    fetchId: string,
    startedAt: string,
    url: UrlString,
    tenantId: string,
    extraHeaders?: HeaderRecord
  ): Promise<FetchOutcome> {
    const req = this.paymentRequest(url, extraHeaders);
    const identity = this.signIdentity(req);

    // 1. Quote the rail — the origin's price, needed to gate on budget.
    const quote = await this.rail.quote(req);

    // 2. Budget gate (the first deny-gate). BudgetError is policy denial.
    try {
      this.budget.preflight(tenantId, quote, url);
    } catch (err) {
      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
        return this.denied(fetchId, tenantId, 'blocked',
          err instanceof Error ? err.message : String(err), { url, httpStatus: undefined });
      }
      throw err;
    }

    // 3. Authorize. A rail error here means payment could not be arranged
    //    — a terminal `payment-required` decision, not a thrown fault.
    let authorization: RailAuthorization;
    try {
      authorization = await this.rail.authorize(req, quote);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'authorize', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
    let settlement: RailSettlement;
    try {
      settlement = await this.rail.settle(req, authorization);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'settle', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 5. Content from the origin, settlement headers applied.
    const originResp = await this.origin.fetch({
      ...req,
      headers: { ...req.headers, ...authorization.settlementHeaders },
    });

    // 6. Map the origin's HTTP answer to a terminal class.
    if (!isOk(originResp.httpStatus)) {
      return this.originDenied(fetchId, tenantId, originUrl(originResp, url), originResp.httpStatus, identity != null);
    }

    // fulfilled — charge the meter once and record one row.
    return this.fulfilled({
      url,
      fetchId,
      tenantId,
      quote,
      settlement,
      identity,
      origin: originResp,
      startedAt,
    });
  }

  // --- outcome builders --------------------------------------------------

  private fulfilled(args: {
    url: UrlString;
    fetchId: string;
    tenantId: string;
    quote: Quote;
    settlement: RailSettlement;
    identity?: IdentityPresentation;
    origin: OriginResponse;
    startedAt: string;
  }): FetchOutcome {
    // 7. License — if the origin publishes RSL terms, derive obligations.
    const license = parseOriginLicense(args.origin.headers);
    const obligations = license ? deriveObligations(license) : [];
    const storeable = license ? resolveStoreability(license) : true;

    // Charge the tenant meter exactly once, on fulfillment.
    this.budget.recordPaid(
      args.tenantId,
      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      args.url
    );

    const outcome: FetchOutcome = {
      fetchId: args.fetchId,
      status: 'fulfilled',
      reason: 'content released after settlement',
      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
      content: {
        body: args.origin.body,
        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
        storeable,
        attributionNotice: attributionNotice(license),
      },
      license,
      obligations,
      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      quote: args.quote,
      rail: args.settlement.rail,
      settlementRef: args.settlement.settlementRef,
      identity: args.identity?.keyId ? identityToPresentation(args.identity) : undefined,
      tenantId: args.tenantId,
      timestamps: { startedAt: args.startedAt, completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId: args.tenantId });

    // Finality: only when the ledger as a whole reconciles clean is the
    // fulfillment *finally* settled — not merely the origin returning 200. A
    // malformed row elsewhere on the ledger (a lost settlement, a missing
    // price) makes reconcile().ok false, so this fetch is `'claimed'`, never
    // `'final'` — the caller never bets real settlement on an assumption.
    const rep = reconcile(this.ledger.entries);
    if (rep.ok) {
      outcome.finality = 'final';
    } else {
      outcome.finality = 'claimed';
    }

    return outcome;
  }

  private denied(
    fetchId: string,
    tenantId: string,
    failureClass: FailureClass,
    message: string,
    info: { url: UrlString; httpStatus?: number }
  ): FetchOutcome {
    const outcome: FetchOutcome = {
      fetchId,
      status: 'denied',
      failureClass,
      reason: message,
      error: { code: failureClass, message },
      origin: info.httpStatus != null
        ? { url: String(info.url), httpStatus: info.httpStatus }
        : { url: String(info.url) },
      tenantId,
      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId });
    return outcome;
  }

  private originDenied(
    fetchId: string,
    tenantId: string,
    url: string,
    httpStatus: number,
    identityPresent: boolean
  ): FetchOutcome {
    let failureClass: FailureClass;
    let message: string;
    let code: string;

    if (httpStatus === 402) {
      failureClass = 'payment-required';
      message = 'origin still demanded payment after settlement (not obtainable)';
      code = 'PAYMENT_REQUIRED';
    } else if (httpStatus === 403 && identityPresent) {
      failureClass = 'token-rejected';
      message = 'origin rejected the presented attestation/identity (HTTP 403)';
      code = 'TOKEN_REJECTED';
    } else if (httpStatus === 403) {
      failureClass = 'blocked';
      message = 'origin blocked the request without a presented identity (HTTP 403)';
      code = 'ORIGIN_BLOCKED';
    } else {
      failureClass = 'blocked';
      message = `origin rejected the request with HTTP ${httpStatus}`;
      code = 'ORIGIN_REJECTED';
    }

    return this.denied(fetchId, tenantId, failureClass, message, { url: url as UrlString, httpStatus });
  }

  // --- identity + request helpers ----------------------------------------

  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
    return {
      url,
      method: 'GET',
      headers: {
        host: new URL(String(url)).host,
        'user-agent': 'metered-web-broker/0.1',
        ...this.headers,
        ...(extraHeaders ?? {}),
      },
    };
  }

  /**
   * Best-effort identity: sign the presented headers and, when a known
   * subject exists, issue a PACT. Returns undefined when no ring is present,
   * no active key exists, or signing throws. Never a gate.
   */
  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
    if (!this.ring) return undefined;

    const keyId = this.ring.active()[0]?.keyId;
    if (!keyId) return undefined;

    // Canonical block the origin can verify: host + date.
    const signingHeaders: HeaderRecord = {
      host: new URL(String(req.url)).host,
      date: this.clock.now(),
      ...req.headers,
    };

    let signedFields: string[];
    try {
      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
    } catch (cause) {
      if (cause instanceof IdentityError) return undefined;
      throw cause;
    }

    let pactToken: string | undefined;
    const subject = this.identityOpts.subject;
    if (subject) {
      try {
        const body = {
          subject,
          grants: [],
          iat: this.clock.now(),
          iss: 'metered-web-broker',
        };
        pactToken = PACT.issue(this.ring, keyId, body).token;
      } catch {
        // Best-effort: a failed PACT issuance is ignored, not a gate.
      }
    }

    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
  }

  private cloneOutcome(o: FetchOutcome): FetchOutcome {
    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
  }
}

/** Identity presentation surfaced on a fulfilled outcome. */
interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  pactToken?: string;
}

function identityToPresentation(x: IdentityPresentation): FetchOutcome['identity'] {
  return {
    keyId: x.keyId,
    algorithm: x.algorithm,
    signedHeaders: x.signedHeaders,
    timestamp: x.timestamp,
    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
  };
}

function isOk(httpStatus: number): boolean {
  return httpStatus >= 200 && httpStatus < 300;
}

/** A best-effort origin URL for denied rows when the fetch request was dropped. */
function originUrl(resp: OriginResponse, url: UrlString): string {
  return headersUrl(resp) ?? String(url);
}

function headersUrl(resp: OriginResponse): string | undefined {
  const u = resp.headers['location'] ?? resp.headers['Location'];
  if (u) try { return new URL(u).toString(); } catch { return undefined; }
  return undefined;
}

/** Wrap a rail failure as a `payment-required` fault. */
function railFault(err: unknown, step: 'authorize' | 'settle', railId: string): Error {
  if (isBrokerError(err)) return err;
  const cause = err instanceof Error ? err : new Error(String(err));
  return new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', cause, true);
}

/** Parse the RSL `Link` header from origin response headers, if present. */
function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
  const link = headers['link'] ?? headers['Link'];
  if (!link) return undefined;
  try {
    return parseLicense(link, { link });
  } catch {
    return undefined; // best-effort: a bad Link is not a terminal failure
  }
}

/** Attribution notice surfaced on fulfilled content, if the license requires it. */
function attributionNotice(
  license: FetchOutcome['license']
): string | undefined {
  if (!license) return undefined;
  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
  if (!clause) return undefined;
  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
  return `Attribution required: ${by}`;
}

export {
  Broker,
  type OriginClient,
  type OriginResponse,
  type BrokerOptions,
  type BrokerIdentityOptions,
  type TerminalKind,
} from './broker.js';

/**
 * P1 + P2: the load-bearing metered path, proven on REAL bytes.
 *
 * Not a stubbed rail, not a dummy origin. This wires the real
 * `SelfHosted402Rail` over an in-process `SettlementServer` (real Ed25519,
 * replay/nonce-guarded settlement — see `packages/rails/src/selfsettle.ts`)
 * behind a REAL metered origin that verifies the broker's signed payment
 * mandate against the settlement key's public part and enforces origin-side
 * replay protection, exactly as a real self-402 / x402 / Cloudflare-PPC origin
 * would. The broker only ever sees the opaque `quote → authorize → settle`
 * interface and a real origin that releases only after a real, verified 402
 * proof.
 *
 * P2: a fulfilled fetch is only `finality: 'final'` when the ledger as a whole
 * reconciles clean (`reconcile().ok === true`) — the settlement is proven, not
 * merely attempted.
 *
 * The metered pipeline (broker.ts) is: rail.quote → rail.authorize →
 * rail.settle → origin.fetch(...). Because the rail *always* signs a real
 * mandate, a real origin that releases on a valid proof yields the full
 * 402 → settle → 200 round trip; an origin that rejects a forged/replayed
 * proof yields the 402 leg on the same wire form.
 */

import { describe, expect, it } from 'vitest';
import { createServer, request } from 'node:http';
import { type AddressInfo } from 'node:net';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { AuditLedger, reconcile } from '@mwb/audit';
import {
  SelfHosted402Rail,
  SettlementServer,
  makeSelf402Rail,
  makeSettlementKey,
  verifyMandate,
  encodeXPayment,
  decodeXPayment,
} from '@mwb/rails';
import type { PaymentMandate, SettlementKey } from '@mwb/rails';
import { makeFetchId, systemClock, type Clock, type PaymentRequest, type UrlString } from '@mwb/core';
import { Broker, type OriginClient, type OriginResponse } from '@mwb/gateway';
import { handleFetch } from './server.js';

const clock: Clock = systemClock;
const PRICE = 5000;
const CONTENT_URL = 'https://api.example.com/data' as UrlString;

/**
 * A real metered origin. It never sees the broker's private key: it decodes
 * the broker's `x-payment` proof, verifies the Ed25519 signature + acceptance
 * window against the settlement key's public part, and refuses to release
 * content twice for the same proof (origin-side replay protection). A forged,
 * tampered, or replayed proof is answered HTTP 402 — exactly what a real
 * metered origin does.
 */
class RealMeteredOrigin implements OriginClient {
  private readonly key: SettlementKey;
  private readonly consumedNonce = new Set<string>();

  constructor(key: SettlementKey) {
    this.key = key;
  }

  async fetch(req: PaymentRequest): Promise<OriginResponse> {
    const header = req.headers['x-payment'];

    // No proof presented at all → a real metered origin demands payment.
    if (!header || typeof header !== 'string') {
      return { httpStatus: 402, headers: {}, body: 'payment required: no proof' };
    }

    let mandate: PaymentMandate;
    try {
      mandate = decodeXPayment(header); // throws on a malformed wire form
    } catch {
      return { httpStatus: 402, headers: {}, body: 'payment required: malformed proof' };
    }

    // Real Ed25519 verification against the settlement key's public part,
    // plus acceptance-window check. This is the origin's real gate.
    const v = verifyMandate(mandate, this.key);
    if (!v.valid) {
      return { httpStatus: 402, headers: {}, body: `payment required: ${v.reason ?? 'invalid proof'}` };
    }

    // Origin-side replay protection: the same real proof must not release
    // content twice.
    if (this.consumedNonce.has(mandate.nonce)) {
      return { httpStatus: 402, headers: {}, body: 'payment required: replayed proof' };
    }

    // Consume it, so a replay is refused next time.
    this.consumedNonce.add(mandate.nonce);

    return {
      httpStatus: 200,
      headers: { 'content-type': 'text/html; charset=utf-8' },
      body:
        '<html>real metered content — released only after a real, verified 402 proof</html>',
    };
  }

  /** How many distinct proofs have been released (== released twice-guarded). */
  get releasedCount(): number {
    return this.consumedNonce.size;
  }
}

/** Wire up the real rail + real origin + real budget, as production does. */
function make() {
  const key = makeSettlementKey(clock);
  const server = new SettlementServer({ key, clock });
  const rail = makeSelf402Rail(server, { priceMicros: PRICE, clock });
  const origin = new RealMeteredOrigin(key);
  const budget = new BudgetEngine({ policy: defaultPolicy, clock });
  const ledger = new AuditLedger({ clock });
  const broker = new Broker({ rail, budget, ledger, origin, clock });
  return { broker, server, rail, origin, ledger, key };
}

async function runOnce(fetchId = makeFetchId()) {
  const ctx = make();
  const outcome = await ctx.broker.fetch({ url: CONTENT_URL, fetchId });
  return { ...ctx, outcome };
}

describe('real 402 metered origin — 402 → settle → 200 round trip', () => {
  it("releases content after the rail's real Ed25519 proof, end to end", async () => {
    const { origin, server, ledger, outcome } = await runOnce();

    // The broker settled against the real backend (real nonce consumed once).
    expect(server.settledCount()).toBe(1);

    // The real origin verified the real signed proof and released exactly once.
    expect(origin.releasedCount).toBe(1);

    // Terminal outcome: fulfilled, with the settlement proven on the row.
    expect(outcome.status).toBe('fulfilled');
    expect(outcome.origin?.httpStatus).toBe(200);
    expect(outcome.settlementRef).toBeTruthy();
    expect(outcome.rail).toBe('self402');
    expect(outcome.price?.unitsMicros).toBe(PRICE);

    // One row recorded, and the audit reconciles clean (we paid, we can prove it).
    expect(ledger.entries.length).toBe(1);
    const rep = reconcile(ledger.entries);
    expect(rep.ok).toBe(true);
    expect(rep.problems).toEqual([]);
  });

  it('a fulfilled fetch is only `finality: final` when the ledger reconciles', async () => {
    // Share ONE ledger across the whole sequence: the broker's `ledger`
    // property can't be swapped after construction, so build once and reuse.
    const ctx = make();
    const first = await ctx.broker.fetch({ url: CONTENT_URL, fetchId: makeFetchId() });

    // P2: the first fulfillment is `final` because the (clean) ledger reconciles.
    expect(first.status).toBe('fulfilled');
    expect(first.finality).toBe('final');
    expect(reconcile(ctx.ledger.entries).ok).toBe(true);

    // Now poison the shared ledger with a fulfilled row that has no
    // settlementRef. A fulfilled row without a settlementRef makes
    // reconcile().ok === false.
    ctx.ledger.record({
      fetchId: 'poison',
      status: 'fulfilled',
      reason: 'injected to break reconciliation',
      origin: { url: 'https://bad.example/inject' },
      price: { unitsMicros: 100, currency: 'USD' },
      // intentionally no settlementRef
      tenantId: 'default',
      timestamps: { startedAt: clock.now(), completedAt: clock.now() },
    });

    // A NEW fetch on a ledger that can't reconcile is still fulfilled by the
    // origin (the real proof releases), but finality must be `claimed`, never
    // `final` — we never bet real settlement on an assumption.
    const second = await ctx.broker.fetch({ url: CONTENT_URL, fetchId: makeFetchId() });
    expect(second.status).toBe('fulfilled'); // origin released the real proof
    expect(second.finality).toBe('claimed'); // ...but the ledger won't reconcile
    expect(reconcile(ctx.ledger.entries).ok).toBe(false);
  });
});

describe('real 402 metered origin — the 402 legs on real bytes', () => {
  it('rejects a forged proof whose signature does not verify (402)', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: PRICE, clock });
    const origin = new RealMeteredOrigin(key);

    // Mint the real signed mandate the broker would present.
    const quote = await rail.quote({ url: CONTENT_URL, method: 'GET', headers: {} });
    const auth = await rail.authorize({ url: CONTENT_URL, method: 'GET', headers: {} }, quote);
    const mandate = JSON.parse(auth.payload) as PaymentMandate;

    // Tamper the amount: the signature is over the original manifest, so this
    // mandate no longer verifies — a real origin refuses it with 402.
    const tampered: PaymentMandate = { ...mandate, amountMicros: mandate.amountMicros + 1 };
    const wire = encodeXPayment(tampered);

    const resp = await origin.fetch({
      url: CONTENT_URL,
      method: 'GET',
      headers: { 'x-payment': wire },
    });
    expect(resp.httpStatus).toBe(402);
    expect(resp.body).toContain('signature-mismatch');
  });

  it('rejects a replayed proof (402) — real origin-side nonce guard', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: PRICE, clock });

    // Mint the real signed mandate.
    const quote = await rail.quote({ url: CONTENT_URL, method: 'GET', headers: {} });
    const auth = await rail.authorize({ url: CONTENT_URL, method: 'GET', headers: {} }, quote);
    const wire = auth.settlementHeaders['x-payment'] as string;
    const mandate = decodeXPayment(wire);
    const req = { url: CONTENT_URL, method: 'GET', headers: { 'x-payment': wire as string } } as PaymentRequest;

    const origin = new RealMeteredOrigin(key);

    // First release: valid proof, consumed → 200.
    const first = await origin.fetch(req);
    expect(first.httpStatus).toBe(200);
    expect(origin.releasedCount).toBe(1);

    // Replay the exact same real proof on the wire → 402. The origin's nonce
    // guard refuses the duplicate real proof, on the same base64url envelope.
    const replay = await origin.fetch(req);
    expect(replay.httpStatus).toBe(402);
    expect(replay.body).toContain('replayed');
  });

  it("a real origin that cannot verify the backend key's proof demands payment", async () => {
    // A different settlement key than the rail's — a mismatched origin cannot
    // verify the broker's proof, so it must demand payment (402), as a real
    // origin whose facilitator key does not match would.
    const wrong = makeSettlementKey(clock);
    const origin = new RealMeteredOrigin(wrong);
    const { rail } = make();

    const quote = await rail.quote({ url: CONTENT_URL, method: 'GET', headers: {} });
    const auth = await rail.authorize({ url: CONTENT_URL, method: 'GET', headers: {} }, quote);
    const wire = auth.settlementHeaders['x-payment'] as string;

    const resp = await origin.fetch({
      url: CONTENT_URL,
      method: 'GET',
      headers: { 'x-payment': wire as string },
    });
    expect(resp.httpStatus).toBe(402);
  });
});

describe('real 402 metered origin — over an actual HTTP socket', () => {
  it('POST /fetch returns 200 on a real metered release, then /audit reconciles', async () => {
    const { broker, ledger, origin } = make();

    // A tiny HTTP surface that funnels requests through the real handleFetch,
    // so the loop is proven on real bytes over a socket (not just in-process).
    const app = createServer((req, res) => {
      const chunks: Buffer[] = [];
      req.on('data', (c: Buffer) => chunks.push(c));
      req.on('end', async () => {
        try {
          const raw = Buffer.concat(chunks).toString('utf8');
          const { status, body } = await handleFetch(broker, raw);
          res.writeHead(status, { 'content-type': 'application/json' });
          res.end(JSON.stringify(body));
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          res.writeHead(500, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ error: 'server error', message }));
        }
      });
    });

    await new Promise<void>((resolve) => app.listen(0, resolve));
    const port = (app.address() as AddressInfo).port;

    try {
      const res = await new Promise<{ status: number; json: unknown }>((resolve, reject) => {
        const payload = JSON.stringify({ url: CONTENT_URL.toString(), fetchId: makeFetchId() });
        const req = request(
          { hostname: '127.0.0.1', port, path: '/fetch', method: 'POST', headers: { 'content-type': 'application/json' } },
          (resBody) => {
            const chunks: Buffer[] = [];
            resBody.on('data', (c: Buffer) => chunks.push(c));
            resBody.on('end', () => {
              try {
                resolve({ status: resBody.statusCode ?? 0, json: JSON.parse(Buffer.concat(chunks).toString('utf8')) });
              } catch (e) {
                reject(e as Error);
              }
            });
          },
        );
        req.on('error', reject);
        req.end(payload);
      });

      // 200 on the wire, fulfilled body, P2 finality, and the audit reconciles.
      expect(res.status).toBe(200);
      expect((res.json as { status: string }).status).toBe('fulfilled');
      expect((res.json as { finality: string }).finality).toBe('final');
      expect(origin.releasedCount).toBe(1);
      expect(reconcile(ledger.entries).ok).toBe(true);
    } finally {
      await new Promise<void>((resolve) => app.close(() => resolve()));
    }
  });
});

/**
 * Self-hosted 402 settlement backend.
 *
 * The metered path (see `packages/gateway/src/broker.ts`) is:
 *
 *   rail.quote -> rail.authorize -> rail.settle -> origin.fetch(...)
 *
 * The rail's `settle` step is the payment commit. Previously `SelfHosted402Rail`
 * only extended the in-memory stub, so a "self 402" never actually minted a
 * proof, rejected a reused proof, or recorded a final receipt. This module
 * makes it real:
 *
 *   1. The broker signs an Ed25519 **payment mandate** (a spend authorization)
 *      over an opaque manifest, carrying a per-request nonce.
 *   2. The rail POSTs that signed mandate to a settlement backend. The backend
 *      verifies the signature, rejects a **replayed** nonce, signs a chained
 *      settlement **receipt**, and returns it. A replayed proof throws
 *      `RAIL_REPLAY` (non-retryable) — the broker maps a settle fault to
 *      `payment-required`, exactly as an origin that still demanded payment.
 *   3. The receipt lands in a small, Ed25519-**chained, tamper-evident ledger**
 *      that the audit/`reconcile` surface can read.
 *
 * The wire form is intentionally minimal (draft-caveat: build against the
 * *pattern* of x402's `PAYMENT-SIGNATURE`/`X-PAYMENT`, not its field names).
 * The same backend runs in-process (tests, dev) or behind a thin HTTP service
 * (`SettlementHttpServer`) on a separate host (`HttpSettlementClient`), so the
 * rail needs no compile-time knowledge of where the backend lives.
 *
 * Crypto mirrors `packages/identity/src/ring.ts`: Ed25519 over a JWK, and the
 * broker's own `b64url`/`fromB64url` from `@mwb/core`. No new dependency.
 */

import {
  generateKeyPairSync,
  sign,
  verify,
  createPrivateKey,
  createPublicKey,
  randomBytes,
} from 'node:crypto';
import {
  RailError,
  systemClock,
  b64url,
  fromB64url,
  type Clock,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type Micros,
} from '@mwb/core';

/** The opaque mandate type the broker mints. Not a draft's field set. */
const PAYMENT_MANDATE_TYPE = 'urn:mwb:self402:payment-mandate:v1';

/** Fixed key order so the manifest bytes are byte-identical at sign and verify. */
const MANDATE_FIELDS = [
  'origin',
  'url',
  'amountMicros',
  'currency',
  'nonce',
  'issuedAt',
  'recipient',
] as const;

/** Accept a mandate whose `issuedAt` is within this window of the clock. */
const ACCEPTANCE_WINDOW_MS = 5 * 60 * 1000;

/** The header the rail injects on the settled origin request (holds the proof). */
export const PAYMENT_HEADER = 'x-payment';

/** An Ed25519 spend-authorizer. `privateKey` never leaves the signing side. */
export interface SettlementKey {
  keyId: string;
  algorithm: 'ed25519';
  /** 32-byte public key, JWK `x`, base64url. Shares the verifier. */
  publicKey: string;
  /** 32-byte seed, JWK `d`, base64url. Never leaves the broker. */
  privateKey: string;
  createdAt: string;
}

/** Mint a settlement key (broker's spend authorizer). */
export function makeSettlementKey(
  clock: Clock = systemClock,
  keyId = `settle_${clock.now().replace(/[^A-Za-z0-9]/g, '')}`,
): SettlementKey {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
  const pub = publicKey.export({ format: 'jwk' }) as { x?: string };
  const priv = privateKey.export({ format: 'jwk' }) as { d?: string };
  if (!pub.x || !priv.d) {
    throw new RailError('failed to export Ed25519 JWK', 'SETTLEMENT_KEY');
  }
  return {
    keyId,
    algorithm: 'ed25519',
    publicKey: b64url(fromB64url(pub.x)),
    privateKey: b64url(fromB64url(priv.d)),
    createdAt: clock.now(),
  };
}

function privateKeyObject(k: SettlementKey): ReturnType<typeof createPrivateKey> {
  return createPrivateKey({
    format: 'jwk',
    key: { kty: 'OKP', crv: 'Ed25519', d: k.privateKey, x: k.publicKey },
  });
}

function publicKeyObject(k: SettlementKey): ReturnType<typeof createPublicKey> {
  return createPublicKey({
    format: 'jwk',
    key: { kty: 'OKP', crv: 'Ed25519', x: k.publicKey },
  });
}

function signBytes(k: SettlementKey, buf: Buffer): string {
  return b64url(new Uint8Array(sign(null, buf, privateKeyObject(k))));
}

function verifyBytes(k: SettlementKey, buf: Buffer, sigB64: string): boolean {
  try {
    return verify(null, buf, publicKeyObject(k), Buffer.from(fromB64url(sigB64)));
  } catch {
    return false;
  }
}

/** The signed spend authorization the broker mints and the rail commits. */
export interface PaymentMandateManifest {
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  nonce: string;
  issuedAt: string;
  recipient: string;
}

export interface PaymentMandate extends PaymentMandateManifest {
  /**
   * 64-byte Ed25519 signature, base64url-encoded (86 chars, no padding). The
   * wire form always sets it, but a hand-edited/tampered mandate may omit it.
   */
  signature?: string;
}

function manifestBytes(m: PaymentMandateManifest): Buffer {
  const obj: Record<string, number | string> = {};
  for (const f of MANDATE_FIELDS) obj[f] = m[f];
  return Buffer.from(JSON.stringify(obj), 'utf8');
}

/** Build (sign) a payment mandate. */
export function buildMandate(o: {
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  recipient: string;
  clock: Clock;
  key: SettlementKey;
  nonce?: string;
  issuedAt?: string;
}): PaymentMandate {
  const nonce = o.nonce ?? randomBytes(32).toString('base64url');
  const issuedAt = o.issuedAt ?? o.clock.now();
  const manifest: PaymentMandateManifest = {
    origin: o.origin,
    url: o.url,
    amountMicros: o.amountMicros,
    currency: o.currency,
    nonce,
    issuedAt,
    recipient: o.recipient,
  };
  return { ...manifest, signature: signBytes(o.key, manifestBytes(manifest)) };
}

export interface VerifyResult {
  valid: boolean;
  reason?: string;
}

/**
 * Verify a mandate's signature, manifest, and acceptance window. Does not
 * consume the nonce — the origin can call this to gate content release.
 */
export function verifyMandate(
  m: PaymentMandate,
  key: SettlementKey,
  opts?: { nowMs?: number },
): VerifyResult {
  if (typeof m.signature !== 'string' || m.signature.length === 0) {
    return { valid: false, reason: 'missing-signature' };
  }
  if (!verifyBytes(key, manifestBytes(m), m.signature)) {
    return { valid: false, reason: 'signature-mismatch' };
  }
  const iat = Date.parse(m.issuedAt);
  if (Number.isNaN(iat)) return { valid: false, reason: 'bad-issuedAt' };
  const nowMs = opts?.nowMs ?? Date.now();
  if (Math.abs(nowMs - iat) > ACCEPTANCE_WINDOW_MS) {
    return { valid: false, reason: 'issued-out-of-window' };
  }
  if (!(m.amountMicros > 0)) return { valid: false, reason: 'non-positive-amount' };
  return { valid: true };
}

/** A receipt minted by the backend, signed by its key. */
export interface SettlementReceipt {
  settlementRef: string;
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  nonce: string;
  issuedAt: string;
  settledAt: string;
}

/** One entry in the chained, tamper-evident settlement ledger. */
export interface LedgerRecord {
  seq: number;
  receipt: SettlementReceipt;
  signedAt: string;
  /** Signature over `${seq}\0${ref}\0${previousSignature}`. */
  signature: string;
}

/**
 * The settlement backend: verifies signed mandates, enforces replay
 * protection (a nonce is consumed exactly once), and records a final,
 * cryptographically-chained receipt ledger. Runs in-process.
 */
export class SettlementServer {
  readonly key: SettlementKey;
  readonly clock: Clock;
  private readonly consumed = new Set<string>();
  private readonly ledgerRows: LedgerRecord[] = [];

  constructor(options: { key: SettlementKey; clock?: Clock }) {
    this.key = options.key;
    this.clock = options.clock ?? systemClock;
  }

  /** Pure: is this mandate's signature valid and in-window? (No state change.) */
  isValidMandate(m: PaymentMandate): boolean {
    return verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) }).valid;
  }

  /** Verify and, on first use, consume the nonce, then mint a receipt. */
  verify(m: PaymentMandate): VerifyResult {
    const v = verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) });
    if (!v.valid) return v;
    if (this.consumed.has(m.nonce)) {
      return { valid: false, reason: 'replayed-proof' };
    }
    return { valid: true };
  }

  /**
   * The payment commit. Verifies, rejects a replayed nonce (throwing
   * `RAIL_REPLAY`, non-retryable), records a chained receipt, and returns the
   * `RailSettlement` the broker surfaces on a fulfilled outcome.
   */
  settle(m: PaymentMandate): RailSettlement {
    const v = this.verify(m);
    if (!v.valid) {
      throw new RailError(
        `settlement rejected: ${v.reason ?? 'unknown'}`,
        'RAIL_SETTLE',
        undefined,
        false,
      );
    }
    const settledAt = this.clock.now();
    const settlementRef = `settle_self402_${randomBytes(9).toString('hex')}`;
    const receipt: SettlementReceipt = {
      settlementRef,
      origin: m.origin,
      url: m.url,
      amountMicros: m.amountMicros,
      currency: m.currency,
      nonce: m.nonce,
      issuedAt: m.issuedAt,
      settledAt,
    };
    const prevSig = this.ledgerRows.length > 0 ? this.ledgerRows[this.ledgerRows.length - 1]!.signature : 'genesis';
    const seq = this.ledgerRows.length + 1;
    const chain = Buffer.from(`${seq}\u0000${receipt.settlementRef}\u0000${prevSig}`, 'utf8');
    const signature = signBytes(this.key, chain);
    this.ledgerRows.push({ seq, receipt, signedAt: settledAt, signature });
    this.consumed.add(m.nonce);
    return {
      rail: 'self402',
      settlementRef,
      amountMicros: m.amountMicros,
      currency: m.currency,
      settledAt,
    };
  }

  /** The current settlement ledger (a copy) — surfaced on the audit view. */
  ledger(): LedgerRecord[] {
    return this.ledgerRows.map((r) => ({ ...r, receipt: { ...r.receipt } }));
  }

  /** How many distinct nonces have been settled (== ledger length). */
  settledCount(): number {
    return this.ledgerRows.length;
  }
}

/**
 * A `PaymentRail` backed by a settlement backend (in-process
 * `SettlementServer`, or a remote `HttpSettlementClient`). The rail signs the
 * mandate (with the broker's key) and commits it via the backend. Spec-agnostic
 * — the broker only sees `quote/authorize/settle`.
 */
export class SelfHosted402Rail implements PaymentRail {
  readonly id = 'self402';

  constructor(
    private readonly backend: SettlementBackend,
    private readonly key: SettlementKey,
    private readonly opts: {
      priceMicros: Micros;
      currency?: string;
      clock?: Clock;
      origin?: string;
    },
  ) {}

  async quote(_req: PaymentRequest): Promise<Quote> {
    const nowMs = Date.parse(this.opts.clock?.now() ?? systemClock.now());
    return {
      unitsMicros: this.opts.priceMicros,
      currency: this.opts.currency ?? 'USD',
      rail: this.id,
      settlement: 'immediate',
      expiresAt: new Date(nowMs + 60_000).toISOString(),
    };
  }

  async authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    const origin = this.opts.origin ?? new URL(String(req.url)).origin;
    const mandate = buildMandate({
      origin,
      url: String(req.url),
      amountMicros: quote.unitsMicros,
      currency: this.opts.currency ?? 'USD',
      recipient: this.key.keyId,
      clock: this.opts.clock ?? systemClock,
      key: this.key,
    });
    const xPayment = encodeXPayment(mandate);
    return {
      scheme: this.id,
      payload: JSON.stringify(mandate),
      settlementHeaders: { [PAYMENT_HEADER]: xPayment },
    };
  }

  async settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    const mandate = JSON.parse(authorization.payload) as PaymentMandate;
    if (mandate.url !== String(req.url)) {
      throw new RailError('settlement mandate does not match the request', 'RAIL_SETTLE');
    }
    return this.backend.settle(mandate);
  }
}

/**
 * The backend contract the rail commits through: the settle commit, a pure
 * `isValidMandate` cross-check (an origin can use it), and the key id the
 * receipt references.
 */
export interface SettlementBackend {
  settle(mandate: PaymentMandate): Promise<RailSettlement>;
  isValidMandate(mandate: PaymentMandate): boolean;
  readonly keyId: string;
}

// `SettlementServer` is synchronous at its crypto core, but the rail is async,
// so wrap the commit in a resolved promise to keep one uniform shape.
function ok(s: RailSettlement): Promise<RailSettlement> {
  return Promise.resolve(s);
}

export class InProcessSettlementBackend implements SettlementBackend {
  readonly keyId: string;

  constructor(private readonly server: SettlementServer) {
    // `keyId` reads the parameter property, so it must be initialized inside
    // the constructor body — a field initializer runs *before* parameter
    // properties are assigned (TS2729: used before initialization).
    this.keyId = this.server.key.keyId;
  }

  settle(mandate: PaymentMandate): Promise<RailSettlement> {
    return ok(this.server.settle(mandate));
  }
  isValidMandate(mandate: PaymentMandate): boolean {
    return this.server.isValidMandate(mandate);
  }
}

/**
 * Convenience: a `SelfHosted402Rail` over an in-process `SettlementServer`,
 * sharing its key. This is the default wiring in `packages/gateway/src/server.ts`.
 */
export function makeSelf402Rail(
  server: SettlementServer,
  options: { priceMicros: Micros; currency?: string; clock?: Clock; origin?: string } = {
    priceMicros: 5000,
  },
): SelfHosted402Rail {
  return new SelfHosted402Rail(
    new InProcessSettlementBackend(server),
    server.key,
    options,
  );
}

/** The decoded wire payload carried in the `x-payment` header. */
export interface XPayment {
  type: string;
  mandate: PaymentMandate;
}

/** Encode the proof header value (`x-payment`). */
export function encodeXPayment(mandate: PaymentMandate): string {
  return b64url(
    Buffer.from(
      JSON.stringify({ type: PAYMENT_MANDATE_TYPE, mandate } satisfies XPayment),
      'utf8',
    ),
  );
}

/** Decode the proof header value; throws on malformed input. */
export function decodeXPayment(value: string): PaymentMandate {
  let raw: string;
  try {
    // Base64url must round-trip exactly; if it does not, the header is
    // malformed (not merely un-JSON). Reject it as such.
    const bytes = fromB64url(value);
    if (b64url(bytes) !== value) {
      throw new Error('not valid base64url');
    }
    raw = Buffer.from(bytes).toString('utf8');
  } catch (cause) {
    throw new RailError('malformed x-payment header', 'SETTLEMENT_DECODE', cause);
  }
  let parsed: XPayment;
  try {
    parsed = JSON.parse(raw) as XPayment;
  } catch (cause) {
    throw new RailError('x-payment is not JSON', 'SETTLEMENT_DECODE', cause);
  }
  if (!parsed || parsed.type !== PAYMENT_MANDATE_TYPE || !parsed.mandate) {
    throw new RailError('unknown x-payment shape', 'SETTLEMENT_DECODE');
  }
  return parsed.mandate;
}

/**
 * A `SettlementBackend` that commits against a *remote* settlement service over
 * HTTP (standalone `SettlementHttpServer`). Lets the backend run on its own
 * host while the rail stays identical. `isValidMandate` is a local signature
 * check (the remote cannot see the broker's key) plus a freshness read.
 */
export class HttpSettlementClient implements SettlementBackend {
  constructor(
    private readonly url: string,
    private readonly key: SettlementKey,
  ) {}

  get keyId(): string {
    return this.key.keyId;
  }

  isValidMandate(m: PaymentMandate): boolean {
    return verifyMandate(m, this.key, { nowMs: Date.now() }).valid;
  }

  async settle(m: PaymentMandate): Promise<RailSettlement> {
    const res = await fetch(`${this.url.replace(/\/$/, '')}/settle`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(m),
    });
    if (!res.ok) {
      // A settlement rejection (e.g. replayed nonce) is the payment rail
      // "still demanding payment" — surface it as a non-retryable settle fault.
      let reason: string | undefined;
      try {
        const json = (await res.json()) as { reason?: string };
        reason = json.reason;
      } catch {
        /* ignore */
      }
      throw new RailError(
        `settlement service returned ${res.status}${reason ? `: ${reason}` : ''}`,
        'RAIL_SETTLE',
        undefined,
        reason === 'replayed-proof',
      );
    }
    const body = (await res.json()) as RailSettlement & { receipt: SettlementReceipt };
    if (!body.settlementRef) {
      throw new RailError('settlement service returned no ref', 'RAIL_SETTLE');
    }
    return body;
  }
}

// --- Standalone settlement HTTP service -----------------------------------

/**
 * A tiny, dependency-free HTTP surface over a `SettlementServer`. The
 * settlement service is its own process on the backend host; this exposes just
 * what a `HttpSettlementClient` (and any independent auditor) needs:
 *
 *   GET  /health        -> liveness, with backend keyId and ledger depth
 *   POST /accept         -> verify a mandate's signature (non-consuming)
 *   POST /settle         -> the payment commit (consumes the nonce)
 *   GET  /ledger         -> the chained, tamper-evident receipt ledger
 *
 * The router (a `RouteTable`) is pure so it can be unit-tested by dispatching
 * decoded requests; the server just funnels a raw request through it. Tests bind
 * this to a `listen(0)` socket (no fixed port), so the routing is covered
 * without opening any socket.
 */
interface Decoded {
  pathname: string;
  body?: unknown;
}

type Result = { status: number; body: unknown };

type Handle = (req: Decoded) => Promise<Result> | Result;

class RouteTable {
  private readonly routes: { method: 'GET' | 'POST'; pattern: RegExp; handle: Handle }[] = [];

  add(method: 'GET' | 'POST', pattern: RegExp, handle: Handle): void {
    this.routes.push({ method, pattern, handle });
  }

  async dispatch(
    method: 'GET' | 'POST',
    pathname: string,
    raw: string,
  ): Promise<Result> {
    const decoded: Decoded = {
      pathname,
      body: method === 'POST' ? decodeBody(raw) : undefined,
    };
    for (const r of this.routes) {
      if (r.method !== method || !r.pattern.test(pathname)) continue;
      return r.handle(decoded);
    }
    return {
      status: 404,
      body: { error: 'not-found', detail: `${method} ${pathname} matches no route` },
    };
  }
}

function decodeBody(raw: string): unknown {
  if (!raw || raw.trim().length === 0) return {};
  return JSON.parse(raw) as unknown;
}

export class SettlementHttpServer {
  readonly table = new RouteTable();

  constructor(private readonly server: SettlementServer) {
    // Liveness: is the backend up, and what is its depth of settlements?
    this.table.add('GET', /^\/health$/, () => ({
      status: 200,
      body: {
        status: 'ok',
        keyId: this.server.key.keyId,
        settled: this.server.settledCount(),
        ledgerDepth: this.server.ledger().length,
      },
    }));

    // Accept: verify a mandate's signature without consuming its nonce.
    // This is what an origin would call before releasing content.
    this.table.add('POST', /^\/accept$/, (req) => {
      let m: PaymentMandate;
      try {
        m = req.body as PaymentMandate;
      } catch {
        return { status: 400, body: { error: 'bad-request', detail: 'missing mandate' } };
      }
      const valid = this.server.isValidMandate(m);
      return {
        status: valid ? 200 : 402,
        body: {
          valid,
          keyId: this.server.key.keyId,
        },
      };
    });

    // Settle: the payment commit. Verifies, enforces replay protection,
    // records a chained receipt, and returns it.
    this.table.add('POST', /^\/settle$/, (req) => {
      let m: PaymentMandate;
      try {
        m = req.body as PaymentMandate;
      } catch {
        return { status: 400, body: { error: 'bad-request', detail: 'missing mandate' } };
      }
      try {
        const settlement = this.server.settle(m);
        return {
          status: 200,
          body: {
            rail: settlement.rail,
            settlementRef: settlement.settlementRef,
            amountMicros: settlement.amountMicros,
            currency: settlement.currency,
            settledAt: settlement.settledAt,
          },
        };
      } catch (cause) {
        // A non-retryable reject (e.g. replayed nonce) is the backend "still
        // demanding payment" — return 402 so the client maps it to a
        // payment-required outcome.
        if (isRailError(cause) && cause.retryable === false) {
          return {
            status: 402,
            body: { error: 'settlement-rejected', reason: reasonOf(cause) },
          };
        }
        return { status: 500, body: { error: 'internal', detail: 'settlement error' } };
      }
    });

    // Ledger: the full, chained, tamper-evident receipt ledger.
    this.table.add('GET', /^\/ledger$/, () => ({
      status: 200,
      body: {
        keyId: this.server.key.keyId,
        count: this.server.ledger().length,
        records: this.server.ledger(),
      },
    }));
  }

  /** The backend's key id (for the standalone health endpoint / wiring). */
  get keyId(): string {
    return this.server.key.keyId;
  }

  /**
   * Dispatch a raw request through the router. `pathname` should be path only
   * (no query string). This is the seam tested by the HTTP integration test.
   */
  async dispatch(
    method: 'GET' | 'POST',
    pathname: string,
    raw = '',
  ): Promise<Result> {
    return this.table.dispatch(method, pathname, raw);
  }
}

function isRailError(e: unknown): e is RailError {
  return e instanceof RailError;
}

function reasonOf(e: RailError): string {
  // The settle fault carries the backend's rejection reason in its message.
  const m = /\s*:\s*([a-z-]+)$/.exec(e.message);
  return m ? m[1] ?? 'settlement-rejected' : 'settlement-rejected';
}

/**
 * A thin HTTP entrypoint for the Metered Web Broker — one endpoint, one contract.
 *
 * The `Broker` is a library (see `packages/gateway/src/broker.ts`); nothing in
 * the repo previously bound a socket. This file is the only "web" layer: it
 * wires a `Broker` from environment config, serves `GET /health` and `GET /`,
 * mounts the metered `POST /fetch`, and exposes the audit ledger at `GET /audit`.
 *
 * It uses Node's built-in `http` module (no Express) so the production image is
 * small and cold-start cheap — one Node process, no PaaS, exactly what the VPS
 * deploy targets. The broker's orchestration is reused untouched.
 *
 *   # run it (TS directly)
 *   npx tsx packages/gateway/src/server.ts
 *   # or, in the image
 *   npm start
 *
 *   curl -s localhost:8787/health
 *   curl -s localhost:8787/fetch -XPOST -H'content-type: application/json' \
 *       -d '{"url":"https://api.example.com/wire/42"}'
 *   curl -s localhost:8787/audit
 */

import {
  createServer,
  type IncomingMessage,
  type Server,
  type ServerResponse,
} from 'node:http';
import { Broker } from './broker.js';
import { BudgetEngine, defaultPolicy, type BudgetPolicy } from '@mwb/budget';
import { AuditLedger, reconcile, renderDashboard, summarize } from '@mwb/audit';
import { KeyRing } from '@mwb/identity';
import { makeSettlementKey, makeSelf402Rail, SettlementServer } from '@mwb/rails';
import {
  systemClock,
  url as brandUrl,
  type Clock,
  type HeaderRecord,
  type PaymentRail,
  type PaymentRequest,
  type UrlString,
} from '@mwb/core';
import type { OriginClient, OriginResponse } from './broker.js';

/** The port the HTTP server binds. Defaults to 8787 for a small VPS. */
export const PORT = Number(process.env.PORT ?? 8787);

/** Host/interface to bind. Default: all interfaces (Caddy fronts it in prod). */
export const HOST = process.env.HOST ?? '0.0.0.0';

/**
 * A metered origin client. Two modes:
 *
 *  - `ORIGIN_URL` unset (default): a self-fulfilling origin. Every settled
 *    request returns HTTP 200 with synthetic body + no license. This lets the
 *    broker run `fulfilled` end-to-end with no real origin behind it — the
 *    whole metered path (quote → authorize → settle → record) executes.
 *  - `ORIGIN_URL` set: the settled request is proxied to that URL over HTTP.
 *    This is the path to a real metered origin (self 402, x402, Cloudflare PPC).
 */
export class MeteredOrigin implements OriginClient {
  private readonly target?: UrlString;

  constructor(target?: UrlString) {
    this.target = target;
  }

  async fetch(req: PaymentRequest): Promise<OriginResponse> {
    if (this.target) {
      const res = await fetch(this.target, {
        method: req.method,
        headers: req.headers,
      });
      return {
        httpStatus: res.status,
        headers: headerRecord(res),
        body: await res.text(),
      };
    }
    // Self origin: nothing behind the broker, so report satisfied.
    return {
      httpStatus: 200,
      headers: { 'content-type': 'text/plain; charset=utf-8' },
      body: 'metered content from a self-hosted origin (ORIGIN_URL unset)',
    };
  }
}

/**
 * Build the Rail from env. The default (and only, today) is the self-402
 * facilitator: a `SelfHosted402Rail` that signs a spend mandate with a
 * broker-held Ed25519 key and commits it to an in-process `SettlementServer`
 * (replay-protected, chained, tamper-evident). There is no external service —
 * the rail is its own backend. The broker only ever sees the opaque
 * `quote → authorize → settle` interface.
 *
 * Env knobs:
 *   - `RAIL_PRICE_MICROS`     micro-unit price, per fetch (default 5000);
 *                             kept ≤ 10_000 so a fetch reaches `fulfilled`.
 *   - `SETTLEMENT_KEY_ID`     key id stamped on the signed mandate.
 */
export function buildRail(clock: Clock): PaymentRail {
  const priceMicros = Number(process.env.RAIL_PRICE_MICROS ?? 5000);
  const key = makeSettlementKey(clock, process.env.SETTLEMENT_KEY_ID);
  const server = new SettlementServer({ key, clock });
  return makeSelf402Rail(server, {
    priceMicros,
    currency: defaultPolicy.currency,
    clock,
  });
}

/** Parse budget policy from env, overriding just the per-call ceiling. */
function buildPolicy(): BudgetPolicy {
  const policy: BudgetPolicy = { ...defaultPolicy };
  const ceiling = process.env.PER_CALL_CEILING_MICROS;
  if (ceiling && Number.isFinite(Number(ceiling))) {
    policy.perCallCeilingMicros = Number(ceiling);
  }
  return policy;
}

/**
 * Build the full broker from env. Every collaborator is injected exactly as the
 * broker unit tests do, so the wiring here is the same one the test proves.
 *
 * Returns the broker alongside the small bits of state the HTTP layer needs to
 * shape responses (the audit ledger, the origin mode, whether identity is on)
 * so `createApp` never reaches into broker internals.
 */
export function buildBroker(): {
  broker: Broker;
  ledger: AuditLedger;
  origin: MeteredOrigin;
  originTarget?: UrlString;
  identityOn: boolean;
} {
  const clock: Clock = systemClock;
  const ledger = new AuditLedger({ clock });
  const origin = new MeteredOrigin(process.env.ORIGIN_URL ? brandUrl(process.env.ORIGIN_URL) : undefined);
  const ring = process.env.IDENTITY_KEY_ID ? new KeyRing(clock) : undefined;
  const identityOn = ring !== undefined;
  const broker = new Broker({
    rail: buildRail(clock),
    budget: new BudgetEngine({ clock, policy: buildPolicy() }),
    ledger,
    ring,
    origin,
    clock,
    identity: identityOn
      ? { subject: process.env.IDENTITY_SUBJECT }
      : undefined,
  });
  return {
    broker,
    ledger,
    origin,
    originTarget: process.env.ORIGIN_URL ? brandUrl(process.env.ORIGIN_URL) : undefined,
    identityOn,
  };
}

/** Read the whole request body as text. */
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString('utf-8');
}

/** A plain object from an HTTP response's headers (Node Headers → record). */
function headerRecord(res: Response): HeaderRecord {
  const out: HeaderRecord = {};
  res.headers.forEach((v, k) => {
    out[k] = v;
  });
  return out;
}

/** Send a JSON response with status and Content-Type. */
function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const raw = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(raw);
}

/** One metered request, decoded from the request body. */
export interface FetchRequest {
  /** The absolute URL of the metered content to fetch. */
  url: UrlString;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /**
   * Optional `fetchId`. Absent ⇒ the broker derives one. Present ⇒ idempotent
   * (a repeat id returns the cached outcome without re-charging the meter).
   */
  fetchId?: string;
  /** Optional headers to present to the origin on the settled request. */
  headers?: HeaderRecord;
}

/**
 * Handle `POST /fetch`. Decodes the request, runs `Broker.fetch`, and maps the
 * broker's terminal outcome to a JSON response. Every broker terminal class is
 * one of {fulfilled, blocked, payment-required, token-rejected}; there is no
 * generic `error` status.
 */
export async function handleFetch(
  broker: Broker,
  raw: string,
): Promise<{ status: number; body: unknown }> {
  let req: FetchRequest;
  try {
    req = JSON.parse(raw) as FetchRequest;
  } catch {
    return { status: 400, body: { error: 'invalid JSON body' } };
  }
  if (!req || typeof req.url !== 'string') {
    return { status: 400, body: { error: "missing required string field 'url'" } };
  }

  const outcome = await broker.fetch({
    url: req.url,
    fetchId: req.fetchId,
    tenantId: req.tenantId,
    headers: req.headers as HeaderRecord | undefined,
  });

  // A fulfilled metered fetch succeeds (200). Otherwise map the terminal class
  // to an HTTP status agents can branch on: payment-required (402) for any
  // metered-charge gate, and 403 for the rest (blocked, token-rejected, error).
  const status =
    outcome.status === 'fulfilled'
      ? 200
      : outcome.failureClass === 'payment-required'
        ? 402
        : 403;
  return { status, body: outcome };
}

/** Handle `GET /health` — liveness, no dependencies. */
export function handleHealth(): { status: number; body: unknown } {
  return { status: 200, body: { status: 'ok', clock: systemClock.now() } };
}

/** Handle `GET /audit` — JSON: the latest ledger rows. */
export function handleAudit(ledger: AuditLedger): { status: number; body: unknown } {
  const rows = ledger.toRows();
  return { status: 200, body: { rows, summary: summarize(rows) } };
}

/** Handle `GET /audit/dashboard` — the reconciliation dashboard as text. */
export function handleAuditDashboard(ledger: AuditLedger): {
  status: number;
  body: unknown;
} {
  const rows = ledger.toRows();
  const dashboard = renderDashboard(rows, 'Metered Web Broker');
  const recon = reconcile(rows);
  return {
    status: 200,
    body: { dashboard, reconciliation: recon, count: rows.length },
  };
}

/** Handle `GET /` — a small JSON index of the endpoints. */
export function handleIndex(): { status: number; body: unknown } {
  return {
    status: 200,
    body: {
      service: 'metered-web-broker',
      endpoints: {
        'GET /': 'this index',
        'GET /health': 'liveness',
        'POST /fetch': '{"url", fetchId?, tenantId?}',
        'GET /audit': 'latest ledger rows + summary',
        'GET /audit/dashboard': 'reconciliation dashboard',
      },
    },
  };
}

/**
 * Create (but do not start) the HTTP server. Exposed so the test can bind an
 * ephemeral port without opening a real socket in the module.
 */
export interface ServerConfig {
  broker: Broker;
  ledger: AuditLedger;
  origin: MeteredOrigin;
  /** The proxied-origin URL, if ORIGIN_URL was set; else undefined (self origin). */
  originTarget?: UrlString;
}

/**
 * Create (but do not start) the HTTP server. Exposed so the test can bind an
 * ephemeral port without opening a real socket in the module.
 */
export function createApp(cfg: ServerConfig): Server {
  const { ledger, origin, originTarget, broker } = cfg;

  const server = createServer((req, res) => {
    const url = req.url ?? '/';
    const method = req.method ?? 'GET';

    if (method === 'GET' && url === '/health') {
      const { status, body } = handleHealth();
      return void sendJson(res, status, body);
    }
    if (method === 'GET' && url === '/') {
      const { status, body } = handleIndex();
      return void sendJson(res, status, body);
    }
    if (method === 'GET' && url === '/audit/dashboard') {
      const { status, body } = handleAuditDashboard(ledger);
      return void sendJson(res, status, body);
    }
    if (method === 'GET' && url === '/audit') {
      const { status, body } = handleAudit(ledger);
      return void sendJson(res, status, body);
    }
    if (method === 'POST' && url === '/fetch') {
      void (async () => {
        try {
          const raw = await readBody(req);
          const { status, body } = await handleFetch(broker, raw);
          return void sendJson(res, status, body);
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          // A failure *inside* the server (not the metered path) is a 500; the
          // metered path never produces a generic error status.
          return void sendJson(res, 500, { error: 'server error', message });
        }
      })();
      return;
    }

    // Unknown route.
    const { status, body } = {
      status: 404,
      body: {
        error: 'not found',
        path: url,
        endpoints: ['/', '/health', '/fetch', '/audit', '/audit/dashboard'],
      },
    };
    return void sendJson(res, status, body);
  });

  // Log the effective origin mode (self-origin or proxied) at boot.
  server.on('listening', () => {
    // eslint-disable-next-line no-console
    console.log(
      `metered-web-broker listening on http://${HOST}:${PORT}` +
        (originTarget ? `  (origin → ${originTarget})` : '  (self origin)'),
    );
  });

  return server;
}

/** Start the HTTP server from env and listen. */
export function start(): Server {
  const cfg = buildBroker();
  const server = createApp(cfg);
  server.listen(PORT, HOST);
  return server;
}

// Only start when run directly (not when imported by the test).
const isMain =
  process.argv[1] &&
  process.argv[1].endsWith('server.ts') &&
  (process.argv[1].endsWith('src/server.ts') || process.argv[1].endsWith('server.js'));

if (isMain) {
  start();
}

