export {
  AuditLedger,
  reconcile,
  summarize,
} from './ledger.js';
export type { LedgerSummary, ReconciliationReport, ReconciliationReport as ReconReport } from './ledger.js';
export { renderDashboard } from './dashboard.js';

import type {
  Clock,
  FetchOutcome,
  FailureClass,
  LedgerEntry,
} from '@mwb/core';

/**
 * The ledger is the broker's source of truth: every fetch the broker
 * attempted — fulfilled, denied, failed — appears exactly once.
 *
 * `seq` is monotonically increasing and gap-free; that invariant is what the
 * reconciliation step verifies. If the broker crashes or an origin
 * settlement is missing, reconciliation surfaces it instead of hiding it.
 */
export class AuditLedger {
  readonly entries: LedgerEntry[] = [];
  private seq = 0;
  private readonly clock: Clock;

  constructor(options?: { clock?: Clock }) {
    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
  }

  /** Append one row for one fetch attempt. Idempotent per fetchId. */
  record(outcome: FetchOutcome, options?: { tenantId?: string }): LedgerEntry {
    const existing = this.entries.find((e) => e.fetchId === outcome.fetchId);
    if (existing) return existing;

    this.seq += 1;
    const now = this.clock.now();
    const row: LedgerEntry = {
      seq: this.seq,
      fetchId: outcome.fetchId,
      tenantId: options?.tenantId ?? outcome.tenantId ?? 'default',
      url: outcome.origin?.url ?? 'unknown',
      status: outcome.status === 'fulfilled' ? 'fulfilled' : 'denied',
      failureClass: outcome.failureClass,
      httpStatus: outcome.origin?.httpStatus,
      priceMicros: outcome.price?.unitsMicros,
      currency: outcome.price?.currency,
      rail: outcome.rail,
      licenseId: outcome.license?.id,
      keyId: outcome.identity?.keyId,
      settlementRef: outcome.settlementRef,
      startedAt: outcome.timestamps.startedAt,
      completedAt: outcome.timestamps.completedAt,
      recordedAt: now,
    };
    this.entries.push(row);
    return row;
  }

  /** Gap-free, monotonically increasing seq. */
  lastSeq(): number {
    return this.seq;
  }

  byTenant(tenantId: string): LedgerEntry[] {
    return this.entries.filter((e) => e.tenantId === tenantId);
  }

  byUrl(url: string): LedgerEntry[] {
    return this.entries.filter((e) => e.url === url);
  }

  toRows(): LedgerEntry[] {
    return this.entries.map((e) => structuredClone(e));
  }
}

export interface LedgerSummary {
  total: number;
  fulfilled: number;
  denied: number;
  byFailureClass: Record<string, number>;
  spendMicros: number;
  byRail: Record<string, number>;
  byLicense: Record<string, number>;
}

export function summarize(rows: LedgerEntry[]): LedgerSummary {
  const s: LedgerSummary = {
    total: rows.length,
    fulfilled: 0,
    denied: 0,
    byFailureClass: {},
    spendMicros: 0,
    byRail: {},
    byLicense: {},
  };
  for (const r of rows) {
    if (r.status === 'fulfilled') s.fulfilled += 1;
    else s.denied += 1;
    if (r.failureClass) s.byFailureClass[r.failureClass] = (s.byFailureClass[r.failureClass] ?? 0) + 1;
    if (r.status === 'fulfilled' && r.priceMicros != null) s.spendMicros += r.priceMicros;
    if (r.rail) s.byRail[r.rail] = (s.byRail[r.rail] ?? 0) + 1;
    if (r.licenseId) s.byLicense[r.licenseId] = (s.byLicense[r.licenseId] ?? 0) + 1;
  }
  return s;
}

export interface ReconciliationReport {
  ok: boolean;
  problems: string[];
  checks: {
    seqGapFree: boolean;
    deniedHasFailureClass: boolean;
    fulfilledHasSettlement: boolean;
    fulfilledHasPrice: boolean;
  };
}

/**
 * Reconcile the ledger against invariants:
 *  - seq is gap-free starting at 1
 *  - every denied row has a failureClass (the three-classes invariant)
 *  - every fulfilled row has a settlementRef (we paid, we can prove it)
 *  - every fulfilled row has a price (we can bill what we paid)
 */
export function reconcile(rows: LedgerEntry[]): ReconciliationReport {
  const problems: string[] = [];

  const seqGapFree =
    rows.length === 0 ||
    rows.every((r, i) => r.seq === i + 1);

  const deniedHaveFC = rows
    .filter((r) => r.status !== 'fulfilled')
    .every((r) => r.failureClass !== undefined);

  const fulfilledHasSett = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => (r.settlementRef ?? '').length > 0);

  const fulfilledHasPrice = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => r.priceMicros != null && r.priceMicros > 0);

  if (!seqGapFree) problems.push('seq is not gap-free starting at 1');
  if (!deniedHaveFC) problems.push('a denied row lacks a failureClass');
  if (!fulfilledHasSett)
    problems.push('a fulfilled row lacks a settlementRef (settlement not proven)');
  if (!fulfilledHasPrice) problems.push('a fulfilled row lacks a positive price');

  return {
    ok:
      seqGapFree && deniedHaveFC && fulfilledHasSett && fulfilledHasPrice,
    problems,
    checks: { seqGapFree, deniedHasFailureClass: deniedHaveFC, fulfilledHasSettlement: fulfilledHasSett, fulfilledHasPrice },
  };
}

export type { FailureClass };

import type { Price, Quote } from './amounts.js';

/** A string constrained to a valid absolute URL at construction. */
export type UrlString = string & { readonly __brand: 'UrlString' };

export function url(value: string): UrlString {
  try {
    return new URL(value) as unknown as UrlString;
  } catch (cause) {
    throw new TypeError(`url(): invalid absolute URL: ${value}`, { cause });
  }
}

export type HeaderRecord = Record<string, string>;

/**
 * The three distinct failure classes. Today's agents collapse all of these
 * into a generic fetch failure; the broker reports each separately so the
 * cost decision is visible.
 */
export type FailureClass = 'blocked' | 'payment-required' | 'token-rejected';

export type FetchStatus = 'fulfilled' | 'denied' | 'error';

export interface FetchParams {
  url: UrlString;
  headers?: HeaderRecord;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /** Extra budget context from the caller, merged under broker policy. */
  budgetOverride?: { perCallCeilingMicros?: number; lineItemCeilingMicros?: number };
}

export type RslClauseType =
  | 'attribution'
  | 'no-store'
  | 'no-derivative-works'
  | 'no-commercial-use'
  | 'pay-per-inference'
  | 'redistribution'
  | (string & {});

export type RslClauseValue = 'required' | 'permitted' | 'forbidden' | number;

export interface RslClause {
  type: string;
  value: RslClauseValue;
  params: Record<string, string | number>;
}

/** A parsed Rights Statement Language (RSL) document. */
export interface License {
  draft: string;
  id: string;
  title?: string;
  publishedAt?: string;
  clauses: RslClause[];
  rawSource: string;
}

/**
 * Obligations the broker derives from a license and enforces/surfaces for
 * this particular fetch. Surfaced in the outcome so the caller can comply.
 */
export interface LicenseObligation {
  clause: string;
  kind: 'notice' | 'store-prohibited' | 'inference-budget' | 'forbidden' | 'permitted';
  instruction: string;
  applied?: string;
}

export interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  /** Opaque PACT-style attestation token where the origin accepts one. */
  pactToken?: string;
}

export interface FetchOutcome {
  fetchId: string;
  status: FetchStatus;
  /** Present iff status !== 'fulfilled'. The three distinct failure classes. */
  failureClass?: FailureClass;
  reason: string;
  origin?: { url: string; httpStatus?: number };
  content?: { body: string; contentType: string; storeable: boolean; attributionNotice?: string };
  license?: License;
  obligations?: LicenseObligation[];
  price?: Price;
  quote?: Quote;
  rail?: string;
  settlementRef?: string;
  identity?: IdentityPresentation;
  tenantId?: string;
  timestamps: { startedAt: string; completedAt: string };
  error?: { code: string; message: string };
  /**
   * Finality of a fulfilled fetch. `'final'` iff the fulfillment was
   * reconciliation-clean (reconcile().ok === true) — the settlement is proven,
   * not merely attempted. A fulfilled-but-not-yet-final fetch is `'claimed'`,
   * so callers never bet real settlement on an assumption.
   */
  finality?: 'claimed' | 'final';
}

/** A raw ledger row — the audit surface. */
export interface LedgerEntry {
  seq: number;
  fetchId: string;
  tenantId: string;
  url: string;
  status: FetchStatus;
  failureClass?: FailureClass;
  httpStatus?: number;
  priceMicros?: number;
  currency?: string;
  rail?: string;
  licenseId?: string;
  keyId?: string;
  settlementRef?: string;
  startedAt: string;
  completedAt: string;
  recordedAt: string;
}

/**
 * A payment rail: one interface, pluggable backends.
 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
 * The interface is stable; backend field names are not (draft-caveat discipline).
 */
export interface PaymentRequest {
  url: UrlString;
  method: string;
  headers: HeaderRecord;
  contentType?: string;
}

export interface RailAuthorization {
  /** Headers the origin expects on the settled request (e.g. X-PAYMENT). */
  settlementHeaders: HeaderRecord;
  scheme: string;
  payload: string;
}

export interface RailSettlement {
  rail: string;
  settlementRef: string;
  amountMicros: number;
  currency: string;
  settledAt: string;
}

export interface PaymentRail {
  readonly id: string;
  quote(req: PaymentRequest): Promise<Quote>;
  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
}

import { describe, expect, it } from 'vitest';
import { frozenClock, b64url, RailError } from '@mwb/core';
import type { Clock, PaymentRequest, UrlString } from '@mwb/core';
import {
  SelfHosted402Rail,
  SettlementServer,
  makeSelf402Rail,
  makeSettlementKey,
  buildMandate,
  verifyMandate,
  encodeXPayment,
  decodeXPayment,
  SettlementHttpServer,
} from '@mwb/rails';

const clock: Clock = frozenClock('2026-08-18T12:00:00.000Z');

const URL = 'https://api.example.com/data' as UrlString;
const REQ: PaymentRequest = { url: URL, method: 'GET', headers: {} };

/** Build a signed mandate under the given key. */
function mandate(
  key = makeSettlementKey(clock),
  override: Partial<{ amountMicros: number; issuedAt: string }> = {},
) {
  return buildMandate({
    origin: 'https://api.example.com',
    url: URL,
    amountMicros: 5000,
    currency: 'USD',
    recipient: key.keyId,
    clock,
    key,
    ...override,
  });
}

/** Encode a raw XPayment wire envelope (used to craft a wrong-shape value). */
function encodeEnvelope(x: unknown): string {
  return b64url(Buffer.from(JSON.stringify(x), 'utf8'));
}

describe('self-settlement: mandate sign / verify', () => {
  it('accepts a freshly signed mandate in the acceptance window', () => {
    const key = makeSettlementKey(clock);
    const m = mandate(key);
    expect(m.signature).toBeTruthy();
    const r = verifyMandate(m, key, { nowMs: Date.parse(clock.now()) });
    expect(r.valid).toBe(true);
    expect(r.reason).toBeUndefined();
  });

  it('rejects a mandate whose manifest was tampered', () => {
    const key = makeSettlementKey(clock);
    const m = mandate(key);
    const tampered = { ...m, amountMicros: 5001 };
    const r = verifyMandate(tampered, key, { nowMs: Date.parse(clock.now()) });
    expect(r.valid).toBe(false);
    expect(r.reason).toBe('signature-mismatch');
  });

  it('rejects a mandate signed by a different key', () => {
    const m = mandate(makeSettlementKey(clock));
    const other = makeSettlementKey(clock);
    const r = verifyMandate(m, other, { nowMs: Date.parse(clock.now()) });
    expect(r.valid).toBe(false);
    expect(r.reason).toBe('signature-mismatch');
  });

  it('rejects a missing signature', () => {
    const key = makeSettlementKey(clock);
    const m = mandate(key);
    delete m.signature;
    const r = verifyMandate(m, key, { nowMs: Date.parse(clock.now()) });
    expect(r.valid).toBe(false);
    expect(r.reason).toBe('missing-signature');
  });

  it('rejects a mandate issued outside the acceptance window', () => {
    const key = makeSettlementKey(clock);
    // A valid signature, but issued a day later — out of window.
    const m = mandate(key, { issuedAt: '2026-08-19T12:00:00.000Z' });
    const r = verifyMandate(m, key, { nowMs: Date.parse(clock.now()) });
    expect(r.valid).toBe(false);
    expect(r.reason).toBe('issued-out-of-window');
  });

  it('round-trips the x-payment header wire form', () => {
    const m = mandate();
    const wire = encodeXPayment(m);
    expect(wire).toMatch(/^[A-Za-z0-9_-]+$/); // base64url, no padding
    expect(decodeXPayment(wire)).toEqual(m);
  });

  it('throws on malformed or wrong-shape x-payment values', () => {
    expect(() => decodeXPayment('!!!not-base64url!!!')).toThrow(/malformed x-payment/i);
    // Correctly base64url-encoded, but with the wrong `type` in the envelope.
    const wire = encodeEnvelope({ type: 'urn:something-else', mandate: mandate() });
    expect(() => decodeXPayment(wire)).toThrow(/unknown x-payment shape/i);
  });
});

describe('self-settlement: SettlementServer commit + replay protection', () => {
  it('mints a chained receipt and rejects a replayed nonce', () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });

    const m = mandate(key);
    const first = server.settle(m);
    expect(first.rail).toBe('self402');
    expect(first.settlementRef).toMatch(/^settle_self402_/);
    expect(first.amountMicros).toBe(5000);
    expect(server.settledCount()).toBe(1);

    const ledger = server.ledger();
    const rec = ledger[0]!;
    expect(rec.seq).toBe(1);
    expect(rec.receipt.settlementRef).toBe(first.settlementRef);
    // A 64-byte Ed25519 signature encodes to 86 chars in base64url (no padding).
    expect(rec.signature.length).toBe(86);

    // A second settle of the SAME mandate is rejected as a replay:
    // non-retryable (the payment rail still demanding payment).
    let caught: RailError | undefined;
    try {
      server.settle(m);
    } catch (e) {
      caught = e as RailError;
    }
    expect(caught).toBeInstanceOf(RailError);
    expect(caught!.code).toBe('RAIL_SETTLE');
    expect(caught!.retryable).toBe(false);
    expect(caught!.message).toContain('replayed-proof');
    expect(server.settledCount()).toBe(1); // unchanged
  });

  it('chains multiple receipts in order, each signed', () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });

    const refs = new Set<string>();
    for (let i = 0; i < 3; i++) {
      const r = server.settle(mandate(key, { amountMicros: 5000 + i * 100 }));
      expect(refs.has(r.settlementRef)).toBe(false);
      refs.add(r.settlementRef);
    }
    const ledger = server.ledger();
    expect(ledger.map((r) => r.seq)).toEqual([1, 2, 3]);
    expect(ledger[1]!.signature).not.toBe(ledger[0]!.signature);
  });
});

describe('self-settlement: SelfHosted402Rail end-to-end', () => {
  it('quotes, authorizes (signed mandate), and settles over an in-process backend', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: 5000, clock, origin: REQ.url });

    const quote = await rail.quote(REQ);
    expect(quote.unitsMicros).toBe(5000);
    expect(quote.currency).toBe('USD');
    expect(quote.rail).toBe('self402');
    expect(quote.settlement).toBe('immediate');

    const auth = await rail.authorize(REQ, quote);
    // The authorize payload is the signed mandate...
    const mandate = JSON.parse(auth.payload) as ReturnType<typeof buildMandate>;
    expect(mandate.signature).toBeTruthy();
    // ...and the settlement header carries the x-payment wire form.
    expect(auth.settlementHeaders['x-payment']).toBeTruthy();

    const s = await rail.settle(REQ, auth);
    expect(s.rail).toBe('self402');
    expect(s.settlementRef).toMatch(/^settle_self402_/);
    expect(server.settledCount()).toBe(1);
  });

  it('rejects a settlement whose mandate url does not match the request', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: 5000, clock, origin: REQ.url });
    const quote = await rail.quote(REQ);
    const auth = await rail.authorize(REQ, quote);

    let caught: RailError | undefined;
    try {
      await rail.settle(
        { url: 'https://other.example.com/x' as UrlString, method: 'GET', headers: {} },
        auth,
      );
    } catch (e) {
      caught = e as RailError;
    }
    expect(caught).toBeInstanceOf(RailError);
    expect(caught!.code).toBe('RAIL_SETTLE');
    expect(caught!.message).toContain('does not match');
  });

  it('a replay over the rail path throws a non-retryable settle fault', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: 5000, clock, origin: REQ.url });
    const quote = await rail.quote(REQ);
    const auth = await rail.authorize(REQ, quote);

    await rail.settle(REQ, auth);
    let caught: RailError | undefined;
    try {
      await rail.settle(REQ, auth);
    } catch (e) {
      caught = e as RailError;
    }
    expect(caught).toBeInstanceOf(RailError);
    expect(caught!.retryable).toBe(false);
    expect(caught!.message).toContain('replayed-proof');
  });
});

// --- HTTP service layer -----------------------------------------------------

describe('self-settlement: SettlementHttpServer', () => {
  it('serves health, accept, settle, ledger, and 404 routes', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const http = new SettlementHttpServer(server);

    // health
    const h = await http.dispatch('GET', '/health');
    expect(h.status).toBe(200);
    expect((h.body as { status: string }).status).toBe('ok');
    expect((h.body as { settled: number }).settled).toBe(0);

    // accept (non-consuming) rejects a wrong-key mandate
    const wrongKeyMandate = mandate(makeSettlementKey(clock));
    const acc = await http.dispatch('POST', '/accept', JSON.stringify(wrongKeyMandate));
    expect(acc.status).toBe(402);
    expect((acc.body as { valid: boolean }).valid).toBe(false);

    // settle succeeds
    const m = mandate(key);
    const settle = await http.dispatch('POST', '/settle', JSON.stringify(m));
    expect(settle.status).toBe(200);
    const body = settle.body as { settlementRef: string };
    expect(body.settlementRef).toMatch(/^settle_self402_/);

    // ledger now holds one record
    const led = await http.dispatch('GET', '/ledger');
    expect(led.status).toBe(200);
    expect((led.body as { count: number }).count).toBe(1);
    expect((led.body as { records: { seq: number }[] }).records[0]!.seq).toBe(1);

    // unknown route -> 404
    const miss = await http.dispatch('GET', '/nope');
    expect(miss.status).toBe(404);
  });

  it('returns 402 on a replayed nonce over HTTP', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const http = new SettlementHttpServer(server);
    const m = mandate(key);
    const first = await http.dispatch('POST', '/settle', JSON.stringify(m));
    expect(first.status).toBe(200);

    const replay = await http.dispatch('POST', '/settle', JSON.stringify(m));
    expect(replay.status).toBe(402);
    expect((replay.body as { reason: string }).reason).toBe('replayed-proof');
  });
});
